INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7313897-306c-41dc-97e8-21e00f9f2453', '長安傷春', '长安傷春', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["霜隕中春花半無，狂遊恣飲盡兇徒。","年年賞翫公卿輩，今委溝塍骨漸枯。"]', '["霜隕中春花半無，狂游恣饮尽兇徒。","年年賞翫公卿輩，今委溝塍骨漸枯。"]', '诗', 'shi', '', NULL, '長安傷春 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588ebca2-06d2-4477-9a92-2191593a4abd', '河梁晚望二首 一', '河梁晚望二首 一', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["水勢滔滔不可量，漁舟容易泛滄浪。","連山翠靄籠沙溆，白鳥翩翩下夕陽。"]', '["水勢滔滔不可量，漁舟容易泛滄浪。","連山翠靄籠沙溆，白鸟翩翩下夕陽。"]', '诗', 'shi', '', NULL, '河梁晚望二首 一 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc03614-423e-45b0-80a0-499d2ce6cca9', '河梁晚望二首 二', '河梁晚望二首 二', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["雨添一夜秋濤闊，極目茫茫似接天。","不知龍物潛何處，魚躍蛙鳴滿檻前。"]', '["雨添一夜秋濤闊，極目茫茫似接天。","不知龙物潛何处，鱼躍蛙鳴满檻前。"]', '诗', 'shi', '', NULL, '河梁晚望二首 二 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d45b28-57c9-469e-8e93-ddc41b21638f', '悲長安', '悲长安', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["何事天時禍未回，生靈愁悴苦寒灰。","豈知萬傾繁華地，強半今爲瓦礫堆。"]', '["何事天时禍未回，生靈愁悴苦寒灰。","豈知万傾繁华地，強半今爲瓦礫堆。"]', '诗', 'shi', '', NULL, '悲長安 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31fe5c69-8234-4aaa-95b8-7bf4cc573f59', '千葉石榴花', '千葉石榴花', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["一朵花開千葉紅，開時又不藉春風。","若教移在香閨畔，定與佳人豔態同。"]', '["一朵花开千葉紅，开时又不藉春风。","若教移在香閨畔，定與佳人豔態同。"]', '诗', 'shi', '', NULL, '千葉石榴花 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07a74718-94be-41f9-a43a-5c30490492f1', '觀碁', '观碁', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["拂局盡消時，能因長路遲。","點頭初得計，格手待無疑。","寂默親遺景，凝神入過思。","共藏多少意，不語兩相知。"]', '["拂局尽消时，能因长路遲。","点头初得計，格手待無疑。","寂默親遺景，凝神入過思。","共藏多少意，不語兩相知。"]', '诗', 'shi', '', NULL, '觀碁 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('794a36dc-408d-4cb2-9ee9-410252190a87', '山居', '山居', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["雪消春力展，花漫洞門垂。","果長纖枝曲，巖崩直道移。","重猿圍淺井，鬬鼠下疎籬。","寒食微燈在，高風勢徹陂。"]', '["雪消春力展，花漫洞门垂。","果长纖枝曲，巖崩直道移。","重猿圍淺井，鬬鼠下疎籬。","寒食微灯在，高风勢徹陂。"]', '诗', 'shi', '', NULL, '山居 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('831233b2-5900-4cf5-a7e3-7bdb5913f9f4', '贈樊川長老', '贈樊川长老', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["瘦顏顴骨見，滿面雪毫垂。","坐石鳥疑死，出門人謂癡。","照身潭入楚，浸影檜生隋。","太白曾經夏，清風涼四肢。"]', '["瘦顏顴骨见，满面雪毫垂。","坐石鸟疑死，出门人謂癡。","照身潭入楚，浸影檜生隋。","太白曾經夏，清风涼四肢。"]', '诗', 'shi', '', NULL, '贈樊川長老 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c822084a-85dc-480d-913e-bd07cb3d1fab', '寄積麥山會如長老', '寄積麦山會如长老', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["默然如大道，塵世不相關。","青檜行時靜，白雲禪處閑。","貧高一生行，病長十年顏。","夏滿期游寺，尋山又下山。"]', '["默然如大道，塵世不相关。","青檜行时静，白云禪处闲。","貧高一生行，病长十年顏。","夏满期游寺，尋山又下山。"]', '诗', 'shi', '', NULL, '寄積麥山會如長老 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc170b63-78c7-413b-b7d1-83179175a4a1', '送僧', '送僧', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["四海無拘繫，行心興自濃。","百年三事衲，萬里一枝筇。","夜減當晴影，春消過雪蹤。","白雲深處去，知宿在何峰。"]', '["四海無拘繫，行心兴自濃。","百年三事衲，万里一枝筇。","夜減當晴影，春消過雪蹤。","白云深处去，知宿在何峰。"]', '诗', 'shi', '', NULL, '送僧 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1eca9f1-86ca-4c2f-b641-02069a104bb3', '哭賈島', '哭賈島', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["燕生松雪地，蜀死葬山根。","詩僻降今古，官卑悞子孫。","塚欄寒月色，人哭苦吟魂。","墓雨滴碑字，年年添蘚痕。"]', '["燕生松雪地，蜀死葬山根。","诗僻降今古，官卑悞子孫。","塚欄寒月色，人哭苦吟魂。","墓雨滴碑字，年年添蘚痕。"]', '诗', 'shi', '', NULL, '哭賈島 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04cf4c7-c3ca-4857-b268-9e2fb2391dff', '雪十二韻', '雪十二韻', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["落處咸過尺，翛然物象淒。","瑞凝金殿上，寒甚玉關西。","潤比江河普，明將日月齊。","凌雲花頂膩，鎖徑竹梢低。","出谷樵童怯，歸林野鳥迷。","煮茶融破練，磨墨染成黳。","陷兔埋平澤，和魚凍合溪。","入樓消酒力，當檻寫詩題。","道路依憑馬，朝昏委託雞。","洞深猿作族，松亞鶴移棲。","及夏清巖穴，經春溜石梯。","豐年兼泰國，天道育黔黎。"]', '["落处咸過尺，翛然物象淒。","瑞凝金殿上，寒甚玉关西。","潤比江河普，明將日月齊。","凌云花頂膩，鎖徑竹梢低。","出谷樵童怯，归林野鸟迷。","煮茶融破練，磨墨染成黳。","陷兔埋平澤，和鱼凍合溪。","入楼消酒力，當檻寫诗題。","道路依憑马，朝昏委託雞。","洞深猿作族，松亞鹤移棲。","及夏清巖穴，經春溜石梯。","豐年兼泰国，天道育黔黎。"]', '诗', 'shi', '', NULL, '雪十二韻 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e32dfd5-c43d-4e56-8328-e102a0290bb8', '精舍遇雨', '精舍遇雨', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["空門寂寂淡吾身，溪雨微微洗客塵。","臥向白雲情未盡，任他黃鳥醉芳春。"]', '["空门寂寂淡吾身，溪雨微微洗客塵。","臥向白云情未尽，任他黄鸟醉芳春。"]', '诗', 'shi', '', NULL, '精舍遇雨 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40e1b88-3fed-40e0-a447-5d78cf8cc53e', '小雪', '小雪', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["落雪臨風不厭看，更多還恐蔽林巒。","愁人正在書窗下，一片飛來一片寒。"]', '["落雪臨风不厭看，更多還恐蔽林巒。","愁人正在书窗下，一片飞来一片寒。"]', '诗', 'shi', '', NULL, '小雪 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8a4158c-053c-4017-9202-797c61f525c9', '送婆羅門僧', '送婆羅门僧', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["雪嶺金河獨向東，吳山楚澤意無窮。","如今白首鄉心盡，萬里歸程在夢中。"]', '["雪嶺金河独向东，吳山楚澤意無窮。","如今白首乡心尽，万里归程在梦中。"]', '诗', 'shi', '', NULL, '送婆羅門僧 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52697b5a-c4dd-4dd1-b262-cb7472e8f4e4', '句', '句', '854766b0-51c1-46dd-bcd1-114b0baa7b17', '唐', '["不知誰會喃喃語，必向王前報太平。"]', '["不知誰會喃喃語，必向王前報太平。"]', '诗', 'shi', '', NULL, '句 可止 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bfdf075-5a65-4b2b-8839-3d919df4049e', '寒食日', '寒食日', '2c29326f-14f0-42a0-bdbc-77d51acd128f', '唐', '["寒食悲看郭外春，野田無處不傷神。","平原纍纍添新塚，半是去年來哭人。"]', '["寒食悲看郭外春，野田無处不傷神。","平原纍纍添新塚，半是去年来哭人。"]', '诗', 'shi', '', NULL, '寒食日 雲表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6064a784-aff3-455e-aa4d-b95dcbfccfcd', '自遣', '自遣', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["日日爲詩苦，誰論春與秋。","一聯如得意，萬事總忘憂。","雨墮花臨砌，風吹竹近樓。","不吟頭也白，任白此生頭。"]', '["日日爲诗苦，誰論春與秋。","一聯如得意，万事總忘憂。","雨墮花臨砌，风吹竹近楼。","不吟头也白，任白此生头。"]', '诗', 'shi', '', NULL, '自遣 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54e63514-fd37-4d2c-bc84-cdd9bdf10efe', '酬沈先輩卷', '酬沈先輩卷', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["一百八十首，清泠韻可敲。","任從人不愛，終是我難拋。","桂魄吟來滿，蒲團坐得凹。","先生聲價在，寰宇幾人抄。"]', '["一百八十首，清泠韻可敲。","任從人不愛，終是我难拋。","桂魄吟来满，蒲團坐得凹。","先生声價在，寰宇幾人抄。"]', '诗', 'shi', '', NULL, '酬沈先輩卷 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e59aed37-0336-4982-96bd-a1bd468312ed', '題賈島吟詩臺', '題賈島吟诗台', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["此臺如可廢，此恨有誰平。","縱使迷青草，終難沒舊名。","天悲朝雨色，嶽哭夜猨聲。","不是心偏苦，應關自古情。"]', '["此台如可廢，此恨有誰平。","縱使迷青草，終难沒旧名。","天悲朝雨色，嶽哭夜猨声。","不是心偏苦，應关自古情。"]', '诗', 'shi', '', NULL, '題賈島吟詩臺 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2276a29-70ae-4179-9325-8a8c3a7d2052', '悼羅隱', '悼羅隐', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["一著讒書未快心，幾抽胸臆縱狂吟。","管中窺豹我猶在，海上釣鼇君也沈。","歲月盡能消憤懣，寰區那更有知音。","長安冠蓋皆塗地，仍喜先生葬碧岑。"]', '["一著讒书未快心，幾抽胸臆縱狂吟。","管中窺豹我猶在，海上釣鼇君也沈。","歲月尽能消憤懣，寰區那更有知音。","长安冠蓋皆塗地，仍喜先生葬碧岑。"]', '诗', 'shi', '', NULL, '悼羅隱 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b886bb24-4cb6-4caa-8d4a-bbee62c48944', '題楚廟', '題楚廟', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["羞容難更返江東，誰問從來百戰功。","天地有心歸道德，山河無力爲英雄。","蘆花尚認霜戈白，海日猶思火陣紅。","也是男兒成敗事，不須惆悵對西風。"]', '["羞容难更返江东，誰问從来百戰功。","天地有心归道德，山河無力爲英雄。","蘆花尚認霜戈白，海日猶思火陣紅。","也是男兒成敗事，不須惆悵对西风。"]', '诗', 'shi', '', NULL, '題楚廟 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ecba7c-69b7-40ae-862e-10df1182e9ec', '牡丹', '牡丹', '6c19abf0-ae6e-4d9d-9c83-af5102566a48', '唐', '["三春堪惜牡丹奇，半倚朱欄欲綻時。","天上更無花勝此，人間偏得貴相宜。","偷香黑蟻斜穿葉，覷蕋黃蜂倒挂枝。","除却解禪心不動，算應狂殺五陵兒。"]', '["三春堪惜牡丹奇，半倚朱欄欲綻时。","天上更無花勝此，人间偏得貴相宜。","偷香黑蟻斜穿葉，覷蕋黄蜂倒挂枝。","除却解禪心不动，算應狂殺五陵兒。"]', '诗', 'shi', '', NULL, '牡丹 歸仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55f3f89-6ae3-400c-8f90-5288a425c01e', '舊國里', '旧国里', '52bdd918-15e2-4d93-b9d5-6187b9b59d7e', '唐', '["舊居梨嶺下，風景近炎方。","地暖生春早，家貧覺歲長。","石房雲過濕，杉徑雨餘香。","日夕竟無事，詩書聊自強。"]', '["旧居梨嶺下，风景近炎方。","地暖生春早，家貧覺歲长。","石房云過濕，杉徑雨餘香。","日夕竟無事，诗书聊自強。"]', '诗', 'shi', '', NULL, '舊國里 卿雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b492836-6c41-44e0-bdcd-4688fd62e9f1', '秋日江居閑詠', '秋日江居闲詠', '52bdd918-15e2-4d93-b9d5-6187b9b59d7e', '唐', '["寄居江島邊，閑詠見秋殘。","草白牛羊瘦，風高猨鳥寒。","檢方醫故疾，挑薺備中餐。","時復停書卷，鉏莎種木蘭。"]', '["寄居江島邊，闲詠见秋殘。","草白牛羊瘦，风高猨鸟寒。","檢方醫故疾，挑薺備中餐。","时复停书卷，鉏莎種木蘭。"]', '诗', 'shi', '', NULL, '秋日江居閑詠 卿雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f49ed0f5-5a9d-443c-9c23-3ec93a8b126b', '長安言懷寄沈彬侍郎', '长安言懷寄沈彬侍郎', '52bdd918-15e2-4d93-b9d5-6187b9b59d7e', '唐', '["故園梨嶺下，歸路接天涯。","生作長安草，勝爲邊地花。","雁南飛不到，書北寄來賒。","堪羨神仙客，青雲早致家。"]', '["故园梨嶺下，归路接天涯。","生作长安草，勝爲邊地花。","雁南飞不到，书北寄来賒。","堪羨神仙客，青云早致家。"]', '诗', 'shi', '', NULL, '長安言懷寄沈彬侍郎 卿雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca192c09-7183-4004-a9e7-a2c8a91637ac', '送人游塞', '送人游塞', '52bdd918-15e2-4d93-b9d5-6187b9b59d7e', '唐', '["去去玉關路，省君曾未行。","塞深多伏寇，時靜亦屯兵。","雪每先秋降，花嘗近夏生。","閑陪射鵰將，應到受降城。"]', '["去去玉关路，省君曾未行。","塞深多伏寇，时静亦屯兵。","雪每先秋降，花嘗近夏生。","闲陪射鵰將，應到受降城。"]', '诗', 'shi', '', NULL, '送人游塞 卿雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9b0630-2932-4e64-afad-366367d9201f', '逢老人', '逢老人', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["路逢一老翁，兩鬢白如雪。","一里二里行，四回五回歇。"]', '["路逢一老翁，兩鬢白如雪。","一里二里行，四回五回歇。"]', '诗', 'shi', '', NULL, '逢老人 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99cf0dd4-56f4-48f9-979b-05558e97b4ee', '牧童', '牧童', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["牧童見人俱不識，盡着芒鞋戴篛笠。","朝陽未出衆山晴，露滴蓑衣猶半濕。","二月三月時，平原草初綠。","三箇五箇騎羸牛，前村後村來放牧。","笛聲纔一舉，衆稚齊歌舞。","看看白日向西斜，各自騎牛又歸去。"]', '["牧童见人俱不識，尽着芒鞋戴篛笠。","朝陽未出衆山晴，露滴蓑衣猶半濕。","二月三月时，平原草初綠。","三箇五箇騎羸牛，前村後村来放牧。","笛声纔一舉，衆稚齊歌舞。","看看白日向西斜，各自騎牛又归去。"]', '诗', 'shi', '', NULL, '牧童 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('172df690-65db-4eda-ae51-400f32781388', '蜀中送人游廬山', '蜀中送人游廬山', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["居游正值芳春月，蜀道千山皆秀發。","溪邊十里五里花，雲外三峯兩峰雪。","君上匡山我舊居，松蘿拋擲十年餘。","君行試到山前問，山鳥只今相憶無。"]', '["居游正值芳春月，蜀道千山皆秀發。","溪邊十里五里花，云外三峯兩峰雪。","君上匡山我旧居，松蘿拋擲十年餘。","君行試到山前问，山鸟只今相憶無。"]', '诗', 'shi', '', NULL, '蜀中送人游廬山 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b755be-7e12-4d78-adb2-c321d591ba37', '琴', '琴', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["七條絲上寄深意，澗水松風生十指。","自乃知音猶尚稀，欲教更入何人耳。"]', '["七條絲上寄深意，澗水松风生十指。","自乃知音猶尚稀，欲教更入何人耳。"]', '诗', 'shi', '', NULL, '琴 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ae4da07-3bcd-4a8d-b64d-bb1f3c05e6f7', '浮橋', '浮橋', 'f7e09dcf-f215-4cb3-842e-fd71b2abc49f', '唐', '["橫壓驚波防沒溺，當初元剏是軍機。","行人到此全無滯，一片江雲踏欲飛。"]', '["橫壓驚波防沒溺，當初元剏是軍機。","行人到此全無滯，一片江云踏欲飞。"]', '诗', 'shi', '', NULL, '浮橋 隱巒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f55c11b-e673-49e6-a099-8c374336da3a', '宿九華化成寺莊', '宿九华化成寺莊', 'e82f382a-cb8a-4db2-9c2c-cc5d399c0b37', '唐', '["佛寺孤莊千嶂間，我來詩境強相關。","巖邊樹動猿下澗，雲裏錫鳴僧上山。","松月影寒生碧落，石泉聲亂噴潺湲。","明朝更躡層霄去，誓共煙霞到老閑。"]', '["佛寺孤莊千嶂间，我来诗境強相关。","巖邊樹动猿下澗，云裏錫鳴僧上山。","松月影寒生碧落，石泉声亂噴潺湲。","明朝更躡層霄去，誓共煙霞到老闲。"]', '诗', 'shi', '', NULL, '宿九華化成寺莊 泠然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0ec11d-6088-4069-af03-8e2c153fe9ec', '乞荆浩畫', '乞荆浩畫', 'f8685507-c865-4c58-a45d-38f2cf5f0118', '唐', '["六幅故牢健，知君恣筆蹤。","不求千澗水，止要兩株松。","樹下留盤石，天邊縱遠峰。","近巖幽濕處，惟藉墨煙濃。"]', '["六幅故牢健，知君恣笔蹤。","不求千澗水，止要兩株松。","樹下留盤石，天邊縱远峰。","近巖幽濕处，惟藉墨煙濃。"]', '诗', 'shi', '', NULL, '乞荆浩畫 大愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c591cbbd-4b6d-4284-a265-d29ffb1db9b4', '上歸州刺史代通狀二首 一', '上归州刺史代通狀二首 一', '6e6cdfff-831a-4e35-9886-70898c3c47f9', '唐', '["家在閩山西復西，其中歲歲有鶯啼。","如今不在鶯啼處，鶯在舊時啼處啼。"]', '["家在閩山西复西，其中歲歲有鶯啼。","如今不在鶯啼处，鶯在旧时啼处啼。"]', '诗', 'shi', '', NULL, '上歸州刺史代通狀二首 一 懷濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c3cd1a-2451-49f5-8361-0d2be7c68086', '上歸州刺史代通狀二首 二', '上归州刺史代通狀二首 二', '6e6cdfff-831a-4e35-9886-70898c3c47f9', '唐', '["家在閩山東復東，其中歲歲有花紅。","而今不在花紅處，花在舊時紅處紅。"]', '["家在閩山东复东，其中歲歲有花紅。","而今不在花紅处，花在旧时紅处紅。"]', '诗', 'shi', '', NULL, '上歸州刺史代通狀二首 二 懷濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b0c92d7-03f5-4547-9770-f7026d3cdfd7', '辭郡守李公恩命', '辞郡守李公恩命', '7516bc59-5ca5-479b-a60f-62d75f6ab6a5', '唐', '["虛著褐衣老，浮杯道不成。","誓傳經論死，不染利名生。","厭樹遮山色，憐窗向月明。","他時隨范蠡，一棹五湖清。"]', '["虛著褐衣老，浮杯道不成。","誓傳經論死，不染利名生。","厭樹遮山色，怜窗向月明。","他时隨范蠡，一棹五湖清。"]', '诗', 'shi', '', NULL, '辭郡守李公恩命 恆超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('215b4a08-7fe4-4c10-b855-17342878dd52', '題廣愛寺楞伽山', '題廣愛寺楞伽山', '4334ff57-a661-49df-98f5-d06776653ccd', '唐', '["靈異不能棲鳥雀，幽奇終不着猿猱。","爲經巢賊應無損，縱使秦驅也謾勞。","珍重昔賢留像迹，陵遷谷變自堅牢。"]', '["靈異不能棲鸟雀，幽奇終不着猿猱。","爲經巢賊應無損，縱使秦驱也謾勞。","珍重昔賢留像迹，陵遷谷变自堅牢。"]', '诗', 'shi', '', NULL, '題廣愛寺楞伽山 淨顯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dd9e156-d253-4450-832b-3a03672563e6', '聞誦法華經歌', '闻誦法华經歌', '74506a9e-05c5-4597-a990-3e1893ab3cdb', '唐', '["山色沈沈，松煙羃羃。","空林之下，盤陀之石。","石上有僧，結跏橫膝。","誦白蓮經，從旦至夕。","左之右之，虎跡狼跡。","十片五片，異花狼籍。","偶然相見，未深相識。","知是古之人，今之人？是曇彥，是曇翼？","我聞此經有深旨，覺帝稱之有妙義。","合目冥心子細聽，醍醐滴入焦腸裏。","佛之意兮祖之髓，我之心兮經之旨。","可憐彈指及舉手，不達目前今正是。","大矣哉！甚奇特。","空王要使羣生得，光輝一萬八千土。","土土皆作黃金色，四生六道一光中。","狂夫猶自問彌勒，我亦當年學空寂。","一得無心便休息，今日親聞誦此經。","始覺驢乘匪端的，我亦當年不出戶。","不欲紅塵沾步武，今日親聞誦此經。","始覺行行皆寶所，我亦當年愛吟詠。","將謂冥搜亂神定，今日親聞誦此經。","何妨筆硯資真性，我亦當年狎兒戲。","將謂光陰半虛棄，今日親聞誦此經。","始覺聚沙非小事，我昔曾游山與水。","將謂他山非故里，今日親聞誦此經。","始覺山河無寸地，我昔心猿未調伏。","常將金鎖虛拘束，今日親聞誦此經。","始覺無物爲拳拲，師誦此經經一字。","字字爛嚼醍醐味，醍醐之味珍且美。","不在脣，不在齒，只在勞生方寸裏。","師誦此經經一句，句句白牛親動步，白牛之步疾如風。","不在西，不在東，只在浮生日用中，日用不知一何苦。","酒之腸，飯之腑，長者揚聲喚不迴。","何異聾，何異瞽，世人之耳非不聰，耳聰特向經中聾。","世人之目非不明，目明特向經中盲。","合聰不聰，合明不明。","轆轤上下，浪死虛生。","世人縱識師之音，誰人能識師之心。","世人縱識師之形，誰人能識師之名。","師名醫王行佛令，來與衆生治心病。","能使迷者醒，狂者定，垢者淨，邪者正，凡者聖，如是則非但天恭敬。","人恭敬，亦合龍讚詠。","鬼讚詠，佛讚詠，豈得背覺合塵之徒，不稽首而歸命。"]', '["山色沈沈，松煙羃羃。","空林之下，盤陀之石。","石上有僧，結跏橫膝。","誦白蓮經，從旦至夕。","左之右之，虎跡狼跡。","十片五片，異花狼籍。","偶然相见，未深相識。","知是古之人，今之人？是曇彥，是曇翼？","我闻此經有深旨，覺帝稱之有妙義。","合目冥心子細听，醍醐滴入焦腸裏。","佛之意兮祖之髓，我之心兮經之旨。","可怜彈指及舉手，不達目前今正是。","大矣哉！甚奇特。","空王要使羣生得，光輝一万八千土。","土土皆作黄金色，四生六道一光中。","狂夫猶自问彌勒，我亦當年学空寂。","一得無心便休息，今日親闻誦此經。","始覺驢乘匪端的，我亦當年不出戶。","不欲紅塵沾步武，今日親闻誦此經。","始覺行行皆寶所，我亦當年愛吟詠。","將謂冥搜亂神定，今日親闻誦此經。","何妨笔硯資真性，我亦當年狎兒戲。","將謂光陰半虛棄，今日親闻誦此經。","始覺聚沙非小事，我昔曾游山與水。","將謂他山非故里，今日親闻誦此經。","始覺山河無寸地，我昔心猿未調伏。","常將金鎖虛拘束，今日親闻誦此經。","始覺無物爲拳拲，師誦此經經一字。","字字爛嚼醍醐味，醍醐之味珍且美。","不在脣，不在齒，只在勞生方寸裏。","師誦此經經一句，句句白牛親动步，白牛之步疾如风。","不在西，不在东，只在浮生日用中，日用不知一何苦。","酒之腸，飯之腑，长者揚声喚不迴。","何異聾，何異瞽，世人之耳非不聰，耳聰特向經中聾。","世人之目非不明，目明特向經中盲。","合聰不聰，合明不明。","轆轤上下，浪死虛生。","世人縱識師之音，誰人能識師之心。","世人縱識師之形，誰人能識師之名。","師名醫王行佛令，来與衆生治心病。","能使迷者醒，狂者定，垢者淨，邪者正，凡者聖，如是則非但天恭敬。","人恭敬，亦合龙讚詠。","鬼讚詠，佛讚詠，豈得背覺合塵之徒，不稽首而归命。"]', '诗', 'shi', '', NULL, '聞誦法華經歌 修雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c0acdd4-79dd-4f19-93ab-513eb1147024', '歌', '歌', '7e205ac6-06c9-4e65-8141-97a004edb159', '唐', '["酒禿酒禿，何榮何辱。","但見衣冠成古丘，不見江河變陵谷。"]', '["酒禿酒禿，何榮何辱。","但见衣冠成古丘，不见江河变陵谷。"]', '诗', 'shi', '', NULL, '歌 元寂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90776a02-e72a-479e-910c-e1f942e1e546', '懷廬山舊隱', '懷廬山旧隐', '28c09ddd-468b-42ed-93e2-38117c2196e0', '唐', '["九疊嵯峨倚着天，悔隨寒瀑下巖煙。","深秋猨鳥來心上，夜靜松杉到眼前。","書架想遭苔蘚[裹]，石窗應被薜蘿纏。","一枝筇竹游江北，不見爐峰二十年。"]', '["九叠嵯峨倚着天，悔隨寒瀑下巖煙。","深秋猨鸟来心上，夜静松杉到眼前。","书架想遭苔蘚[裹]，石窗應被薜蘿纏。","一枝筇竹游江北，不见爐峰二十年。"]', '诗', 'shi', '', NULL, '懷廬山舊隱 若虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ef5b32-b69e-4e24-a287-a2b4eca01ec9', '樂仙觀', '乐仙观', '28c09ddd-468b-42ed-93e2-38117c2196e0', '唐', '["樂氏騎龍上碧天，東吳遺宅尚依然。","悟來大道無多事，真後丹元不值錢。","老樹夜風蟲咬葉，古垣春雨蘚生甎。","松傾鶴死桑田變，華表歸鄉未有年。"]', '["乐氏騎龙上碧天，东吳遺宅尚依然。","悟来大道無多事，真後丹元不值錢。","老樹夜风蟲咬葉，古垣春雨蘚生甎。","松傾鹤死桑田变，华表归乡未有年。"]', '诗', 'shi', '', NULL, '樂仙觀 若虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e24966-b11c-4fbc-90ef-668d93bb0941', '古鏡', '古镜', '28c09ddd-468b-42ed-93e2-38117c2196e0', '唐', '["軒后紅爐獨鑄成，蘚痕磨落月輪呈。","萬般物象皆能鑒，一箇人心不可明。","匣內乍開鸞鳳活，臺前高挂鬼神驚。","百年肝膽堪將比，祗怕看頻素髮生。"]', '["軒后紅爐独鑄成，蘚痕磨落月輪呈。","万般物象皆能鑒，一箇人心不可明。","匣內乍开鸾鳳活，台前高挂鬼神驚。","百年肝膽堪將比，祗怕看頻素髮生。"]', '诗', 'shi', '', NULL, '古鏡 若虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7757e0-0967-4fd6-b6bb-ff98f4724b3e', '覩木平和尚', '覩木平和尚', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["木平山裏人，貌古年復少。","相看陌路同，論心秋月皎。","懷衲線非蠶，助歌聲有鳥。","城闕今日來，一謳曾已曉。"]', '["木平山裏人，貌古年复少。","相看陌路同，論心秋月皎。","懷衲線非蠶，助歌声有鸟。","城闕今日来，一謳曾已晓。"]', '诗', 'shi', '', NULL, '覩木平和尚 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085b5c16-f6f9-4495-8b0c-c404dda4d477', '鷺鷥', '鷺鷥', '1e892bb0-46c4-47a3-9f2b-5d46a9f5cecf', '唐', '["白蘋紅蓼碧江涯，日暖雙雙立睡時。","願揭金籠放歸去，却隨沙鶴鬬輕絲。"]', '["白蘋紅蓼碧江涯，日暖雙雙立睡时。","願揭金籠放归去，却隨沙鹤鬬轻絲。"]', '诗', 'shi', '', NULL, '鷺鷥 无則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af717420-b906-41ab-9bac-9837855b5a21', '百舌鳥二首 一', '百舌鸟二首 一', '1e892bb0-46c4-47a3-9f2b-5d46a9f5cecf', '唐', '["千愁萬恨過花時，似向春風怨別離。","若使衆禽俱解語，一生懷抱有誰知。"]', '["千愁万恨過花时，似向春风怨別離。","若使衆禽俱解語，一生懷抱有誰知。"]', '诗', 'shi', '', NULL, '百舌鳥二首 一 无則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46fa6fc6-61d8-478a-ae84-429cf9a4871a', '百舌鳥二首 二', '百舌鸟二首 二', '1e892bb0-46c4-47a3-9f2b-5d46a9f5cecf', '唐', '["長截隣雞叫五更，數般名字百般聲。","饒伊搖舌先知曉，也待青天明即鳴。"]', '["长截隣雞叫五更，數般名字百般声。","饒伊搖舌先知晓，也待青天明即鳴。"]', '诗', 'shi', '', NULL, '百舌鳥二首 二 无則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37fc7daa-d7c5-4df1-b273-24422a525b47', '賞牡丹應教', '賞牡丹應教', '9a78354d-6bc4-4ba7-962b-d567e15e28c9', '唐', '["擁衲對芳叢，由來事不同。","鬢從今日白，花似去年紅。","豔異隨朝露，馨香逐曉風。","何須對零落，然後始知空。"]', '["擁衲对芳叢，由来事不同。","鬢從今日白，花似去年紅。","豔異隨朝露，馨香逐晓风。","何須对零落，然後始知空。"]', '诗', 'shi', '', NULL, '賞牡丹應教 謙光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7d5078-a898-4787-85d7-35afd4e4a650', '善哉行', '善哉行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["有美一人兮，婉如青揚。","識曲別音兮，令姿煌煌。","繡袂捧琴兮，登君子堂。","如彼萱草兮，使我憂忘。","欲贈之以紫玉尺，白銀鐺，久不見之兮，湘水茫茫。"]', '["有美一人兮，婉如青揚。","識曲別音兮，令姿煌煌。","繡袂捧琴兮，登君子堂。","如彼萱草兮，使我憂忘。","欲贈之以紫玉尺，白銀鐺，久不见之兮，湘水茫茫。"]', '诗', 'shi', '', NULL, '善哉行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa627ae-9d13-495c-a5f5-82822db1d81c', '讀離騷經', '读離騷經', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["湘江濱，湘江濱，蘭紅芷白波如銀，終須一去呼湘君。","問湘神，雲中君，不知何以交靈均。","我恐湘江之魚兮，死後盡爲人。","曾食靈均之肉兮，箇箇爲忠臣。","又想靈均之骨兮終不曲，千年波底色如玉。","誰能入水少取得，香沐函題貢上國。","貢上國，即全勝和璞懸瓈，垂棘結綠。"]', '["湘江濱，湘江濱，蘭紅芷白波如銀，終須一去呼湘君。","问湘神，云中君，不知何以交靈均。","我恐湘江之鱼兮，死後尽爲人。","曾食靈均之肉兮，箇箇爲忠臣。","又想靈均之骨兮終不曲，千年波底色如玉。","誰能入水少取得，香沐函題貢上国。","貢上国，即全勝和璞懸瓈，垂棘結綠。"]', '诗', 'shi', '', NULL, '讀離騷經 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4032c0aa-68d2-4b62-b842-a92ae3fec730', '陽春曲', '陽春曲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["爲口莫學阮嗣宗，不言是非非至公。","爲手須似朱雲輩，折檻英風至今在。","男兒結髮事君親，須斅前賢多慷慨。","歷數雍熙房與杜，魏公姚公宋開府。","盡向天上仙宮閑處坐，何不却辭上帝下下土？","忍見蒼生苦苦苦。"]', '["爲口莫学阮嗣宗，不言是非非至公。","爲手須似朱云輩，折檻英风至今在。","男兒結髮事君親，須斅前賢多慷慨。","歷數雍熙房與杜，魏公姚公宋开府。","尽向天上仙宮闲处坐，何不却辞上帝下下土？","忍见蒼生苦苦苦。"]', '诗', 'shi', '', NULL, '陽春曲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6c811cb-96d9-457c-98ec-4f68ef2eb3a1', '白雪曲', '白雪曲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["列鼎佩金章，淚眼看風枝。","却思食藜藿，身作屠沽兒。","負米無遠近，所希升斗歸。","爲人無貴賤，莫學雞狗肥。","斯言如不忘，別更無光輝。","斯言如或忘，即安用人爲。"]', '["列鼎佩金章，泪眼看风枝。","却思食藜藿，身作屠沽兒。","負米無远近，所希升斗归。","爲人無貴賤，莫学雞狗肥。","斯言如不忘，別更無光輝。","斯言如或忘，即安用人爲。"]', '诗', 'shi', '', NULL, '白雪曲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9751674d-2434-4234-8179-d1119fe16e52', '上留田', '上留田', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["父不父，兄不兄。","上留田，蝥賊生。","徒陟岡，淚崢嶸。","我欲使諸凡鳥雀，盡變爲鶺鴒。","我欲使諸凡草木，盡變爲田荆。","鄰人歌，鄰人歌。","古風清，清風生。"]', '["父不父，兄不兄。","上留田，蝥賊生。","徒陟岡，泪崢嶸。","我欲使諸凡鸟雀，尽变爲鶺鴒。","我欲使諸凡草木，尽变爲田荆。","鄰人歌，鄰人歌。","古风清，清风生。"]', '诗', 'shi', '', NULL, '上留田 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8374980-3b6d-420c-9afd-1fa79cf5af51', '胡無人', '胡無人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["霍嫖姚，趙充國，天子將之平朔漠。","肉胡之肉，燼胡帳幄。","千里萬里，唯留胡之空殼。","邊風蕭蕭，榆葉初落。","殺氣晝赤，枯骨夜哭。","將軍既立殊勳，遂有胡無人曲。","我聞之，天子富有四海。","德被無垠，但令一物得所。","八表來賓，亦何必令彼胡無人。"]', '["霍嫖姚，趙充国，天子將之平朔漠。","肉胡之肉，燼胡帳幄。","千里万里，唯留胡之空殼。","邊风蕭蕭，榆葉初落。","殺氣晝赤，枯骨夜哭。","將軍既立殊勳，遂有胡無人曲。","我闻之，天子富有四海。","德被無垠，但令一物得所。","八表来賓，亦何必令彼胡無人。"]', '诗', 'shi', '', NULL, '胡無人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342bf50e-e7b2-453f-8b63-69adf2491ce0', '苦寒行', '苦寒行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["北風北風，職何嚴毒。","摧壯士心，縮金烏足。","凍雲囂囂，礙雪一片下不得。","聲遶枯桑，根在沙塞。","黃河徹底，頑直到海。","一氣摶束，萬物無態。","唯有吾庭前杉松樹枝，枝枝健在。"]', '["北风北风，職何嚴毒。","摧壯士心，縮金烏足。","凍云囂囂，礙雪一片下不得。","声遶枯桑，根在沙塞。","黄河徹底，頑直到海。","一氣摶束，万物無態。","唯有吾庭前杉松樹枝，枝枝健在。"]', '诗', 'shi', '', NULL, '苦寒行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('934195d8-7c49-4757-8b7e-20835be1de86', '蒿里', '蒿里', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["兔不遲，烏更急，但恐穆王八駿，著鞭不及。","所以蒿里，墳出蕺蕺。","氣凌雲天，龍騰鳳集。","盡爲風消土喫，狐掇蟻拾，黃金不啼玉不泣。","白楊騷屑，亂風愁月。","折碑石人，莽穢榛沒。","牛羊窸窣，時見牧童兒，弄枯骨。"]', '["兔不遲，烏更急，但恐穆王八駿，著鞭不及。","所以蒿里，墳出蕺蕺。","氣凌云天，龙腾鳳集。","尽爲风消土喫，狐掇蟻拾，黄金不啼玉不泣。","白楊騷屑，亂风愁月。","折碑石人，莽穢榛沒。","牛羊窸窣，时见牧童兒，弄枯骨。"]', '诗', 'shi', '', NULL, '蒿里 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc985d9-c158-4b44-a138-0a84046ad574', '臨高臺', '臨高台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["涼風吹遠念，使我升高臺。","寧知數片雲，不是舊山來。","故人天一涯，久客殊未回。","鴈來不得書，空寄聲哀哀。"]', '["涼风吹远念，使我升高台。","寧知數片云，不是旧山来。","故人天一涯，久客殊未回。","鴈来不得书，空寄声哀哀。"]', '诗', 'shi', '', NULL, '臨高臺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0643fb8d-f9d3-43fd-afdd-af860fe2e781', '杞梁妻', '杞梁妻', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["秦之無道兮四海枯，築長城兮遮北胡。","築人築土一萬里，杞梁貞婦啼嗚嗚。","上無父兮中無夫，下無子兮孤復孤。","一號城崩塞色苦，再號杞梁骨出土。","疲魂飢魄相逐歸，陌上少年莫相非。"]', '["秦之無道兮四海枯，築长城兮遮北胡。","築人築土一万里，杞梁貞婦啼嗚嗚。","上無父兮中無夫，下無子兮孤复孤。","一號城崩塞色苦，再號杞梁骨出土。","疲魂飢魄相逐归，陌上少年莫相非。"]', '诗', 'shi', '', NULL, '杞梁妻 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9b1423-886f-4131-98d9-9485b423774a', '古離別', '古離別', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["離恨如旨酒，古今飲皆醉。","只恐長江水，盡是兒女淚。","伊余非此輩，送人空把臂。","他日再相逢，清風動天地。"]', '["離恨如旨酒，古今饮皆醉。","只恐长江水，尽是兒女泪。","伊余非此輩，送人空把臂。","他日再相逢，清风动天地。"]', '诗', 'shi', '', NULL, '古離別 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18303e0-3fd6-4d77-b32a-de7c0a81785d', '戰城南二首 一', '戰城南二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬里桑乾傍，茫茫古蕃壤。","將軍貌憔悴，撫劍悲年長。","胡兵尚陵逼，久住亦非強。","邯鄲少年輩，箇箇有伎倆。","拖槍半夜去，雪片大如掌。"]', '["万里桑乾傍，茫茫古蕃壤。","將軍貌憔悴，撫劍悲年长。","胡兵尚陵逼，久住亦非強。","邯鄲少年輩，箇箇有伎倆。","拖槍半夜去，雪片大如掌。"]', '诗', 'shi', '', NULL, '戰城南二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f8a792-07da-4cb7-b73d-cbd827fbef17', '戰城南二首 二', '戰城南二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["磧中有陰兵，戰馬時驚蹶。","輕猛李陵心，摧殘蘇武節。","黃金鎖子甲，風吹色如鐵。","十載不封侯，茫茫向誰說。"]', '["磧中有陰兵，戰马时驚蹶。","轻猛李陵心，摧殘蘇武節。","黄金鎖子甲，风吹色如鐵。","十載不封侯，茫茫向誰说。"]', '诗', 'shi', '', NULL, '戰城南二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01300dd3-4cc0-4704-951f-48aee9578526', '少年行 一', '少年行 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["錦衣鮮華手擎鶻，閑行氣貌多輕忽。","稼穡艱難總不知，五帝三王是何物。"]', '["錦衣鲜华手擎鶻，闲行氣貌多轻忽。","稼穡艱难總不知，五帝三王是何物。"]', '诗', 'shi', '', NULL, '少年行 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f981000b-8a6a-4391-8be0-0908498376f2', '少年行 二', '少年行 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["自拳五色裘，迸入他人宅。","却捉蒼頭奴，玉鞭打一百。"]', '["自拳五色裘，迸入他人宅。","却捉蒼头奴，玉鞭打一百。"]', '诗', 'shi', '', NULL, '少年行 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('378c9a7b-6342-4e69-a07e-c154a77e0a90', '少年行 三', '少年行 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["面白如削玉，猖狂曲江曲。","馬上黃金鞍，適來新賭得。"]', '["面白如削玉，猖狂曲江曲。","马上黄金鞍，適来新賭得。"]', '诗', 'shi', '', NULL, '少年行 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143b1f06-47db-4b06-b10c-a37cd8372375', '夢遊仙四首 一', '梦游仙四首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["夢到海中山，入箇白銀宅。","逢見一道士，稱是李八伯。"]', '["梦到海中山，入箇白銀宅。","逢见一道士，稱是李八伯。"]', '诗', 'shi', '', NULL, '夢遊仙四首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edee2b50-743e-4c16-9bbd-38a933a1f9ae', '夢遊仙四首 二', '梦游仙四首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["三四仙女兒，身著瑟瑟衣。","手把明月珠，打落金色梨。"]', '["三四仙女兒，身著瑟瑟衣。","手把明月珠，打落金色梨。"]', '诗', 'shi', '', NULL, '夢遊仙四首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b5afc6-579c-4c77-9a4b-b94cc0147e0e', '夢遊仙四首 三', '梦游仙四首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["車渠地無塵，行至瑤池濱。","森森椿樹下，白龍來嗅人。"]', '["车渠地無塵，行至瑤池濱。","森森椿樹下，白龙来嗅人。"]', '诗', 'shi', '', NULL, '夢遊仙四首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1de0b99-af67-466c-b27a-ae17ad5895d8', '夢遊仙四首 四', '梦游仙四首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["宮殿崢嶸籠紫氣，金渠玉砂五色水。","守閽仙婢相倚睡，偷摘蟠桃幾倒地。"]', '["宮殿崢嶸籠紫氣，金渠玉砂五色水。","守閽仙婢相倚睡，偷摘蟠桃幾倒地。"]', '诗', 'shi', '', NULL, '夢遊仙四首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('526b2aa9-3041-44a9-bd83-3387a31cfa21', '輕薄篇二首 一', '轻薄篇二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["繡林錦野，春態相壓。","誰家少年，馬蹄蹋蹋。","鬬雞走狗夜不歸，一擲賭却如花妾。","誰云不顛不狂，其名不彰。","悲夫！。"]', '["繡林錦野，春態相壓。","誰家少年，马蹄蹋蹋。","鬬雞走狗夜不归，一擲賭却如花妾。","誰云不顛不狂，其名不彰。","悲夫！。"]', '诗', 'shi', '', NULL, '輕薄篇二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7edafc3b-0629-42e8-a597-c7ac03b2a908', '輕薄篇二首 二', '轻薄篇二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["木落蕭蕭，蟲鳴唧唧。","不覺朱蔫臉紅，霜劫鬢漆。","世途多事，泣向秋日。","方今少壯不努力，老大徒傷悲。"]', '["木落蕭蕭，蟲鳴唧唧。","不覺朱蔫臉紅，霜劫鬢漆。","世途多事，泣向秋日。","方今少壯不努力，老大徒傷悲。"]', '诗', 'shi', '', NULL, '輕薄篇二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0c3d10-e664-45ff-b654-6be68cae002c', '長安道', '长安道', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["憧憧合合，八表一轍。","黃塵霧合，車馬火熱。","名湯風雨，利輾霜雪。","千車萬馱，半宿關月。","上有堯禹，下有夔卨。","紫氣銀輪兮，常覆金闕。","仙掌捧日兮，濁河澄澈。","愚將草木兮有言，與華封人兮不別。"]', '["憧憧合合，八表一轍。","黄塵霧合，车马火熱。","名湯风雨，利輾霜雪。","千车万馱，半宿关月。","上有堯禹，下有夔卨。","紫氣銀輪兮，常覆金闕。","仙掌捧日兮，濁河澄澈。","愚將草木兮有言，與华封人兮不別。"]', '诗', 'shi', '', NULL, '長安道 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a110a6d-6a30-4bfd-afb5-92f8d077535b', '洛陽塵', '洛陽塵', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昔時昔時洛城人，今作茫茫洛城塵。","我聞富有石季倫，樓臺五色干星辰。","樂如天樂日夜聞，錦姝繡妾何紛紛。","真珠簾中，姑射神人。","文金線玉，香成暮雲。","孫秀若不殺，晉室應更貧。","伊水削行路，塚石花磷磷。","蒼茫金谷園，牛羊齕荆榛。","飛鳥好羽毛，疑是綠珠身。"]', '["昔时昔时洛城人，今作茫茫洛城塵。","我闻富有石季倫，楼台五色干星辰。","乐如天乐日夜闻，錦姝繡妾何紛紛。","真珠簾中，姑射神人。","文金線玉，香成暮云。","孫秀若不殺，晉室應更貧。","伊水削行路，塚石花磷磷。","蒼茫金谷园，牛羊齕荆榛。","飞鸟好羽毛，疑是綠珠身。"]', '诗', 'shi', '', NULL, '洛陽塵 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3f1a1c-b8cf-4d10-9d48-5ef77af95fb1', '富貴曲二首 一', '富貴曲二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["有金張族，驕奢相續。","瓊樹玉堂，雕墻繡轂。","紈綺雜雜，鐘鼓合合。","美人如白牡丹花，半日只舞得一曲。","樂不樂，足不足，爭教他愛山青水綠。"]', '["有金張族，驕奢相續。","瓊樹玉堂，雕墻繡轂。","紈綺杂杂，鐘鼓合合。","美人如白牡丹花，半日只舞得一曲。","乐不乐，足不足，爭教他愛山青水綠。"]', '诗', 'shi', '', NULL, '富貴曲二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94a77918-76c6-44f6-8e8e-58fb7dd978d5', '富貴曲二首 二', '富貴曲二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["如神若仙，似蘭同雪。","樂戒于極，胡不知輟。","只欲更綴上落花，恨不能把住明月。","太山肉盡，東海酒竭。","佳人醉唱，敲玉釵折。","寧知耘田車水翁，日日日灸背欲裂。"]', '["如神若仙，似蘭同雪。","乐戒于極，胡不知輟。","只欲更綴上落花，恨不能把住明月。","太山肉尽，东海酒竭。","佳人醉唱，敲玉釵折。","寧知耘田车水翁，日日日灸背欲裂。"]', '诗', 'shi', '', NULL, '富貴曲二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28f892da-d936-4767-a397-5a2273fe1c36', '野田黃雀行', '野田黄雀行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高樹風多，吹爾巢落。","深蒿葉暖，宜爾依泊。","莫近鴞類，蛛網亦惡。","飲野田之清水，食野田之黃粟。","深花中睡，𡋯土裏浴。","如此即全勝啄太倉之穀，而更穿人之屋。"]', '["高樹风多，吹爾巢落。","深蒿葉暖，宜爾依泊。","莫近鴞類，蛛網亦惡。","饮野田之清水，食野田之黄粟。","深花中睡，𡋯土裏浴。","如此即全勝啄太倉之穀，而更穿人之屋。"]', '诗', 'shi', '', NULL, '野田黃雀行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('309461b0-8cf8-4288-8eca-6f610fa9d2ec', '古意九首 一', '古意九首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一雨火雲盡，閉門心冥冥。","蘭花與芙蓉，滿院同芳馨。","佳人天一涯，好鳥何嚶嚶。","我有雙白璧，不羨于虞卿。","我有徑寸珠，別是天地精。","玩之室生白，瀟灑身安輕。","只應天上人，見我雙眼明。"]', '["一雨火云尽，閉门心冥冥。","蘭花與芙蓉，满院同芳馨。","佳人天一涯，好鸟何嚶嚶。","我有雙白璧，不羨于虞卿。","我有徑寸珠，別是天地精。","玩之室生白，瀟灑身安轻。","只應天上人，见我雙眼明。"]', '诗', 'shi', '', NULL, '古意九首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb398fc9-0346-4cd2-ab39-6ca8dba2e380', '古意九首 二', '古意九首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["陽烏爍萬物，草木懷春恩。","茫茫塵土飛，培壅名利根。","我本是蓑笠，幼知天子尊。","學爲毛氏詩，亦多直致言。","不慕需臑類，附勢同崩奔。","唯尋桃李蹊，去去長者門。"]', '["陽烏爍万物，草木懷春恩。","茫茫塵土飞，培壅名利根。","我本是蓑笠，幼知天子尊。","学爲毛氏诗，亦多直致言。","不慕需臑類，附勢同崩奔。","唯尋桃李蹊，去去长者门。"]', '诗', 'shi', '', NULL, '古意九首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c2b127-eda7-498d-828e-46271de7d98f', '古意九首 三', '古意九首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["美人如遊龍，被服金鴛鴦。","手把古刀尺，在彼白玉堂。","文章深掣曳，珂珮鳴丁當。","好風吹桃花，片片落銀床。","何妨學羽翰，遠逐朱鳥翔。"]', '["美人如游龙，被服金鴛鴦。","手把古刀尺，在彼白玉堂。","文章深掣曳，珂珮鳴丁當。","好风吹桃花，片片落銀床。","何妨学羽翰，远逐朱鸟翔。"]', '诗', 'shi', '', NULL, '古意九首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea05842-1f5c-427f-ab89-9bbac4075eb1', '古意九首 四', '古意九首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["乾坤有清氣，散入詩人脾。","聖賢遺清風，不在惡木枝。","千人萬人中，一人兩人知。","憶在東溪日，花開葉落時。","幾擬以黃金，鑄作鍾子期。"]', '["乾坤有清氣，散入诗人脾。","聖賢遺清风，不在惡木枝。","千人万人中，一人兩人知。","憶在东溪日，花开葉落时。","幾擬以黄金，鑄作鍾子期。"]', '诗', 'shi', '', NULL, '古意九首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d931fe9-b45d-4ca9-af65-26b5d5aac2bc', '古意九首 五', '古意九首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["莫輕白雲白，不與風雨會。","莫見守羊兒，或是初平輩。","人生非日月，光輝豈常在。","一榮與一辱，古今常相對。","君不見于公門，子孫好冠蓋。"]', '["莫轻白云白，不與风雨會。","莫见守羊兒，或是初平輩。","人生非日月，光輝豈常在。","一榮與一辱，古今常相对。","君不见于公门，子孫好冠蓋。"]', '诗', 'shi', '', NULL, '古意九首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cdc8483-10f9-43d1-a125-e400ac468bf6', '古意九首 六', '古意九首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["古交如真金，百煉色不回。","今交如暴流，儵忽生塵埃。","我願君子氣，散爲青松栽。","我恐荆棘花，只爲小人開。","傷心復傷心，吟上高高臺。"]', '["古交如真金，百煉色不回。","今交如暴流，儵忽生塵埃。","我願君子氣，散爲青松栽。","我恐荆棘花，只爲小人开。","傷心复傷心，吟上高高台。"]', '诗', 'shi', '', NULL, '古意九首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e260c15-8a1d-43a3-ba62-4827397397e3', '古意九首 七', '古意九首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常思謝康樂，文章有神力。","是何清風清，凜然似相識。","一種爲頑嚚，得作翻經石。","一種爲枯槁，得作登山屐。","永嘉爲郡後，山水添鮮碧。","何當學羽翰，一去觀遺跡。"]', '["常思謝康乐，文章有神力。","是何清风清，凜然似相識。","一種爲頑嚚，得作翻經石。","一種爲枯槁，得作登山屐。","永嘉爲郡後，山水添鲜碧。","何當学羽翰，一去观遺跡。"]', '诗', 'shi', '', NULL, '古意九首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2ba1dc-4d47-4fee-9127-b28753702eb8', '古意九首 八', '古意九首 八', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常思李太白，仙筆驅造化。","玄宗致之七寶床，虎殿龍樓無不可。","一朝力士脫靴後，玉上青蠅生一箇。","紫皇殿前五色麟，忽然掣斷黃金鎖。","五湖大浪如銀山，滿船載酒撾鼓過。","賀老成異物，顛狂誰敢和。","寧知江邊墳，不是猶醉臥。"]', '["常思李太白，仙笔驱造化。","玄宗致之七寶床，虎殿龙楼無不可。","一朝力士脫靴後，玉上青蠅生一箇。","紫皇殿前五色麟，忽然掣斷黄金鎖。","五湖大浪如銀山，满船載酒撾鼓過。","賀老成異物，顛狂誰敢和。","寧知江邊墳，不是猶醉臥。"]', '诗', 'shi', '', NULL, '古意九首 八 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96cbc2fa-2200-466f-b851-2fb48769623d', '古意九首 九', '古意九首 九', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["憶在山中時，丹桂花葳蕤。","紅泉浸瑤草，白日生華滋。","箬屋開地鑪，翠墻挂藤衣。","看經竹窗邊，白猨三兩枝。","東峰有老人，眼碧頭骨奇。","種薤煮白石，旨趣如嬰兒。","月上來打門，月落方始歸。","授我微妙訣，恬澹無所爲。","別來六七年，只恐白日飛。"]', '["憶在山中时，丹桂花葳蕤。","紅泉浸瑤草，白日生华滋。","箬屋开地鑪，翠墻挂藤衣。","看經竹窗邊，白猨三兩枝。","东峰有老人，眼碧头骨奇。","種薤煮白石，旨趣如嬰兒。","月上来打门，月落方始归。","授我微妙訣，恬澹無所爲。","別来六七年，只恐白日飞。"]', '诗', 'shi', '', NULL, '古意九首 九 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9659cd-3b17-448f-8d4f-9bdd007eab34', '酷吏詞', '酷吏词', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["霰雨灂灂，風號如斸。","有叟有叟，暮投我宿。","吁歎自語，云太守酷。","如何如何，掠脂斡肉。","吳姬唱一曲，等閑破紅束。","韓娥唱一曲，錦段鮮照屋。","寧知一曲兩曲謌，曾使千人萬人哭。","不惟哭，亦白其頭，飢其族，所以祥風不來，和氣不復。","蝗乎蠈忽，東西南北。"]', '["霰雨灂灂，风號如斸。","有叟有叟，暮投我宿。","吁歎自語，云太守酷。","如何如何，掠脂斡肉。","吳姬唱一曲，等闲破紅束。","韓娥唱一曲，錦段鲜照屋。","寧知一曲兩曲謌，曾使千人万人哭。","不惟哭，亦白其头，飢其族，所以祥风不来，和氣不复。","蝗乎蠈忽，东西南北。"]', '诗', 'shi', '', NULL, '酷吏詞 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963f4825-dd3c-4461-9ae8-4e1a296a9b95', '還舉人歌行卷', '還舉人歌行卷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["厚於鐵圍山上鐵，薄似雙成仙體纈。","蜀機鳳雛動蹩躠，珊瑚枝枝撐著月。","王愷家中藏難掘，顏回飢僝愁天雪。","古松直筆雷不折，雪衣女啄蟠桃缺。"]', '["厚於鐵圍山上鐵，薄似雙成仙體纈。","蜀機鳳雛动蹩躠，珊瑚枝枝撐著月。","王愷家中藏难掘，顏回飢僝愁天雪。","古松直笔雷不折，雪衣女啄蟠桃缺。"]', '诗', 'shi', '', NULL, '還舉人歌行卷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d4f8d3-5714-4a2b-90e0-391d6eba2d6e', '陳宮詞', '陳宮词', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["緬想當時宮闕盛，荒宴椒房懱堯聖。","玉樹花歌百花裏，珊瑚窗中海日迸。","大臣來朝酒未醒，酒醒忠諫多不聽。","陳宮因此成野田，耕人犂破宮人鏡。"]', '["緬想當时宮闕盛，荒宴椒房懱堯聖。","玉樹花歌百花裏，珊瑚窗中海日迸。","大臣来朝酒未醒，酒醒忠諫多不听。","陳宮因此成野田，耕人犂破宮人镜。"]', '诗', 'shi', '', NULL, '陳宮詞 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0a8f64-89ff-4b84-abfc-2c3fcd8e2b8d', '擬齊梁酬所知見贈二首 一', '擬齊梁酬所知见贈二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["靜只焚香坐，詠懷悲歲闌。","佳人忽有贈，滿手紅琅玕。","不獨耀肌魄，將行爲羽翰。","酬如上青天，風雪空漫漫。"]', '["静只焚香坐，詠懷悲歲闌。","佳人忽有贈，满手紅琅玕。","不独耀肌魄，將行爲羽翰。","酬如上青天，风雪空漫漫。"]', '诗', 'shi', '', NULL, '擬齊梁酬所知見贈二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8eedaee-8d5b-4cf9-ace6-eda237c3c8e7', '擬齊梁酬所知見贈二首 二', '擬齊梁酬所知见贈二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["美如仙鼎金，清如纖手琴。","孫登嘯一聲，縹緲不可尋。","但覺神洋洋，如入三昧林。","釋手復在手，古意深復深。","慚無英瓊瑤，何以酬知音。"]', '["美如仙鼎金，清如纖手琴。","孫登嘯一声，縹緲不可尋。","但覺神洋洋，如入三昧林。","釋手复在手，古意深复深。","慚無英瓊瑤，何以酬知音。"]', '诗', 'shi', '', NULL, '擬齊梁酬所知見贈二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487d58be-60e4-4d7c-9699-375301ed4f69', '經古戰場', '經古戰場', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["茫茫凶荒，迥如天設。","駐馬四顧，氣候迂結。","秋空崢嶸，黃日將沒。","多少行人，白日見物。","莫道路高低，盡是戰骨。","莫見地赤碧，盡是征血。","昔人昔人既能忠盡于力，身糜戈戟。","脂其風，膏其域。","今人何不繩其塍？","植其食。","而使空曠年年，常貯愁煙。","使我至此，不能無言。"]', '["茫茫凶荒，迥如天設。","駐马四顧，氣候迂結。","秋空崢嶸，黄日將沒。","多少行人，白日见物。","莫道路高低，尽是戰骨。","莫见地赤碧，尽是征血。","昔人昔人既能忠尽于力，身糜戈戟。","脂其风，膏其域。","今人何不繩其塍？","植其食。","而使空曠年年，常貯愁煙。","使我至此，不能無言。"]', '诗', 'shi', '', NULL, '經古戰場 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b02b5d9-6d1e-486b-b399-01cab26423fc', '村行遇獵', '村行遇獵', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["獵師紛紛走榛莽，女亦相隨把弓矢。","南北東西盡殺心，斷燒殘雲在圍裏。","鶻拂荒田兔成血，竿打黃茅雉驚起。","傷嗟箇輩亦是人，一生將此關身己。","我聞天地之大德曰生，又聞萬事皆天意。","何遣此人又如此，猶更願天公一丈雪，深山麋鹿盡凍死。"]', '["獵師紛紛走榛莽，女亦相隨把弓矢。","南北东西尽殺心，斷燒殘云在圍裏。","鶻拂荒田兔成血，竿打黄茅雉驚起。","傷嗟箇輩亦是人，一生將此关身己。","我闻天地之大德曰生，又闻万事皆天意。","何遣此人又如此，猶更願天公一丈雪，深山麋鹿尽凍死。"]', '诗', 'shi', '', NULL, '村行遇獵 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('444208cf-16ab-44c1-9908-6bf26d235f10', '漁家', '漁家', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["赤蘆蓋屋低壓恰，沙漲柴門水痕疊。","黃雞青犬花蒙籠，漁女漁兒掃風葉。","有叟相逢帶秋醉，自拔船樁色無媿。","前山脚下得魚多，惡浪堆中盡頭睡。","但得忘筌心自樂，肯羨前賢釣清渭。","終須畫取挂秋堂，與爾爲鄰有深意。"]', '["赤蘆蓋屋低壓恰，沙漲柴门水痕叠。","黄雞青犬花蒙籠，漁女漁兒掃风葉。","有叟相逢带秋醉，自拔船樁色無媿。","前山脚下得鱼多，惡浪堆中尽头睡。","但得忘筌心自乐，肯羨前賢釣清渭。","終須畫取挂秋堂，與爾爲鄰有深意。"]', '诗', 'shi', '', NULL, '漁家 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfb66ee-9b73-4c33-9fcf-8372639753cf', '田家作', '田家作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["田家老翁無可作，晝甑蒸梨香漠漠。","只向堦前曝背眠，赤桑大葉時時落。","古壍侵門桃竹密，倉囤峨峨欲遮日。","自云孫子解耕耘，四五年來腹多實。","我聞此語心自悲，世上悠悠豈得知，稼而不穡徒爾爲。"]', '["田家老翁無可作，晝甑蒸梨香漠漠。","只向堦前曝背眠，赤桑大葉时时落。","古壍侵门桃竹密，倉囤峨峨欲遮日。","自云孫子解耕耘，四五年来腹多實。","我闻此語心自悲，世上悠悠豈得知，稼而不穡徒爾爲。"]', '诗', 'shi', '', NULL, '田家作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75558cd-3e5c-4776-bccb-c2f075ac9503', '江邊祠', '江邊祠', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["松森森，江渾渾，江邊古祠空閉門。","精靈應醉社日酒，白龜咬斷菖蒲根。","花殘泠紅宿雨滴，土龍甲濕鬼眼赤。","天符早晚下空碧，昨夜前村行霹靂。"]', '["松森森，江渾渾，江邊古祠空閉门。","精靈應醉社日酒，白龟咬斷菖蒲根。","花殘泠紅宿雨滴，土龙甲濕鬼眼赤。","天符早晚下空碧，昨夜前村行霹靂。"]', '诗', 'shi', '', NULL, '江邊祠 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49338a72-6850-4da6-9d4c-ed9760ecb164', '苦熱寄赤松道者', '苦熱寄赤松道者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天雲如燒人如炙，天地鑪中更合適。","蟬喘雷乾冰井融，些子清風有何益。","守羊真人聃之役，高吟招隱倚碧壁。","紫氣紅煙鮮的的，澗茗園瓜麴塵色，驕冷奢涼合相憶。"]', '["天云如燒人如炙，天地鑪中更合適。","蟬喘雷乾冰井融，些子清风有何益。","守羊真人聃之役，高吟招隐倚碧壁。","紫氣紅煙鲜的的，澗茗园瓜麴塵色，驕冷奢涼合相憶。"]', '诗', 'shi', '', NULL, '苦熱寄赤松道者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e33b261f-1996-463a-8c98-1043225b08bb', '偶作二首 一', '偶作二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["新詩一千首，古錦初下機。","除月與鬼神，別未有人知。","子期去不返，浩浩良不悲。","不知天地間，知者復是誰。"]', '["新诗一千首，古錦初下機。","除月與鬼神，別未有人知。","子期去不返，浩浩良不悲。","不知天地间，知者复是誰。"]', '诗', 'shi', '', NULL, '偶作二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46bc2d31-92f6-4e9b-a69e-df3ce6139ac0', '偶作二首 二', '偶作二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["門前數枝路，路路車馬鳴。","名埃與利塵，千里萬里行。","只見青山高，豈見青山平。","朱門勢峨峨，冠蓋何光明。","黃鳥在花裏，青蟬奪其聲。","爾生非金玉，豈常貴復貞。","寄言之子心，可以歸無形。"]', '["门前數枝路，路路车马鳴。","名埃與利塵，千里万里行。","只见青山高，豈见青山平。","朱门勢峨峨，冠蓋何光明。","黄鸟在花裏，青蟬奪其声。","爾生非金玉，豈常貴复貞。","寄言之子心，可以归無形。"]', '诗', 'shi', '', NULL, '偶作二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3c5a70-a796-46d2-8f22-87c21636da0e', '夜夜曲', '夜夜曲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蟪蛄切切風騷騷，芙蓉噴香蟾蜍高。","孤燈耿耿征婦勞，更深撲落金錯刀。"]', '["蟪蛄切切风騷騷，芙蓉噴香蟾蜍高。","孤灯耿耿征婦勞，更深撲落金錯刀。"]', '诗', 'shi', '', NULL, '夜夜曲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('031f570d-e6de-4773-ad0f-ad417bae76f4', '春晚書山家屋壁二首 一', '春晚书山家屋壁二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["柴門寂寂黍飯馨，山家煙火春雨晴。","庭花濛濛水泠泠，小兒啼索樹上鶯。"]', '["柴门寂寂黍飯馨，山家煙火春雨晴。","庭花濛濛水泠泠，小兒啼索樹上鶯。"]', '诗', 'shi', '', NULL, '春晚書山家屋壁二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca89ed95-a370-4413-ad31-55a752465d07', '春晚書山家屋壁二首 二', '春晚书山家屋壁二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["水香塘黑蒲森森，鴛鴦鸂鶒如家禽。","前村後壟桑柘深，東鄰西舍無相侵。","蠶娘洗繭前溪淥，牧童吹笛和衣浴。","山翁留我宿又宿，笑指西坡瓜豆熟。"]', '["水香塘黑蒲森森，鴛鴦鸂鶒如家禽。","前村後壟桑柘深，东鄰西舍無相侵。","蠶娘洗繭前溪淥，牧童吹笛和衣浴。","山翁留我宿又宿，笑指西坡瓜豆熟。"]', '诗', 'shi', '', NULL, '春晚書山家屋壁二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81410c71-1b7d-4b01-a4ab-2bd3fe99e3f3', '春晚閑居寄陳嵩伯', '春晚闲居寄陳嵩伯', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["春霖閉門久，春色聚庭木。","一夢辭舊山，四鄰有新哭。","菰蒲生白水，風篁擢纖玉。","爲憶湖上翁，花時獨冥目。"]', '["春霖閉门久，春色聚庭木。","一梦辞旧山，四鄰有新哭。","菰蒲生白水，风篁擢纖玉。","爲憶湖上翁，花时独冥目。"]', '诗', 'shi', '', NULL, '春晚閑居寄陳嵩伯 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ea5056-6a2f-4ed3-8161-771d9d706e9e', '長持經僧', '长持經僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["嘮嘮長夜坐，嘮嘮早起。","杉森森，不見長，人聲續續如流水。","摐金掙玉，吐宮嚥徵。","頭低草木，手合神鬼。","日消三兩黃金爭得止，而槁木朽枝，一食而已。","傷嗟浮世之人，善事不曾入耳。"]', '["嘮嘮长夜坐，嘮嘮早起。","杉森森，不见长，人声續續如流水。","摐金掙玉，吐宮嚥徵。","头低草木，手合神鬼。","日消三兩黄金爭得止，而槁木朽枝，一食而已。","傷嗟浮世之人，善事不曾入耳。"]', '诗', 'shi', '', NULL, '長持經僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a84410e-3f39-42c8-bde8-caa85e59be9a', '茫茫曲', '茫茫曲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["茫茫復茫茫，滿眼皆埃塵。","莫言白髮多，莖莖是愁筋。","未達苦雕僞，及達多不仁。","淺深與高低，盡能生棘榛，茫茫四大愁殺人。"]', '["茫茫复茫茫，满眼皆埃塵。","莫言白髮多，莖莖是愁筋。","未達苦雕僞，及達多不仁。","淺深與高低，尽能生棘榛，茫茫四大愁殺人。"]', '诗', 'shi', '', NULL, '茫茫曲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67a341b-00d8-43fe-b731-49721065beab', '古鏡詞上劉侍郎', '古镜词上劉侍郎', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["至寶不自寶，照古還照今。","仙人手胼胝，寥泬秋沈沈。","不是十二面，不是百煉金。","若非八彩眉，不可輒照臨。","即歸玉案頭，爲君整冠簪。","即居吾君手，照出天下心。","恭聞太宗朝，此鏡當宸襟。","六合懸清光，萬里無塵侵。","此鏡今又出，天地還得一。"]', '["至寶不自寶，照古還照今。","仙人手胼胝，寥泬秋沈沈。","不是十二面，不是百煉金。","若非八彩眉，不可輒照臨。","即归玉案头，爲君整冠簪。","即居吾君手，照出天下心。","恭闻太宗朝，此镜當宸襟。","六合懸清光，万里無塵侵。","此镜今又出，天地還得一。"]', '诗', 'shi', '', NULL, '古鏡詞上劉侍郎 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b41a32-c7cb-4ec5-9c4b-5579ecb1b7bc', '送姜道士歸南岳', '送姜道士归南岳', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["松品落落，雪格索索。","眼有三角，頭峭五岳。","若不居岳，此處難著。","藥僮貌蠻名鄙彼，葫蘆酒滿擔劣起。","萬里長風嘯一聲，九貞須拍黃金几。","落葉蕭蕭□杳□，送師言了意未了。","意未了，他時爲我致取一部音聲鳥。"]', '["松品落落，雪格索索。","眼有三角，头峭五岳。","若不居岳，此处难著。","藥僮貌蠻名鄙彼，葫蘆酒满擔劣起。","万里长风嘯一声，九貞須拍黄金几。","落葉蕭蕭□杳□，送師言了意未了。","意未了，他时爲我致取一部音声鸟。"]', '诗', 'shi', '', NULL, '送姜道士歸南岳 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d659c16e-1b35-4251-b67f-e220466dd599', '了仙謠', '了仙謠', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["海中紫霧蓬萊島，安期子喬去何早。","遊戲多騎白騏驎，鬚髮如銀未曾老。","亦留仙訣在人間，齧鏃終言藥非道。","始皇不得此深旨，遠遣徐福生憂惱。","紫朮黃精心上苗，大還小還行中寶。","若師方術棄心師，浪似雪山何處討。"]', '["海中紫霧蓬萊島，安期子喬去何早。","游戲多騎白騏驎，鬚髮如銀未曾老。","亦留仙訣在人间，齧鏃終言藥非道。","始皇不得此深旨，远遣徐福生憂惱。","紫朮黄精心上苗，大還小還行中寶。","若師方術棄心師，浪似雪山何处討。"]', '诗', 'shi', '', NULL, '了仙謠 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb4697e-c3da-4a14-8cbe-f96eff2ba28f', '循吏曲上王使君', '循吏曲上王使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["需宿需宿，炳爛光合。","蒸蒸婺民，鍾此多福。","自東自西，自南自北。","伊飛伊走，乳乳良牧。","和氣無形，春光自成。","大信不信，貽厥無朕。","需女需女，爾亦須語。","使君爲理，玄風震古。","需女需女，爾亦須語。","我願喙長三千里，枕著玉階奏明主。"]', '["需宿需宿，炳爛光合。","蒸蒸婺民，鍾此多福。","自东自西，自南自北。","伊飞伊走，乳乳良牧。","和氣無形，春光自成。","大信不信，貽厥無朕。","需女需女，爾亦須語。","使君爲理，玄风震古。","需女需女，爾亦須語。","我願喙长三千里，枕著玉階奏明主。"]', '诗', 'shi', '', NULL, '循吏曲上王使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2f6cd2-3d78-43c3-bb25-3398c9dfde70', '古鏡詞', '古镜词', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我有一面鏡，新磨似秋月。","上唯金膏香，下狀驪龍窟。","等閑不欲開，醜者多不悅。","或問幾千年，軒轅手中物。"]', '["我有一面镜，新磨似秋月。","上唯金膏香，下狀驪龙窟。","等闲不欲开，醜者多不悅。","或问幾千年，軒轅手中物。"]', '诗', 'shi', '', NULL, '古鏡詞 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08224bf6-bbdb-47b7-b7f8-e002f6199136', '懷張爲周朴', '懷張爲周朴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["張周二夫子，詩好人太癖。","更不過嶺來，如今頭盡白。","人傳禹力不到處，河聲流向西。","又到處即閉戶，逢君方展眉。","不知是不是，若是即大奇。","我又聞二公，心與人不同。","一生常在寂寞中，有時狂吟入僧宅。","錦囊鳥啼荔枝紅，有時冥搜海山腦。","珊瑚枝動日杲杲，聖君在上知不知，赤面濁醪許多好。"]', '["張周二夫子，诗好人太癖。","更不過嶺来，如今头尽白。","人傳禹力不到处，河声流向西。","又到处即閉戶，逢君方展眉。","不知是不是，若是即大奇。","我又闻二公，心與人不同。","一生常在寂寞中，有时狂吟入僧宅。","錦囊鸟啼荔枝紅，有时冥搜海山腦。","珊瑚枝动日杲杲，聖君在上知不知，赤面濁醪許多好。"]', '诗', 'shi', '', NULL, '懷張爲周朴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54225f57-2dcc-4b0e-9461-4dd755b96241', '題弘顗三藏院', '題弘顗三藏院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["儀清態淡雕瓊瓌，捲簾瀟灑無塵埃。","嶽茶如乳庭花開，信心弟子時時來。","灌頂壇嚴伸㽬塞，三十年功苦拘束。","梵僧夢裏授微言，雪嶺白牛力深得。","水精一索香一爐，紅蓮花舌生醍醐。","初聽喉音寶樓閣，如聞魔王宮殿拉金瓦落。","次聽妙音大隨求，更覺人間萬事深悠悠。","四音俱作清且柔，愛河濁浪却倒流。","却倒流兮無處去，碧海含空日初曙。"]', '["儀清態淡雕瓊瓌，捲簾瀟灑無塵埃。","嶽茶如乳庭花开，信心弟子时时来。","灌頂壇嚴伸㽬塞，三十年功苦拘束。","梵僧梦裏授微言，雪嶺白牛力深得。","水精一索香一爐，紅蓮花舌生醍醐。","初听喉音寶楼閣，如闻魔王宮殿拉金瓦落。","次听妙音大隨求，更覺人间万事深悠悠。","四音俱作清且柔，愛河濁浪却倒流。","却倒流兮無处去，碧海含空日初曙。"]', '诗', 'shi', '', NULL, '題弘顗三藏院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c937474-d08e-47e8-bf3e-309d00eed91f', '古意代友人投所知', '古意代友人投所知', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["青松雖有花，有花不如無。","貧井泉雖清，且無金轆轤。","客從遠方來，遺我古銅鏡。","挂之玉堂上，如對軒轅聖。","天龍睡坤腹，土蝕金鬣綠。","因知燕趙佳人顏似玉，不得此鏡終不。"]', '["青松雖有花，有花不如無。","貧井泉雖清，且無金轆轤。","客從远方来，遺我古銅镜。","挂之玉堂上，如对軒轅聖。","天龙睡坤腹，土蝕金鬣綠。","因知燕趙佳人顏似玉，不得此镜終不。"]', '诗', 'shi', '', NULL, '古意代友人投所知 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5fecfd-f432-4fa6-8f77-3aee61fd3317', '聞知己入翰林', '闻知己入翰林', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天驥頭似鳥，[倐]忽四天下。","南金色如椹，入火不見火。","吾交二名士，遽立于帝左。","鳳姿既出世，天意囑在我。","奇哉子淵頌，無可無不可。"]', '["天驥头似鸟，[倐]忽四天下。","南金色如椹，入火不见火。","吾交二名士，遽立于帝左。","鳳姿既出世，天意囑在我。","奇哉子淵頌，無可無不可。"]', '诗', 'shi', '', NULL, '聞知己入翰林 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f011a00f-3463-4787-8149-e0505464dd7a', '上裴大夫二首 一', '上裴大夫二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我有一端綺，花彩鸞鳳羣。","佳人金錯刀，何似裁此文。"]', '["我有一端綺，花彩鸾鳳羣。","佳人金錯刀，何似裁此文。"]', '诗', 'shi', '', NULL, '上裴大夫二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf318fe-e826-47b6-bc66-6e79a5b65832', '上裴大夫二首 二', '上裴大夫二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我有白雲琴，樸斲天地精。","俚耳不使聞，慮同衆樂聽。","指指法仙法，聲聲聖人聲。","一彈四時和，再彈中古清。","庭前梧桐枝，颯颯南風生。","還希師曠懷，見我心不輕。"]', '["我有白云琴，樸斲天地精。","俚耳不使闻，慮同衆乐听。","指指法仙法，声声聖人声。","一彈四时和，再彈中古清。","庭前梧桐枝，颯颯南风生。","還希師曠懷，见我心不轻。"]', '诗', 'shi', '', NULL, '上裴大夫二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1233a3-6911-4c3b-a0fb-b5679fd28ca4', '上劉商州', '上劉商州', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["周邵吁噓氣，結爲禎祥雲。","客從遠方來，持此將贈君。","時命偶不謬，授館終南東。","愔愔良吏師，不寐如老農。","丘軻文之天，代天有餘功。","代天復代天，后稷何所從。"]', '["周邵吁噓氣，結爲禎祥云。","客從远方来，持此將贈君。","时命偶不謬，授館終南东。","愔愔良吏師，不寐如老農。","丘軻文之天，代天有餘功。","代天复代天，后稷何所從。"]', '诗', 'shi', '', NULL, '上劉商州 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2087809f-1af6-44d9-8b56-697c355752c1', '閑居擬齊梁四首 一', '闲居擬齊梁四首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["夜雨山草滋，爽籟生古木。","閑吟竹仙偈，清於嚼金玉。","蟋蟀啼壞牆，苟免悲局促。","道人優曇花，迢迢遠山綠。"]', '["夜雨山草滋，爽籟生古木。","闲吟竹仙偈，清於嚼金玉。","蟋蟀啼壞牆，苟免悲局促。","道人優曇花，迢迢远山綠。"]', '诗', 'shi', '', NULL, '閑居擬齊梁四首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a762e4-3c24-4830-9702-75bde063eed3', '閑居擬齊梁四首 二', '闲居擬齊梁四首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["果熟無低枝，芳香入屏帷。","故人久不來，萱草何離離。","苦吟齋貌減，更被杉風吹。","獨賴湖上翁，時爲烹露葵。"]', '["果熟無低枝，芳香入屏帷。","故人久不来，萱草何離離。","苦吟斋貌減，更被杉风吹。","独賴湖上翁，时爲烹露葵。"]', '诗', 'shi', '', NULL, '閑居擬齊梁四首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a710ba-f0fd-46df-97da-714c47c61840', '閑居擬齊梁四首 三', '闲居擬齊梁四首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["紅藕暎嘉魴，澄池照孤坐。","池痕放文彩，雨氣贈慵墮。","山翁寄朮藥，幸得秋病可。","終召十七人，雲中備香火。"]', '["紅藕暎嘉魴，澄池照孤坐。","池痕放文彩，雨氣贈慵墮。","山翁寄朮藥，幸得秋病可。","終召十七人，云中備香火。"]', '诗', 'shi', '', NULL, '閑居擬齊梁四首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbe61f2e-56fc-460e-9e26-98cb74b5c874', '閑居擬齊梁四首 四', '闲居擬齊梁四首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清氣生滄洲，殘雲落林藪。","放鶴久不歸，不知更歸否。","支策到江湄，江臯木葉飛。","自憐爲客遠，還如鵲遶枝。","南枝復北枝，玉露沾毛衣。"]', '["清氣生滄洲，殘云落林藪。","放鹤久不归，不知更归否。","支策到江湄，江臯木葉飞。","自怜爲客远，還如鵲遶枝。","南枝复北枝，玉露沾毛衣。"]', '诗', 'shi', '', NULL, '閑居擬齊梁四首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36ec153-e2bf-4e00-8208-ac45b0fb3eb5', '塞上曲二首 一', '塞上曲二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["錦袷胡兒黑如漆，騎羊上冰如箭疾。","蒲萄酒白雕腊紅，苜蓿根甜沙鼠出。","單于右臂何須斷，天子昭昭本如日。","一握黳髯一握絲，須知只爲平戎術。"]', '["錦袷胡兒黑如漆，騎羊上冰如箭疾。","蒲萄酒白雕腊紅，苜蓿根甜沙鼠出。","單于右臂何須斷，天子昭昭本如日。","一握黳髯一握絲，須知只爲平戎術。"]', '诗', 'shi', '', NULL, '塞上曲二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d60e07-8e14-42cd-8c0d-4ba6ba51e238', '塞上曲二首 二', '塞上曲二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["去年轉鬬陰山脚，生得單于却放却。","今年深入于不毛，胡兵拔帳遺弓刀。","男兒須展平生志，爲國輸忠合天地。","甲穿雖即失黃金，劒缺猶能生紫氣。","塞草萋萋兵士苦，胡虜如今勿胡虜。","封侯十萬始無心，玉關凱入君看取。"]', '["去年轉鬬陰山脚，生得單于却放却。","今年深入于不毛，胡兵拔帳遺弓刀。","男兒須展平生志，爲国輸忠合天地。","甲穿雖即失黄金，劒缺猶能生紫氣。","塞草萋萋兵士苦，胡虜如今勿胡虜。","封侯十万始無心，玉关凱入君看取。"]', '诗', 'shi', '', NULL, '塞上曲二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d9e605-c1b2-4651-92f2-bf024ae44875', '擬齊梁體寄馮使君三首 一', '擬齊梁體寄馮使君三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["庭鳥多好音，相呼灌木中。","竹房更何有，還如鳥巢空。","賴逢富人侯，真東晉謝公。","煌煌發令姿，珂珮鳴丁冬。","故山有深霞，未如旌旗紅。","慚非衛霍松，何以當清風。"]', '["庭鸟多好音，相呼灌木中。","竹房更何有，還如鸟巢空。","賴逢富人侯，真东晉謝公。","煌煌發令姿，珂珮鳴丁冬。","故山有深霞，未如旌旗紅。","慚非衛霍松，何以當清风。"]', '诗', 'shi', '', NULL, '擬齊梁體寄馮使君三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc179e3-6b97-4513-9d55-8b9cdb6673e6', '擬齊梁體寄馮使君三首 二', '擬齊梁體寄馮使君三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["露益蟬聲長，蕙蘭垂紫帶。","清吟代明月，孤雲忽爲蓋。","伊余石林人，本是燒畬輩。","頻接謝公棊，輸多未曾賽。"]', '["露益蟬声长，蕙蘭垂紫带。","清吟代明月，孤云忽爲蓋。","伊余石林人，本是燒畬輩。","頻接謝公棊，輸多未曾賽。"]', '诗', 'shi', '', NULL, '擬齊梁體寄馮使君三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84980cd4-e51e-47b4-8cd2-ba00e9097cc3', '擬齊梁體寄馮使君三首 三', '擬齊梁體寄馮使君三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["大道貴無心，聖賢爲始慕。","秋空共澄潔，美玉同貞素。","偉哉桐江守，雌黃出金口。","爲文能廢興，談道弭空有。","雪林槁枯者，坐石聽亦久。","還疑紫磨身，成居靈運後。"]', '["大道貴無心，聖賢爲始慕。","秋空共澄潔，美玉同貞素。","偉哉桐江守，雌黄出金口。","爲文能廢兴，談道弭空有。","雪林槁枯者，坐石听亦久。","還疑紫磨身，成居靈運後。"]', '诗', 'shi', '', NULL, '擬齊梁體寄馮使君三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2da42c3-3266-4126-84f4-d4a5334b1ab0', '書匡山老僧菴', '书匡山老僧菴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["篔簹紅實好鳥語，銀髯瘦僧貌如祖。","香煙濛濛衣上聚，冥心縹緲入鐵圄。","白麏作夢枕藤屨，東峯山媼貢瓜乳。"]', '["篔簹紅實好鸟語，銀髯瘦僧貌如祖。","香煙濛濛衣上聚，冥心縹緲入鐵圄。","白麏作梦枕藤屨，东峯山媼貢瓜乳。"]', '诗', 'shi', '', NULL, '書匡山老僧菴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089ebcfd-893b-432e-a3e8-af3f748b7722', '讀顧況歌行', '读顧況歌行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雪泥露金冰滴瓦，楓檉火著僧留坐。","忽覩逋翁一軸歌，始覺詩魔辜負我。","花飛飛，雪霏霏，三珠樹曉珠纍纍。","妖狐爬出西子骨，雷車拶破織女機。","憶昔鄱陽寺中見一碣，逋翁詞兮逋翁札。","庾翼未伏王右軍，李白不知誰擬殺。","別，別，若非仙眼應難別。","不可說，不可說，離亂亂離應打折。"]', '["雪泥露金冰滴瓦，楓檉火著僧留坐。","忽覩逋翁一軸歌，始覺诗魔辜負我。","花飞飞，雪霏霏，三珠樹晓珠纍纍。","妖狐爬出西子骨，雷车拶破织女機。","憶昔鄱陽寺中见一碣，逋翁词兮逋翁札。","庾翼未伏王右軍，李白不知誰擬殺。","別，別，若非仙眼應难別。","不可说，不可说，離亂亂離應打折。"]', '诗', 'shi', '', NULL, '讀顧況歌行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530741a2-f841-4fa4-94cf-673df4f8a172', '冬末病中作二首 一', '冬末病中作二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["冬風吹草木，亦吹我病根。","故人久不來，冷落如丘園。","聃龍與摩詰，吁歎非不聞。","顧惟年少時，未合多憂懃。","風鍾遠孤枕，雪水流凍痕。","空餘微妙心，期空靜者論。"]', '["冬风吹草木，亦吹我病根。","故人久不来，冷落如丘园。","聃龙與摩詰，吁歎非不闻。","顧惟年少时，未合多憂懃。","风鍾远孤枕，雪水流凍痕。","空餘微妙心，期空静者論。"]', '诗', 'shi', '', NULL, '冬末病中作二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('692bdb40-7c79-4c9e-9b9d-3c476620896e', '冬末病中作二首 二', '冬末病中作二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["胸中有一物，旅拒復攻擊。","向下還上來，唯疑是肺石。","山童頑且小，用之復何益。","教洗煮茶鐺，雪團打鄰壁。","宛轉無好姿，裴回更何適。","庭前早梅樹，坐見花盡碧。","屋老多鼠窠，窗卑露山脊。","近來胸中物，已似輸藥力。","微吟復微今，依稀似莊舃。"]', '["胸中有一物，旅拒复攻擊。","向下還上来，唯疑是肺石。","山童頑且小，用之复何益。","教洗煮茶鐺，雪團打鄰壁。","宛轉無好姿，裴回更何適。","庭前早梅樹，坐见花尽碧。","屋老多鼠窠，窗卑露山脊。","近来胸中物，已似輸藥力。","微吟复微今，依稀似莊舃。"]', '诗', 'shi', '', NULL, '冬末病中作二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a18a3990-6160-4bbd-8d5d-1565d9662e84', '遇葉進士', '遇葉進士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["文章擬真宰，儀冠冷如[璧]。","山寺偶相逢，眼青勝山色。","氣隆多慷慨，語澹無他力。","金繩殘果落，竹閣涼雨滴。","自媿龍鍾人，見此沖天翼。"]', '["文章擬真宰，儀冠冷如[璧]。","山寺偶相逢，眼青勝山色。","氣隆多慷慨，語澹無他力。","金繩殘果落，竹閣涼雨滴。","自媿龙鍾人，见此沖天翼。"]', '诗', 'shi', '', NULL, '遇葉進士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19fd214b-2da6-4461-a40a-25800d2c2ef4', '寄杜使君', '寄杜使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清辰捲珠簾，盥漱香滿室。","杉松經雪後，別有精彩出。","琅函芙蓉書，開之向堦日。","好鳥常解來，孤雲偶相失。","有時作章句，氣概還鮮逸。","茫茫世情世，誰人愛真實。","清高慕玄度，宴默攀道一。","殘磬隔風林，微陽解冰筆。","亦知休明代，諒無經濟術。","門前九箇峯，終擬爲文乞。"]', '["清辰捲珠簾，盥漱香满室。","杉松經雪後，別有精彩出。","琅函芙蓉书，开之向堦日。","好鸟常解来，孤云偶相失。","有时作章句，氣概還鲜逸。","茫茫世情世，誰人愛真實。","清高慕玄度，宴默攀道一。","殘磬隔风林，微陽解冰笔。","亦知休明代，諒無經濟術。","门前九箇峯，終擬爲文乞。"]', '诗', 'shi', '', NULL, '寄杜使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cfb1c1b-3f23-447b-9857-4a57aa71ac61', '寄高員外', '寄高員外', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["冷冽蒼黃風似劈，雪骨冰筋滿瑤席。","庭松流汙相抵喫，霜絮重裘火無力。","孤峯地鑪燒白櫪，龐眉道者應相憶。","儵忽維陽歲云暮，寂寥不覺成章句。","惟應將寄蘂珠宮，禪剎雲深一來否。"]', '["冷冽蒼黄风似劈，雪骨冰筋满瑤席。","庭松流汙相抵喫，霜絮重裘火無力。","孤峯地鑪燒白櫪，龐眉道者應相憶。","儵忽維陽歲云暮，寂寥不覺成章句。","惟應將寄蘂珠宮，禪剎云深一来否。"]', '诗', 'shi', '', NULL, '寄高員外 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dec600ff-f7f2-4824-8bc9-d429374b2b28', '書陳處士屋壁二首 一', '书陳处士屋壁二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["有叟傲堯日，髮白肌膚紅。","妻子亦讀書，種蘭清溪東。","白雲有奇色，紫桂含天風。","即應迎鶴書，肯羨於洞洪。"]', '["有叟傲堯日，髮白肌膚紅。","妻子亦读书，種蘭清溪东。","白云有奇色，紫桂含天风。","即應迎鹤书，肯羨於洞洪。"]', '诗', 'shi', '', NULL, '書陳處士屋壁二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2257ed8f-1739-4a4d-9eb2-9ac80c778618', '書陳處士屋壁二首 二', '书陳处士屋壁二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高步前山前，高歌北山北。","數載賣甘橙，山貲近云足。","新詩不將出，往往僧乞得。","唯云李太白，亦是偷桃賊。","吟狂鬼神走，酒釅天地[黑]。","青芻生堦除，擷之束成束。"]', '["高步前山前，高歌北山北。","數載賣甘橙，山貲近云足。","新诗不將出，往往僧乞得。","唯云李太白，亦是偷桃賊。","吟狂鬼神走，酒釅天地[黑]。","青芻生堦除，擷之束成束。"]', '诗', 'shi', '', NULL, '書陳處士屋壁二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2cc6dcf-6c94-4fc7-a3e9-a514310a63b9', '對月作', '对月作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["今人看此月，古人看此月。","如何古人心，難向今人說。","古人求祿以及親，及之如之何。","忠孝爲朱輪，今人求祿唯庇身。","庇身如之何，惡木多斜文。","斜文復斜文，顛窒何紛紛。"]', '["今人看此月，古人看此月。","如何古人心，难向今人说。","古人求祿以及親，及之如之何。","忠孝爲朱輪，今人求祿唯庇身。","庇身如之何，惡木多斜文。","斜文复斜文，顛窒何紛紛。"]', '诗', 'shi', '', NULL, '對月作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45175096-5a3e-4dd1-ab2c-f822de0bd1e9', '山茶花', '山茶花', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["風裁日染開仙囿，百花色死猩血謬。","今朝一朵墮堦前，應有看人怨孫秀。"]', '["风裁日染开仙囿，百花色死猩血謬。","今朝一朵墮堦前，應有看人怨孫秀。"]', '诗', 'shi', '', NULL, '山茶花 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79e889a-3212-4cfc-b0ae-720e340a5c73', '上孫使君', '上孫使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["聖主得賢臣，天地方交泰。","恭惟嶽精粹，多出於昭代。","君侯握文鏡，獨立塵埃外。","王演俗容儀，崔陵小風概。","馨香擁蘭雪，峻秀高嵩岱。","嵇松領歲寒，莊劒無礱淬。","威稜玉霜直，匠石金槌大。","詩穿明月珠，道拍安期背。","中興鸞鳳集，直道風雲會。","萬卷似無書，三山如歷塊。","德乎天所縱，清矣誰堪對。","有法在朝端，無塵到冠蓋。","具瞻從密勿，旦夕調鼎鼐。","爲君整衢尊，爲君戢蕃塞。","豈知吾后意，憂此毘陵最。","親手賜彤弓，蒼生是繄賴。","下車鄰寇散，是物冰壺內。","龔遂[愛]廉平，次公太繁碎。","袴襦砧動地，父母歌闤闠。","□雪鏁戈鋋，非煙遶旌斾。","寧思子產冰，肯羨任棠薤。","忽如春再來，不獨天重戴。","昂藏海嶠鶴，冷碧仙庭檜。","物物動和氣，家家有新態。","芙蓉開帟幕，錦帳無纖壒。","鼓角穿凍雲，恩波動耕耒。","奸回改精魄，禮教書紳帶。","必于堯舜日，還似房杜輩。","野人有章句，格力亦慷慨。","若不入丘門，世間更誰愛。"]', '["聖主得賢臣，天地方交泰。","恭惟嶽精粹，多出於昭代。","君侯握文镜，独立塵埃外。","王演俗容儀，崔陵小风概。","馨香擁蘭雪，峻秀高嵩岱。","嵇松領歲寒，莊劒無礱淬。","威稜玉霜直，匠石金槌大。","诗穿明月珠，道拍安期背。","中兴鸾鳳集，直道风云會。","万卷似無书，三山如歷塊。","德乎天所縱，清矣誰堪对。","有法在朝端，無塵到冠蓋。","具瞻從密勿，旦夕調鼎鼐。","爲君整衢尊，爲君戢蕃塞。","豈知吾后意，憂此毘陵最。","親手賜彤弓，蒼生是繄賴。","下车鄰寇散，是物冰壺內。","龔遂[愛]廉平，次公太繁碎。","袴襦砧动地，父母歌闤闠。","□雪鏁戈鋋，非煙遶旌斾。","寧思子產冰，肯羨任棠薤。","忽如春再来，不独天重戴。","昂藏海嶠鹤，冷碧仙庭檜。","物物动和氣，家家有新態。","芙蓉开帟幕，錦帳無纖壒。","鼓角穿凍云，恩波动耕耒。","奸回改精魄，禮教书紳带。","必于堯舜日，還似房杜輩。","野人有章句，格力亦慷慨。","若不入丘门，世间更誰愛。"]', '诗', 'shi', '', NULL, '上孫使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47426d63-51d4-4e03-bc27-323630bb1168', '哭靈一上人', '哭靈一上人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一公何不在，空有遠公名。","共說岑山路，今時不可行。","舊房松更老，新塔草初生。","經論傳緇侶，文章遍墨卿。","禪林枝幹折，法宇棟梁傾。","誰俊修僧史，應知傳已成。"]', '["一公何不在，空有远公名。","共说岑山路，今时不可行。","旧房松更老，新塔草初生。","經論傳緇侶，文章遍墨卿。","禪林枝幹折，法宇棟梁傾。","誰俊修僧史，應知傳已成。"]', '诗', 'shi', '', NULL, '哭靈一上人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22f841a-91f2-4537-bc81-79fd1d56919d', '行路難 一', '行路难 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["君不見山高海深人不測，古往今來轉青碧。","淺近輕浮莫與交，地卑只解生荆棘。","誰道黃金如糞土，張耳陳餘斷消息。","行路難，行路難，君自看。"]', '["君不见山高海深人不測，古往今来轉青碧。","淺近轻浮莫與交，地卑只解生荆棘。","誰道黄金如糞土，張耳陳餘斷消息。","行路难，行路难，君自看。"]', '诗', 'shi', '', NULL, '行路難 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca50797-22fc-4805-8db6-96546f8383eb', '行路難 二', '行路难 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不會當時作天地，剛有多般愚與智。","到頭還用真宰心，何如上下皆清氣。","大道冥冥不知處，那堪頓得羲和轡。","義不義兮仁不仁，擬學長生更容易。","負心爲罏復爲火，緣木求魚應且止。","君不見燒金煉石古帝王，鬼火熒熒白楊裏。"]', '["不會當时作天地，剛有多般愚與智。","到头還用真宰心，何如上下皆清氣。","大道冥冥不知处，那堪頓得羲和轡。","義不義兮仁不仁，擬学长生更容易。","負心爲罏复爲火，緣木求鱼應且止。","君不见燒金煉石古帝王，鬼火熒熒白楊裏。"]', '诗', 'shi', '', NULL, '行路難 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7df0412-a577-49e5-aa8b-adb1a3d8d635', '行路難 三', '行路难 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["君不見道傍廢井生古木，本是驕奢貴人屋。","幾度美人照影來，素綆銀缾濯纖玉。","雲飛雨散今如此，繡闥雕甍作荒谷。","沸渭笙歌君莫誇，不應常是西家哭。","休誰遺編行者幾，至竟終須合天理。","敗他成此亦何功，蘇張終作多言鬼。","行路難，行路難，不在羊腸裏。"]', '["君不见道傍廢井生古木，本是驕奢貴人屋。","幾度美人照影来，素綆銀缾濯纖玉。","云飞雨散今如此，繡闥雕甍作荒谷。","沸渭笙歌君莫誇，不應常是西家哭。","休誰遺編行者幾，至竟終須合天理。","敗他成此亦何功，蘇張終作多言鬼。","行路难，行路难，不在羊腸裏。"]', '诗', 'shi', '', NULL, '行路難 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd949047-34b7-4d60-87ae-147c9b8e0c36', '行路難 四', '行路难 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["九有茫茫共堯日，浪死虛生亦非一。","清淨玄音竟不聞，花眼酒腸暗如漆。","或偶因片言隻字登第光二親，又不能獻可替否航要津。","口譚羲軒與周孔，履行不及屠沽人。","行路難，行路難，日暮途遠空悲歎。"]', '["九有茫茫共堯日，浪死虛生亦非一。","清淨玄音竟不闻，花眼酒腸暗如漆。","或偶因片言隻字登第光二親，又不能獻可替否航要津。","口譚羲軒與周孔，履行不及屠沽人。","行路难，行路难，日暮途远空悲歎。"]', '诗', 'shi', '', NULL, '行路難 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b86cc3c8-715b-46fe-9a2f-0e72af8e599f', '行路難 五', '行路难 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["君不見道傍樹有寄生枝，青青鬱鬱同榮衰。","無情之物尚如此，爲人不及還堪悲。","父歸墳兮未朝夕，已分黃金爭田宅。","高堂老母頭似霜，心作數支淚常滴。","我聞忽如負芒刺，不獨爲君空歎息。","古人尺布猶可縫，潯陽義犬令人憶。","寄言世上爲人子，孝義團圓莫如此。","若如此，不遄死兮更何俟。"]', '["君不见道傍樹有寄生枝，青青鬱鬱同榮衰。","無情之物尚如此，爲人不及還堪悲。","父归墳兮未朝夕，已分黄金爭田宅。","高堂老母头似霜，心作數支泪常滴。","我闻忽如負芒刺，不独爲君空歎息。","古人尺布猶可縫，潯陽義犬令人憶。","寄言世上爲人子，孝義團圓莫如此。","若如此，不遄死兮更何俟。"]', '诗', 'shi', '', NULL, '行路難 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b8fd964-d0aa-4328-9830-d7284d70bc53', '泊秋江', '泊秋江', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["岸如洞庭山似剡，船漾清溪涼勝簟。","月白風高不得眠，枯葦叢邊釣師魘。"]', '["岸如洞庭山似剡，船漾清溪涼勝簟。","月白风高不得眠，枯葦叢邊釣師魘。"]', '诗', 'shi', '', NULL, '泊秋江 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d6ca40-9b7a-4088-9dcc-827bc79f19d2', '嘲商客', '嘲商客', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["葦蕭蕭，風摵摵，落日江頭何處客。","斜倚帆檣不喚人，五湖浪向心中白。"]', '["葦蕭蕭，风摵摵，落日江头何处客。","斜倚帆檣不喚人，五湖浪向心中白。"]', '诗', 'shi', '', NULL, '嘲商客 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('049b232e-8ab1-4ccb-967e-4899bc6c6e12', '寄王滌', '寄王滌', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["梅月多開戶，衣裳潤欲滴。","寂寥雖無形，不是小讐敵。","地虛草木壯，雨白桃李赤。","永日無人來，庭花苦狼籍。","吟高好鳥覷，風靜茶煙直。","唯思萊子來，衣拖五般色。"]', '["梅月多开戶，衣裳潤欲滴。","寂寥雖無形，不是小讐敵。","地虛草木壯，雨白桃李赤。","永日無人来，庭花苦狼籍。","吟高好鸟覷，风静茶煙直。","唯思萊子来，衣拖五般色。"]', '诗', 'shi', '', NULL, '寄王滌 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42d13e43-6efe-4101-bf30-8685ef9c5cbd', '上馮使君五首 一', '上馮使君五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["撐船碧江上，春日何遲遲。","汀花最深處，拾得鴛鴦兒。"]', '["撐船碧江上，春日何遲遲。","汀花最深处，拾得鴛鴦兒。"]', '诗', 'shi', '', NULL, '上馮使君五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae39f4cf-c7c4-49f1-99cd-df8cfeaf765a', '上馮使君五首 二', '上馮使君五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["漁父無憂苦，水仙亦何別。","眠在綠葦邊，不知釣筒發。"]', '["漁父無憂苦，水仙亦何別。","眠在綠葦邊，不知釣筒發。"]', '诗', 'shi', '', NULL, '上馮使君五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d5cea9-c175-494c-bde5-ba17a6e19cae', '上馮使君五首 三', '上馮使君五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["樵叟無憂苦，地仙亦何別。","茆屋岸花中，弄孫頭似雪。"]', '["樵叟無憂苦，地仙亦何別。","茆屋岸花中，弄孫头似雪。"]', '诗', 'shi', '', NULL, '上馮使君五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d58548-3293-4f9f-9142-7f4c71d09607', '上馮使君五首 四', '上馮使君五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["扣舷得新詩，茶煮桃花水。","㠔㠔數片帆，去去殊未已。"]', '["扣舷得新诗，茶煮桃花水。","㠔㠔數片帆，去去殊未已。"]', '诗', 'shi', '', NULL, '上馮使君五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba0bdf9-9c3b-4f2e-be4c-cb31824c1385', '上馮使君五首 五', '上馮使君五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["仁政無不及，乳獺將子行。","誰家苦竹林，中有讀書聲。"]', '["仁政無不及，乳獺將子行。","誰家苦竹林，中有读书声。"]', '诗', 'shi', '', NULL, '上馮使君五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b24845c-c5cb-4e7f-aa86-3cd08e92c742', '擬君子有所思二首 一', '擬君子有所思二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我愛正考甫，思賢作商頌。","我愛揚子雲，理亂皆如鳳。","振衣中夜起，露花香旖旎。","撲碎驪龍明月珠，敲出鳳皇五色髓。","陋巷蕭蕭風㭊㭊，緬想斯人勝珪璧。","寂寥千載不相逢，無限區區盡虛擲。","君不見沈約道，佳人不在茲，春光爲誰惜。"]', '["我愛正考甫，思賢作商頌。","我愛揚子云，理亂皆如鳳。","振衣中夜起，露花香旖旎。","撲碎驪龙明月珠，敲出鳳皇五色髓。","陋巷蕭蕭风㭊㭊，緬想斯人勝珪璧。","寂寥千載不相逢，無限區區尽虛擲。","君不见沈約道，佳人不在茲，春光爲誰惜。"]', '诗', 'shi', '', NULL, '擬君子有所思二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00146da6-8344-44fe-8522-526cdf8cad77', '擬君子有所思二首 二', '擬君子有所思二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["安得龍猛筆，點石爲黃金。","散爲酷吏家，使無貪殘心。","甘棠密葉成翠幄，欵鳳不來天地塞。","所以傾國傾城人，如今如今不可得。"]', '["安得龙猛笔，点石爲黄金。","散爲酷吏家，使無貪殘心。","甘棠密葉成翠幄，欵鳳不来天地塞。","所以傾国傾城人，如今如今不可得。"]', '诗', 'shi', '', NULL, '擬君子有所思二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994573a0-8bec-4d71-81d4-6299d4d039ac', '古塞下曲四首 一', '古塞下曲四首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["古塞腥膻地，胡兵聚如蠅。","寒鵰中𩩉石，落在黃河冰。","蒼茫邏逤城，枿枿賊氣興。","鑄金禱秋穹，還擬相憑陵。"]', '["古塞腥膻地，胡兵聚如蠅。","寒鵰中𩩉石，落在黄河冰。","蒼茫邏逤城，枿枿賊氣兴。","鑄金禱秋穹，還擬相憑陵。"]', '诗', 'shi', '', NULL, '古塞下曲四首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b920728f-1c21-4af8-a85b-34d1930e9bc7', '古塞下曲四首 二', '古塞下曲四首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["戰骨踐成塵，飛入征人目。","黃雲忽變黑，戰鬼作陣哭。","陰風吼大漠，火號出不得。","誰爲天子前，唱此邊城曲。"]', '["戰骨踐成塵，飞入征人目。","黄云忽变黑，戰鬼作陣哭。","陰风吼大漠，火號出不得。","誰爲天子前，唱此邊城曲。"]', '诗', 'shi', '', NULL, '古塞下曲四首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9cd899-f5d3-4dfa-9d3d-27f1782942e9', '古塞下曲四首 三', '古塞下曲四首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["日向平沙出，還向平沙沒。","飛蓬落軍營，驚鵰去天末。","帝鄉青樓倚霄漢，歌吹掀天對花月。","豈知塞上望鄉人，日日雙眸滴清血。"]', '["日向平沙出，還向平沙沒。","飞蓬落軍營，驚鵰去天末。","帝乡青楼倚霄漢，歌吹掀天对花月。","豈知塞上望乡人，日日雙眸滴清血。"]', '诗', 'shi', '', NULL, '古塞下曲四首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e88bc8-47d9-41dc-9416-50be12c9ab9f', '古塞下曲四首 四', '古塞下曲四首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["狼煙在陣雲，匈奴愛輕敵。","領兵不知數，牛羊復吞磧。","嚴冬大河枯，嫖姚去深擊。","戰血染黃沙，風吹暎天赤。"]', '["狼煙在陣云，匈奴愛轻敵。","領兵不知數，牛羊复吞磧。","嚴冬大河枯，嫖姚去深擊。","戰血染黄沙，风吹暎天赤。"]', '诗', 'shi', '', NULL, '古塞下曲四首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71da2ffd-7f42-4700-afee-3a6fe0dd1a02', '鼓腹曲', '鼓腹曲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我昔不幸兮遭百罹，蒼蒼留我兮到好時。","耳聞鐘鼓兮生豐肌，白髮却黑兮自不知。","東鄰老人好吹笛，倉囤峨峨穀多赤。","餅紅鰕兮㭊麋腊，有酒如濁醯兮呼我喫。","往往醉倒潢洿之水邊兮人盡識，孰云六五帝兮四三皇。","如夔如龍羞如龔黃，吾不知此之言兮是何之言兮。"]', '["我昔不幸兮遭百罹，蒼蒼留我兮到好时。","耳闻鐘鼓兮生豐肌，白髮却黑兮自不知。","东鄰老人好吹笛，倉囤峨峨穀多赤。","餅紅鰕兮㭊麋腊，有酒如濁醯兮呼我喫。","往往醉倒潢洿之水邊兮人尽識，孰云六五帝兮四三皇。","如夔如龙羞如龔黄，吾不知此之言兮是何之言兮。"]', '诗', 'shi', '', NULL, '鼓腹曲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67eda351-739f-4349-aef7-3793896a3c4e', '經曠禪師院', '經曠禪師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["吾師楞伽山中人，氣岸古淡僧麒麟。","曹溪老兄一與語，金玉聲利。","泥棄唾委，兀兀如頑雲。","驪珠兮固難價其價，靈芝兮何以根其根。","真貌枯槁言樸略，衲衣爛黑燒嶽痕。","憶昔十四五年前苦寒節，禮師問師楞伽月。","此時師握玉麈尾，報我却云非日月。","一敲粉碎狂性歇，庭松無韻冷撼骨。","搔窗擦簷數枝雪，邇來流浪于吳越。","一片閑雲空皎潔，再來尋師已蟬蛻。","薝蔔枝枯醴泉竭，水檀香火遺影在。","甘露松枝月中折，寶師往日真隱心，今日不能墮雙血。"]', '["吾師楞伽山中人，氣岸古淡僧麒麟。","曹溪老兄一與語，金玉声利。","泥棄唾委，兀兀如頑云。","驪珠兮固难價其價，靈芝兮何以根其根。","真貌枯槁言樸略，衲衣爛黑燒嶽痕。","憶昔十四五年前苦寒節，禮師问師楞伽月。","此时師握玉麈尾，報我却云非日月。","一敲粉碎狂性歇，庭松無韻冷撼骨。","搔窗擦簷數枝雪，邇来流浪于吳越。","一片闲云空皎潔，再来尋師已蟬蛻。","薝蔔枝枯醴泉竭，水檀香火遺影在。","甘露松枝月中折，寶師往日真隐心，今日不能墮雙血。"]', '诗', 'shi', '', NULL, '經曠禪師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4135e905-70cf-4329-9c96-d95134949a77', '邊上作三首 一', '邊上作三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山無綠兮水無清，風既毒兮沙亦腥。","胡兒走馬疾飛鳥，聯翩射落雲中聲。"]', '["山無綠兮水無清，风既毒兮沙亦腥。","胡兒走马疾飞鸟，聯翩射落云中声。"]', '诗', 'shi', '', NULL, '邊上作三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe93599e-d985-4d78-bdb7-dddaa666cb29', '邊上作三首 二', '邊上作三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["陣雲忽向沙中起，探得胡兵過遼水。","堪嗟護塞征戍兒，未戰已疑身是鬼。"]', '["陣云忽向沙中起，探得胡兵過遼水。","堪嗟護塞征戍兒，未戰已疑身是鬼。"]', '诗', 'shi', '', NULL, '邊上作三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af42490e-26c5-4b68-8103-532d4fc6744f', '邊上作三首 三', '邊上作三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說青塚穴，中有白野狐。","時時出沙磧，向東而號呼。","號呼復號呼，畫師圖得無。"]', '["见说青塚穴，中有白野狐。","时时出沙磧，向东而號呼。","號呼复號呼，畫師圖得無。"]', '诗', 'shi', '', NULL, '邊上作三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34159e29-e317-4bd9-bc89-46f040bd8ecb', '送張拾遺赴施州司戶', '送張拾遺赴施州司戶', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["道之大道古太古，二字爲名爭莽鹵。","社稷安危在直言，須歷堯堦撾諫鼓。","恭聞吾皇至聖深無比，推席却几聽至理。","一言偶未合堯聰，賈生須看湘江水。","君不見頃者百官排闥赴延英，陽城不死存令名。","又不見仲尼遙奇司馬子，珮玉垂紳合如此。","公乎公乎施之掾，江上春風喜相見。","畏天之命復行行，芙蓉爲衣勝絁絹。","好音入耳應非久，三峽聞猨莫迴首。","且啜千年羹，醉巴酒。"]', '["道之大道古太古，二字爲名爭莽鹵。","社稷安危在直言，須歷堯堦撾諫鼓。","恭闻吾皇至聖深無比，推席却几听至理。","一言偶未合堯聰，賈生須看湘江水。","君不见頃者百官排闥赴延英，陽城不死存令名。","又不见仲尼遙奇司马子，珮玉垂紳合如此。","公乎公乎施之掾，江上春风喜相见。","畏天之命复行行，芙蓉爲衣勝絁絹。","好音入耳應非久，三峽闻猨莫迴首。","且啜千年羹，醉巴酒。"]', '诗', 'shi', '', NULL, '送張拾遺赴施州司戶 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c4ee12-b22c-433f-a82c-fd54538dd993', '書倪氏屋壁三首 一', '书倪氏屋壁三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["茶烹綠乳花暎簾，撐沙苦筍銀纖纖。","窗中山色青翠黏，主人於我情無厭。"]', '["茶烹綠乳花暎簾，撐沙苦筍銀纖纖。","窗中山色青翠黏，主人於我情無厭。"]', '诗', 'shi', '', NULL, '書倪氏屋壁三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e422260-dad4-4f42-8d01-eeb08e55baa3', '書倪氏屋壁三首 二', '书倪氏屋壁三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["白桑紅椹鶯咽咽，麵揉玉塵餅挑雪。","將爲數日已一月，主人於我特地切。"]', '["白桑紅椹鶯咽咽，麵揉玉塵餅挑雪。","將爲數日已一月，主人於我特地切。"]', '诗', 'shi', '', NULL, '書倪氏屋壁三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('416b638a-4f61-4c5f-be68-788367160801', '書倪氏屋壁三首 三', '书倪氏屋壁三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["水嬌草媚掩山路，睡槎鴛鴦如畫作。","春光靄靄忽已暮，主人剛地不放去。"]', '["水嬌草媚掩山路，睡槎鴛鴦如畫作。","春光靄靄忽已暮，主人剛地不放去。"]', '诗', 'shi', '', NULL, '書倪氏屋壁三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9477a2d1-3108-45a6-93e3-6b3f56d9bed6', '續姚梁公坐右銘', '續姚梁公坐右銘', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["善爲爾諸身，行爲爾性命。","禍福必可轉，莫慤言前定。","見人之得，如己之得。","則美無不克，見人之失。","如己之失，是亨貞吉。","反此之徒，天鬼必誅。","福先禍始，好殺滅[紀]。","不得不止，守謙寡慾。","善善惡惡，不得不作。","無見貴熱，諂走蹩躠。","無輕賤微，上下相依。","古聖著書，矻矻孳孳。","忠孝信行，越食逾衣。","生天地間，未或非假。","身危彩虹，景速奔馬。","胡不自彊，將升玉堂。","胡爲自墜，言虛行僞。","豔殃爾壽須戒，酒腐爾腸須畏。","勵志須至，撲滿必破。","非莫非於餙非，過莫過於文過。","及物陰功，子孫必封。","無恃文學，是司奇薄。","患隨不忍，害逐無足。","一此一彼，諧宮合徵。","親仁下問，立節求己。","惡木之陰匪陰，盜泉之水匪水。","世孚草草，能生幾幾。","直須如冰如玉，種桃種李。","嫉人之惡，酬恩報義。","忽己之慢，成人之美。","毋擔虛譽，無背至理。","恬和愻暢，沖融終始。","天人之行，盡此而已。","丁寧丁寧，戴髮含齒。"]', '["善爲爾諸身，行爲爾性命。","禍福必可轉，莫慤言前定。","见人之得，如己之得。","則美無不克，见人之失。","如己之失，是亨貞吉。","反此之徒，天鬼必誅。","福先禍始，好殺滅[紀]。","不得不止，守謙寡慾。","善善惡惡，不得不作。","無见貴熱，諂走蹩躠。","無轻賤微，上下相依。","古聖著书，矻矻孳孳。","忠孝信行，越食逾衣。","生天地间，未或非假。","身危彩虹，景速奔马。","胡不自彊，將升玉堂。","胡爲自墜，言虛行僞。","豔殃爾壽須戒，酒腐爾腸須畏。","勵志須至，撲满必破。","非莫非於餙非，過莫過於文過。","及物陰功，子孫必封。","無恃文学，是司奇薄。","患隨不忍，害逐無足。","一此一彼，諧宮合徵。","親仁下问，立節求己。","惡木之陰匪陰，盜泉之水匪水。","世孚草草，能生幾幾。","直須如冰如玉，種桃種李。","嫉人之惡，酬恩報義。","忽己之慢，成人之美。","毋擔虛譽，無背至理。","恬和愻暢，沖融終始。","天人之行，尽此而已。","丁寧丁寧，戴髮含齒。"]', '诗', 'shi', '', NULL, '續姚梁公坐右銘 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66725f40-86fd-4d39-b906-5bb47a7b5336', '上盧少卿覓千文', '上盧少卿覓千文', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["荆山有美玉，含華尚炳爛。","堪爲聖君璽，堪爲聖君案。","草木潤不彫，煙霞覆不散。","野人到山下，仰視星辰畔。","倘或如栗黃，保之上霄漢。"]', '["荆山有美玉，含华尚炳爛。","堪爲聖君璽，堪爲聖君案。","草木潤不彫，煙霞覆不散。","野人到山下，仰視星辰畔。","倘或如栗黄，保之上霄漢。"]', '诗', 'shi', '', NULL, '上盧少卿覓千文 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('548d265e-163c-4961-8869-1ccf7bf346aa', '謝盧少卿惠千文', '謝盧少卿惠千文', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["廬山有石鏡，高倚無塵垢。","晝景分煙蘿，夜魄侵星斗。","苞含物象列，搜照魚龍吼。","寄謝天地間，毫端皆我有。"]', '["廬山有石镜，高倚無塵垢。","晝景分煙蘿，夜魄侵星斗。","苞含物象列，搜照鱼龙吼。","寄謝天地间，毫端皆我有。"]', '诗', 'shi', '', NULL, '謝盧少卿惠千文 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd7213a-5931-48bb-bc52-933feeedf20d', '大蜀皇帝壽春節進堯銘舜頌二首 堯銘', '大蜀皇帝壽春節進堯銘舜頌二首 堯銘', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["金冊昭昭，列聖孤標。","仲尼有言，巍巍帝堯。","承天眷命，罔厥矜驕。","四德炎炎，堦蓂不凋。","永孚於休，垂衣飄颻。","吾皇則之，小心翼翼。","秉陽亭毒，不遑暇食。","土堦苔綠，茅茨雪滴。","君既天賦，相亦天錫。","德輈金鏡，以聖繼聖。","漢高將將，太宗兵柄。","吾皇則之，日新德盛。","朽索六馬，罔墜厥命。","熙熙蓼蕭，塊潤風調。","舞擎干羽，囿入蒭蕘。","既玉其葉，亦金其枝。","葉葉枝枝，百工允釐。","享國如堯，不疑不疑。"]', '["金冊昭昭，列聖孤標。","仲尼有言，巍巍帝堯。","承天眷命，罔厥矜驕。","四德炎炎，堦蓂不凋。","永孚於休，垂衣飄颻。","吾皇則之，小心翼翼。","秉陽亭毒，不遑暇食。","土堦苔綠，茅茨雪滴。","君既天賦，相亦天錫。","德輈金镜，以聖繼聖。","漢高將將，太宗兵柄。","吾皇則之，日新德盛。","朽索六马，罔墜厥命。","熙熙蓼蕭，塊潤风調。","舞擎干羽，囿入蒭蕘。","既玉其葉，亦金其枝。","葉葉枝枝，百工允釐。","享国如堯，不疑不疑。"]', '诗', 'shi', '', NULL, '大蜀皇帝壽春節進堯銘舜頌二首 堯銘 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3f76e0-612a-4477-b75c-48fc94778f2d', '大蜀皇帝壽春節進堯銘舜頌二首 舜頌', '大蜀皇帝壽春節進堯銘舜頌二首 舜頌', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高高歷山，有黍有粟。","皇皇大舜，合堯玄德。","五典克從，四門伊穆。","大道將行，天下爲公。","臨下有赫，選賢用能。","吾皇則之，無斁無逸。","綏厥品彙，光光得一。","千輻臨頂，十在隨蹕。","大哉大同，爲光爲龍。","吾皇則之，聖謀隆隆。","納隍孜孜，攷攷切切。","六宗是禋，五瑞斯列。","排麟環鳳，披香立雪。","四夷納賮，九圍有截。","昔救世師，降生竺乾。","壽春亦然，萬年萬年。"]', '["高高歷山，有黍有粟。","皇皇大舜，合堯玄德。","五典克從，四门伊穆。","大道將行，天下爲公。","臨下有赫，選賢用能。","吾皇則之，無斁無逸。","綏厥品彙，光光得一。","千輻臨頂，十在隨蹕。","大哉大同，爲光爲龙。","吾皇則之，聖謀隆隆。","納隍孜孜，攷攷切切。","六宗是禋，五瑞斯列。","排麟环鳳，披香立雪。","四夷納賮，九圍有截。","昔救世師，降生竺乾。","壽春亦然，万年万年。"]', '诗', 'shi', '', NULL, '大蜀皇帝壽春節進堯銘舜頌二首 舜頌 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1a79cf-d96c-429e-b422-8571a8be136a', '大蜀高祖潛龍日獻陳情偈頌', '大蜀高祖潛龙日獻陳情偈頌', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["有叟有叟，居岳之室。","忽振金湯，下彼巉崪。","聞蜀風景，地寧得一。","富人侯王，旦奭摩詰。","龍角日角，紫氣盤屈。","揭日月行，符湯禹出。","天步孔艱，橫流犯蹕。","穆穆蜀俗，整整師律。","髯髮垂雪，忠貞貫日。","四人蘇活，萬里豐謐。","無雨不膏，有露皆滴。","有叟有叟，無實行實。","一瓶一衲，既朴且質。","幸蒙顧盼，詞煖恩鬱。","軒鏡光中，願如善吉。"]', '["有叟有叟，居岳之室。","忽振金湯，下彼巉崪。","闻蜀风景，地寧得一。","富人侯王，旦奭摩詰。","龙角日角，紫氣盤屈。","揭日月行，符湯禹出。","天步孔艱，橫流犯蹕。","穆穆蜀俗，整整師律。","髯髮垂雪，忠貞貫日。","四人蘇活，万里豐謐。","無雨不膏，有露皆滴。","有叟有叟，無實行實。","一瓶一衲，既朴且質。","幸蒙顧盼，词煖恩鬱。","軒镜光中，願如善吉。"]', '诗', 'shi', '', NULL, '大蜀高祖潛龍日獻陳情偈頌 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab17b5a3-0877-4c22-b700-157aabd9e444', '寄大願和尚', '寄大願和尚', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["道朗居太山，達磨住熊耳。","手擎清涼月，靈光溢天地。","盡騎金師子，去世久已矣。","吾師隱廬岳，外念全刳削。","擲孔聖之日月，相空王之橐籥。","曾升麟德殿，譚無著。","賜衣三銖讓不著，唯思紅泉白石閣。","因隨裴楷離京索，邇來便止於匡霍。","瀑布千尋噴冷煙，旃檀一枝翹瘦鶴。","峴首故人清信在，千書萬書取不諾。","微人昔爲門下人，扣玄佩惠無邊垠。","自憐亦是師子子，未逾三載能嚬呻。","一從散席歸寧後，溪寺更有誰相親。","青山古木入白浪，赤松道士爲東鄰。","焚香西望情何極，不及曇詵淚空滴。","桐江太守社中人，還送郄超米千石。","寶書遽掩修章句，萬里空函亦何益。","終須一替辟虵人，未解融神出空寂。"]', '["道朗居太山，達磨住熊耳。","手擎清涼月，靈光溢天地。","尽騎金師子，去世久已矣。","吾師隐廬岳，外念全刳削。","擲孔聖之日月，相空王之橐籥。","曾升麟德殿，譚無著。","賜衣三銖讓不著，唯思紅泉白石閣。","因隨裴楷離京索，邇来便止於匡霍。","瀑布千尋噴冷煙，旃檀一枝翹瘦鹤。","峴首故人清信在，千书万书取不諾。","微人昔爲门下人，扣玄佩惠無邊垠。","自怜亦是師子子，未逾三載能嚬呻。","一從散席归寧後，溪寺更有誰相親。","青山古木入白浪，赤松道士爲东鄰。","焚香西望情何極，不及曇詵泪空滴。","桐江太守社中人，還送郄超米千石。","寶书遽掩修章句，万里空函亦何益。","終須一替辟虵人，未解融神出空寂。"]', '诗', 'shi', '', NULL, '寄大願和尚 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6bfbad-eb99-4f8e-981e-c84f2b56f23a', '上顧大夫', '上顧大夫', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["碧海漾仙洲，驪珠外無寶。","一岳倚青冥，羣山盡如草。","君侯聖朝瑞，動只關玄造。","誰云倚天劍，含霜在懷抱。","誰云青雲險，門前是平道。","洪民亦何幸，里巷清如掃。","至化無經綸，至神無祝禱。","即應炳文柄，孤平去浩浩。","即應調鼎味，比屋堪封保。","野人慕正化，來自海邊島。","經傳髻裏珠，詩學池中藻。","閉門十餘載，庭杉共枯槁。","今朝投至鑒，得不傾肝腦。","斯文如未精，歸山更探討。"]', '["碧海漾仙洲，驪珠外無寶。","一岳倚青冥，羣山尽如草。","君侯聖朝瑞，动只关玄造。","誰云倚天劍，含霜在懷抱。","誰云青云險，门前是平道。","洪民亦何幸，里巷清如掃。","至化無經綸，至神無祝禱。","即應炳文柄，孤平去浩浩。","即應調鼎味，比屋堪封保。","野人慕正化，来自海邊島。","經傳髻裏珠，诗学池中藻。","閉门十餘載，庭杉共枯槁。","今朝投至鑒，得不傾肝腦。","斯文如未精，归山更探討。"]', '诗', 'shi', '', NULL, '上顧大夫 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be6921ff-6aaa-43d8-a0d0-730a4c56e42a', '寒月送玄士入天台', '寒月送玄士入天台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["之子逍遙塵世薄，格淡於雲語如鶴。","相見唯談海上山，碧側青斜冷相沓。","芒鞋竹杖寒凍時，玉霄忽去非有期。","僮擔赤籠密雪裏，世人無人留得之。","想入紅霞路深邃，孤峰縱嘯仙飆起。","星精聚觀泣海鬼，月湧薄煙花點水。","送君丁寧有深旨，好尋佛窟遊銀地。","雪眉衲僧皆正氣，伊昔貞白先同此意。","若得神聖之藥，即莫忘遠相寄。"]', '["之子逍遙塵世薄，格淡於云語如鹤。","相见唯談海上山，碧側青斜冷相沓。","芒鞋竹杖寒凍时，玉霄忽去非有期。","僮擔赤籠密雪裏，世人無人留得之。","想入紅霞路深邃，孤峰縱嘯仙飆起。","星精聚观泣海鬼，月湧薄煙花点水。","送君丁寧有深旨，好尋佛窟游銀地。","雪眉衲僧皆正氣，伊昔貞白先同此意。","若得神聖之藥，即莫忘远相寄。"]', '诗', 'shi', '', NULL, '寒月送玄士入天台 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bffbe8d-b870-4677-915d-ce1cfe699e76', '上杜使君', '上杜使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["爲魚須處海，爲木須在岳。","一登君子堂，頓覺心寥廓。","右聽青女鏡，左聽宣尼鐸。","政術似蒲盧，詩情出沖漠。","從來苦清苦，近更加澹薄。","訟庭何所有，一隻兩隻鶴。","煙霞色擁墻，禾黍香侵郭。","嚴霜與美雨，皆從二天落。","蒼生苦瘡痍，如何盡消削。","聖君新雨露，更作誰恩渥。","即捉五色筆，密勿金鑾角。","即同房杜手，把乾坤橐籥。","休說卜圭峰，開門對林壑。"]', '["爲鱼須处海，爲木須在岳。","一登君子堂，頓覺心寥廓。","右听青女镜，左听宣尼鐸。","政術似蒲盧，诗情出沖漠。","從来苦清苦，近更加澹薄。","訟庭何所有，一隻兩隻鹤。","煙霞色擁墻，禾黍香侵郭。","嚴霜與美雨，皆從二天落。","蒼生苦瘡痍，如何尽消削。","聖君新雨露，更作誰恩渥。","即捉五色笔，密勿金鑾角。","即同房杜手，把乾坤橐籥。","休说卜圭峰，开门对林壑。"]', '诗', 'shi', '', NULL, '上杜使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fad8b1f-159f-4826-b7c2-14d4cb7b37e9', '送僧入馬頭山', '送僧入马头山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["馬頭寶峰，秀塞寒空。","有叟有叟，真隱其中。","無味醍醐，亦非般若。","白趾碧目，數百瀟灑。","苦竹大於杉，白熊臥如馬。","金鍾撼壑，布水噴瓦。","芙蓉堂開峰月入，岳精踏雪立屋下。","伊余解攀緣，已是非常者。","更有叟，獨往來，與我語。","情無剛彊，氣透今古。","竹笠援補，芒鞋藤乳。","北風倒人，乾雪不聚。","滿頭霜雪湯雪去，湯雪去。","無人及，空望真氣江上立。"]', '["马头寶峰，秀塞寒空。","有叟有叟，真隐其中。","無味醍醐，亦非般若。","白趾碧目，數百瀟灑。","苦竹大於杉，白熊臥如马。","金鍾撼壑，布水噴瓦。","芙蓉堂开峰月入，岳精踏雪立屋下。","伊余解攀緣，已是非常者。","更有叟，独往来，與我語。","情無剛彊，氣透今古。","竹笠援補，芒鞋藤乳。","北风倒人，乾雪不聚。","满头霜雪湯雪去，湯雪去。","無人及，空望真氣江上立。"]', '诗', 'shi', '', NULL, '送僧入馬頭山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf044ce-bd24-412c-88c7-de1224ad97e7', '上盧使君', '上盧使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["夔龍在廟堂，雖然有僉議。","蒼生得父母，自是天之意。","鄱陽氣候正，文物皆鮮媚。","金鏡有餘光，春風少閑地。","膺門倚寒碧，到者寧容易。","賓從皆鳳毛，爪牙悉猨臂。","樓臺千萬戶，錦繡龍歌沸。","大惠蟲鳥全，至嚴龍虎畏。","可憐召伯樹，婆裟不勝翠。","詩搜日月華，道嚥神仙味。","嘉樹白雀來，祥煙甘露墜。","中川一帶香，□開幽邃地。","逸少情有餘，東山境不啻。","恭聞聖天子，廊廟猶虛位。","應知黎庶心，只恐徵書至。"]', '["夔龙在廟堂，雖然有僉議。","蒼生得父母，自是天之意。","鄱陽氣候正，文物皆鲜媚。","金镜有餘光，春风少闲地。","膺门倚寒碧，到者寧容易。","賓從皆鳳毛，爪牙悉猨臂。","楼台千万戶，錦繡龙歌沸。","大惠蟲鸟全，至嚴龙虎畏。","可怜召伯樹，婆裟不勝翠。","诗搜日月华，道嚥神仙味。","嘉樹白雀来，祥煙甘露墜。","中川一带香，□开幽邃地。","逸少情有餘，东山境不啻。","恭闻聖天子，廊廟猶虛位。","應知黎庶心，只恐徵书至。"]', '诗', 'shi', '', NULL, '上盧使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec79aef-b871-4cd4-9020-2ae523d1c1db', '送顥雅禪師', '送顥雅禪師', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["霜鋒擗石鳥雀聚，帆凍陰飆吹不舉。","芬陀利香釋驎虎，幡幢冒雪爭迎取。","春光主，芙蓉堂窄堆花乳，手提金桴打金鼓。","天花娉婷下如雨，狻猊座上師子語。","苦却樂，樂却苦，盧至黃金忽如土。"]', '["霜鋒擗石鸟雀聚，帆凍陰飆吹不舉。","芬陀利香釋驎虎，幡幢冒雪爭迎取。","春光主，芙蓉堂窄堆花乳，手提金桴打金鼓。","天花娉婷下如雨，狻猊座上師子語。","苦却乐，乐却苦，盧至黄金忽如土。"]', '诗', 'shi', '', NULL, '送顥雅禪師 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad293cec-27a2-40e3-b276-dff5567b3c41', '和楊使君遊赤松山', '和楊使君游赤松山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["爲郡三星無一事，龔黃意外扳喬松。","日邊揚歷不爭路，雲外苔蘚須留蹤。","溪月未落漏滴滴，隼旟已入山重重。","捫蘿蓋輸山屐伴，駐斾不見朝霞濃。","乳猨劇黠掛險樹，露木翠脆生諸峰。","初平謝公道非遠，黯然物外心相逢。","石羊依稀齕瑤草，桃花彷彿開仙宮。","終當歸補吾君衮，好山好水那相容。"]', '["爲郡三星無一事，龔黄意外扳喬松。","日邊揚歷不爭路，云外苔蘚須留蹤。","溪月未落漏滴滴，隼旟已入山重重。","捫蘿蓋輸山屐伴，駐斾不见朝霞濃。","乳猨劇黠掛險樹，露木翠脆生諸峰。","初平謝公道非远，黯然物外心相逢。","石羊依稀齕瑤草，桃花彷彿开仙宮。","終當归補吾君衮，好山好水那相容。"]', '诗', 'shi', '', NULL, '和楊使君遊赤松山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cca6a4d-c12b-4615-8b65-d0cbc7bff23b', '送崔使君', '送崔使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["柳門柳門，芳草芊綿。","日日日日，黯然黯然。","子牟戀闕歸闕，王粲下樓相別。","食實得地，頗淹歲月。","今朝天子在上，合雪必雪。","況絳之牧，文行炳潔。","釋謂緣因，久昵清塵。","王嘉迎安，遠狎遺民。","嫓彼二子，厥或相似。","論文不文，話道無滓。","士有貴逼，勢不可遏。","麟步規矩，鳳翥昂枿。","峴首仁蹤項頻跋，商雲乳麝香可撮。","望塵□□連紫闥，吾皇必用整乾坤，莫忘江頭白頭達。"]', '["柳门柳门，芳草芊綿。","日日日日，黯然黯然。","子牟戀闕归闕，王粲下楼相別。","食實得地，頗淹歲月。","今朝天子在上，合雪必雪。","況絳之牧，文行炳潔。","釋謂緣因，久昵清塵。","王嘉迎安，远狎遺民。","嫓彼二子，厥或相似。","論文不文，話道無滓。","士有貴逼，勢不可遏。","麟步規矩，鳳翥昂枿。","峴首仁蹤項頻跋，商云乳麝香可撮。","望塵□□連紫闥，吾皇必用整乾坤，莫忘江头白头達。"]', '诗', 'shi', '', NULL, '送崔使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cc440c7-195a-4b79-87e6-4b7b20b8a260', '杜侯行', '杜侯行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天目連天搏秀氣，崢嶸作起新城地。","德門鍾秀光盛時，三虎八龍皆世瑞。","頃者天厖亂下鯨翻海，烽火崩騰照行在。","江表唯傳君子營，劍衝牛斗疏真宰。","金昆玉季輕三鼓，煮海懸魚臣節苦。","鴈影參差入瑞煙，荆花燦爛開仙圃。","我聞大中咸通真令主，相惟大杜兼小杜。","但能致君活國濟生人，亦何必須踏金梯，折桂樹。","宣宗懿宗調舜琴，大杜小杜爲殷霖。","出將入相兮功德深，生人受賜兮直至今。","杜侯兄弟繼之後，璞玉渾金美騰口。","常言一呼百萬何足云，終取封侯之印大如斗。","功聞吾皇似堯禹，搜索賢良皆面覩。","杜侯杜侯，君儻修令德，克有終，即必還爲大杜兼小杜。","人之戴兮天筆註，國之福兮天固祚。","四海無波八表臣，如今而後君看取。"]', '["天目連天搏秀氣，崢嶸作起新城地。","德门鍾秀光盛时，三虎八龙皆世瑞。","頃者天厖亂下鯨翻海，烽火崩腾照行在。","江表唯傳君子營，劍衝牛斗疏真宰。","金昆玉季轻三鼓，煮海懸鱼臣節苦。","鴈影參差入瑞煙，荆花燦爛开仙圃。","我闻大中咸通真令主，相惟大杜兼小杜。","但能致君活国濟生人，亦何必須踏金梯，折桂樹。","宣宗懿宗調舜琴，大杜小杜爲殷霖。","出將入相兮功德深，生人受賜兮直至今。","杜侯兄弟繼之後，璞玉渾金美腾口。","常言一呼百万何足云，終取封侯之印大如斗。","功闻吾皇似堯禹，搜索賢良皆面覩。","杜侯杜侯，君儻修令德，克有終，即必還爲大杜兼小杜。","人之戴兮天笔註，国之福兮天固祚。","四海無波八表臣，如今而後君看取。"]', '诗', 'shi', '', NULL, '杜侯行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc288e7-f096-45f4-ace3-eb1d795effdc', '偶作五首 一', '偶作五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["誰信心火多，多能焚大國。","誰信鬢上絲，莖莖出蠶腹。","嘗聞養蠶婦，未曉上桑樹。","下樹畏蠶飢，兒啼亦不顧。","一春膏血盡，豈止應王賦。","如何酷吏酷，盡爲搜將去。","蠶蛾爲蝶飛，僞葉空滿枝。","冤梭與恨機，一見一霑衣。"]', '["誰信心火多，多能焚大国。","誰信鬢上絲，莖莖出蠶腹。","嘗闻養蠶婦，未晓上桑樹。","下樹畏蠶飢，兒啼亦不顧。","一春膏血尽，豈止應王賦。","如何酷吏酷，尽爲搜將去。","蠶蛾爲蝶飞，僞葉空满枝。","冤梭與恨機，一见一霑衣。"]', '诗', 'shi', '', NULL, '偶作五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bd1fcda-a97c-44b6-9fcf-4fc1ceaf4df5', '偶作五首 二', '偶作五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["機生機，巧生巧，心鑊烘烘日煎炒。","闖蜀眉嚬遊海島，扶桑椹熟金烏飽。","金烏飽，飛復飛，四天下人眼眙眙。"]', '["機生機，巧生巧，心鑊烘烘日煎炒。","闖蜀眉嚬游海島，扶桑椹熟金烏飽。","金烏飽，飞复飞，四天下人眼眙眙。"]', '诗', 'shi', '', NULL, '偶作五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f08a3dd-01f6-46b5-908c-3bfd21e509da', '偶作五首 三', '偶作五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["孰云我輕薄，石頭如何喚作玉。","孰云我是非，隨邪逐惡又爭得。","古人終不事悠悠，一言道合死即休。","豈不見大鵬點翼蓋十洲，是何之物鳴啾啾。"]', '["孰云我轻薄，石头如何喚作玉。","孰云我是非，隨邪逐惡又爭得。","古人終不事悠悠，一言道合死即休。","豈不见大鵬点翼蓋十洲，是何之物鳴啾啾。"]', '诗', 'shi', '', NULL, '偶作五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf83f240-214a-4762-8364-fc752ecd5798', '偶作五首 四', '偶作五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["君子食即食，何必在珍華。","小人食不食，縱食如泥沙。","清歌且莫唱，妙舞亦休誇。","爾非鳳灸麒麟肉，焉能一掛於齒牙。","去來去來歸去來，紅泉正灑芙蓉霞。"]', '["君子食即食，何必在珍华。","小人食不食，縱食如泥沙。","清歌且莫唱，妙舞亦休誇。","爾非鳳灸麒麟肉，焉能一掛於齒牙。","去来去来归去来，紅泉正灑芙蓉霞。"]', '诗', 'shi', '', NULL, '偶作五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4845f4b5-bb3f-48b6-9108-a4f12eb5b5f7', '偶作五首 五', '偶作五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["君不見金陵風臺月榭煙霞光，如今五里十里野火燒茫茫。","君不見西施綠珠顏色可傾國，樂極悲來留不得。","君不見漢王力盡得乾坤，如何秋雨灑廟門。","銅臺老樹作精魅，金谷野狐多子孫。","幾許繁華幾更改，唯有堯舜周召丘軻似長在。","坐看樓閣成丘墟，莫話桑田變成海。","吾有清涼雪山雪，天上人間常皎潔。","茫茫慾火欲燒人，惆悵無因爲君說。"]', '["君不见金陵风台月榭煙霞光，如今五里十里野火燒茫茫。","君不见西施綠珠顏色可傾国，乐極悲来留不得。","君不见漢王力尽得乾坤，如何秋雨灑廟门。","銅台老樹作精魅，金谷野狐多子孫。","幾許繁华幾更改，唯有堯舜周召丘軻似长在。","坐看楼閣成丘墟，莫話桑田变成海。","吾有清涼雪山雪，天上人间常皎潔。","茫茫慾火欲燒人，惆悵無因爲君说。"]', '诗', 'shi', '', NULL, '偶作五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7822273d-bc96-4f18-9be7-e35f3434a460', '山中作', '山中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山爲水精宮，藉花無塵埃。","吟狂岳似動，筆落天瓊瓌。","伊余自樂道，不論才不才。","有時鬼笑兩三聲，疑是大謝小謝李白來。"]', '["山爲水精宮，藉花無塵埃。","吟狂岳似动，笔落天瓊瓌。","伊余自乐道，不論才不才。","有时鬼笑兩三声，疑是大謝小謝李白来。"]', '诗', 'shi', '', NULL, '山中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2920c9a1-bdab-4435-82e1-d47c75b7df5f', '聞前王使君在澤潞居', '闻前王使君在澤潞居', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["爲善無近名，竊名者得聲不如心，誠哉是言也。","使君聖朝瑞，乾符初刺婺。","德變人性靈，筆變人風土。","煙霞與蟲鳥，和氣將美雨。","千里與萬里，各各來相附。","信哉有良吏，玄讖應百數。","古人古人自古人，今日又見民歌六七袴。","不幸大寇崩騰來，孤城勢孤固難錮。","攀轅既不及，旌斾衝風露。","大駕已西幸，飄零何處去？","婺人空悲哀，對生祠泣沾莓苔。","忽聞暫寄河之北，兵強四面無塵埃。","唯祝鑾輿早歸來，用此咎繇仲虺才。","使四野霧廓，八紘鏡開。","皇天無親，長與善鄰，宜哉宜哉。"]', '["爲善無近名，竊名者得声不如心，誠哉是言也。","使君聖朝瑞，乾符初刺婺。","德变人性靈，笔变人风土。","煙霞與蟲鸟，和氣將美雨。","千里與万里，各各来相附。","信哉有良吏，玄讖應百數。","古人古人自古人，今日又见民歌六七袴。","不幸大寇崩腾来，孤城勢孤固难錮。","攀轅既不及，旌斾衝风露。","大駕已西幸，飄零何处去？","婺人空悲哀，对生祠泣沾莓苔。","忽闻暫寄河之北，兵強四面無塵埃。","唯祝鑾輿早归来，用此咎繇仲虺才。","使四野霧廓，八紘镜开。","皇天無親，长與善鄰，宜哉宜哉。"]', '诗', 'shi', '', NULL, '聞前王使君在澤潞居 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c68e9289-7c74-449f-ac83-6f8924d8b848', '將入匡山別芳晝二公二首 一', '將入匡山別芳晝二公二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["噴嵐堆黛塞寒碧，窗前古雪入白石。","臨岐約我來不來，若來須撥紅霞覓。"]', '["噴嵐堆黛塞寒碧，窗前古雪入白石。","臨岐約我来不来，若来須撥紅霞覓。"]', '诗', 'shi', '', NULL, '將入匡山別芳晝二公二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b52015-5f01-4243-ba21-b1e7289c9326', '將入匡山別芳晝二公二首 二', '將入匡山別芳晝二公二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["紅豆樹間滴紅雨，戀師不得依師住。","世情世界愁殺人，錦繡谷中歸舍去。"]', '["紅豆樹间滴紅雨，戀師不得依師住。","世情世界愁殺人，錦繡谷中归舍去。"]', '诗', 'shi', '', NULL, '將入匡山別芳晝二公二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6de0cbea-6106-46fb-83e3-3399c7e15958', '送楊秀才', '送楊秀才', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["北山峨峨香拂拂，翠漲青奔勢巉崪。","赤松君宅在其中，紫金爲墻珠作室。","玻璃門外仙獓睡，幢節森森絳煙密。","水精簾捲桃花開，文錦娉婷衆非一。","撫長離，坎答鼓。","花姑吹簫，弄玉起舞。","三萬八千爲半日，海涸鼇枯等閑覩。","愛共安期碁，苦識彭祖祖。","有時朝玉京，紅雲擁金虎。","石橋亦是神仙住，白鳳飛來又飛去。","五雲縹緲羽翼高，世人仰望心空勞。"]', '["北山峨峨香拂拂，翠漲青奔勢巉崪。","赤松君宅在其中，紫金爲墻珠作室。","玻璃门外仙獓睡，幢節森森絳煙密。","水精簾捲桃花开，文錦娉婷衆非一。","撫长離，坎答鼓。","花姑吹簫，弄玉起舞。","三万八千爲半日，海涸鼇枯等闲覩。","愛共安期碁，苦識彭祖祖。","有时朝玉京，紅云擁金虎。","石橋亦是神仙住，白鳳飞来又飞去。","五云縹緲羽翼高，世人仰望心空勞。"]', '诗', 'shi', '', NULL, '送楊秀才 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f235b793-9b94-4451-a5c4-14b30ed54060', '別杜將軍', '別杜將軍', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["伊余本是胡爲者，採蕈鋤茶在窮野。","偶披蓑笠事空王，餘力爲文擬何謝。","少年心在青雲端，知音滿地皆龍鸞。","遽逢天步艱難日，深藏溪谷空長歎。","偶出重圍遇英哲，留我江樓經歲月。","身隈玉帳香滿衣，夢歷金盆雨和雪。","東風來兮歌式微，深雲道人召來歸。","燕辭大廈兮將何爲，濛濛花雨兮鶯飛飛，一汀楊柳同依依。"]', '["伊余本是胡爲者，採蕈鋤茶在窮野。","偶披蓑笠事空王，餘力爲文擬何謝。","少年心在青云端，知音满地皆龙鸾。","遽逢天步艱难日，深藏溪谷空长歎。","偶出重圍遇英哲，留我江楼經歲月。","身隈玉帳香满衣，梦歷金盆雨和雪。","东风来兮歌式微，深云道人召来归。","燕辞大廈兮將何爲，濛濛花雨兮鶯飞飞，一汀楊柳同依依。"]', '诗', 'shi', '', NULL, '別杜將軍 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5daf4987-6227-49bf-8375-446332ed4f4e', '送夢上人歸京', '送梦上人归京', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["伊余龍鍾歸海涯，千山萬水情自怡。","夢公別我還上國，江邊慘執行遲遲。","向我道雲中覓伴未得伴，又示我數首新詩盡是詩。","只恐不如此，若如此如此，即須天子知。","蕭蕭金吹荆門口，槐菊鬬黃落葉走。","前程勝事未可涯，但空圭峰難入手。","蓮峰掌記韓拾遺，鴈行雍穆世所稀。","二十年前即別離，憑師一話吟朝飢。"]', '["伊余龙鍾归海涯，千山万水情自怡。","梦公別我還上国，江邊慘執行遲遲。","向我道云中覓伴未得伴，又示我數首新诗尽是诗。","只恐不如此，若如此如此，即須天子知。","蕭蕭金吹荆门口，槐菊鬬黄落葉走。","前程勝事未可涯，但空圭峰难入手。","蓮峰掌記韓拾遺，鴈行雍穆世所稀。","二十年前即別離，憑師一話吟朝飢。"]', '诗', 'shi', '', NULL, '送夢上人歸京 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59841f8a-df17-4d9d-99b8-3b447d3cc54a', '問岳禪師疾', '问岳禪師疾', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["世病如山岳，世醫皆拱手。","道病如金鎖，師遭鎖鎖否。","伊昔芙蓉頰，談經似主涉。","蘇合晝氤氳，天花似飛蝶。","覺樹垂實，魔輩刺疾。","病也不問，終不皴膝。","春光冉冉，不上爾質。","東風浩浩，謾入爾室。","云何斯人，而有斯疾。"]', '["世病如山岳，世醫皆拱手。","道病如金鎖，師遭鎖鎖否。","伊昔芙蓉頰，談經似主涉。","蘇合晝氤氳，天花似飞蝶。","覺樹垂實，魔輩刺疾。","病也不问，終不皴膝。","春光冉冉，不上爾質。","东风浩浩，謾入爾室。","云何斯人，而有斯疾。"]', '诗', 'shi', '', NULL, '問岳禪師疾 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f717aea-de1d-4c03-b5b4-2e84875a269d', '上荆南府主三讓德政碑', '上荆南府主三讓德政碑', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["明明赫赫中興主，動納諸隍冠前古。","四海英雄盡戢兵，皆如圪圪天金柱。","萬姓多論政與德，請樹豐碑似山岳。","一從寇滅二十年，琬琰雕鐫賜重疊。","荆州化風何卓異，寡欲無爲合天地。","雖立貞碑與衆殊，字字皆是吾皇意。","君侯捧碑西拜泣，臣且何人恩洊及。","鳳皇銜下雕龍文，德昧政虛爭敢立。","函封三奏心匍匐，堅讓此碑聲蓋國。","我恐江淹五色筆，作不立此碑之碑文不得。"]', '["明明赫赫中兴主，动納諸隍冠前古。","四海英雄尽戢兵，皆如圪圪天金柱。","万姓多論政與德，請樹豐碑似山岳。","一從寇滅二十年，琬琰雕鐫賜重叠。","荆州化风何卓異，寡欲無爲合天地。","雖立貞碑與衆殊，字字皆是吾皇意。","君侯捧碑西拜泣，臣且何人恩洊及。","鳳皇銜下雕龙文，德昧政虛爭敢立。","函封三奏心匍匐，堅讓此碑声蓋国。","我恐江淹五色笔，作不立此碑之碑文不得。"]', '诗', 'shi', '', NULL, '上荆南府主三讓德政碑 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c379ad7-41ed-418e-ba95-6dfb40b01eca', '施萬病丸', '施万病丸', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我聞昔有海上翁，鬚眉皎白塵土中。","葫蘆盛藥行如風，病者與藥皆惺憁。","藥王藥上親兄弟，救人急於己諸體。","玉毫調御偏讚揚，金輪釋梵咸歸禮。","賢守運心亦相似，不吝親親拘子子。","曾聞古德有深言，由來大士皆如此。"]', '["我闻昔有海上翁，鬚眉皎白塵土中。","葫蘆盛藥行如风，病者與藥皆惺憁。","藥王藥上親兄弟，救人急於己諸體。","玉毫調御偏讚揚，金輪釋梵咸归禮。","賢守運心亦相似，不吝親親拘子子。","曾闻古德有深言，由来大士皆如此。"]', '诗', 'shi', '', NULL, '施萬病丸 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e3beb3e-384b-415d-8b9a-92e7b3b3c0af', '甘雨應祈', '甘雨應祈', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["春雨偶愆期，草木亦未覺。","君侯不遑處，退食或閉閣。","東海浪滔滔，西江波漠漠。","得不願身爲大虬，金其角，玉其甲。","一吸再喢，雲平霧匝。","華暢九有，清傾六合。","使不蘇者蘇，不足者足。","情通上玄，如膏綿綿。","有叟有叟，鼓腹歌於道邊。","歌曰：麥苗芃芃兮鶬鶊飛，日出而作兮日入歸，如彼草木兮雨露肥。","古人三樂兮，我樂多之。","天之成兮，地之平兮。","柘系黃兮，瓠葉青兮。","乳女啼兮，蒸黍馨兮。","炙背捫虱兮，復何經營兮。"]', '["春雨偶愆期，草木亦未覺。","君侯不遑处，退食或閉閣。","东海浪滔滔，西江波漠漠。","得不願身爲大虬，金其角，玉其甲。","一吸再喢，云平霧匝。","华暢九有，清傾六合。","使不蘇者蘇，不足者足。","情通上玄，如膏綿綿。","有叟有叟，鼓腹歌於道邊。","歌曰：麦苗芃芃兮鶬鶊飞，日出而作兮日入归，如彼草木兮雨露肥。","古人三乐兮，我乐多之。","天之成兮，地之平兮。","柘系黄兮，瓠葉青兮。","乳女啼兮，蒸黍馨兮。","炙背捫虱兮，复何經營兮。"]', '诗', 'shi', '', NULL, '甘雨應祈 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf396a5-34c7-4f7e-80e2-4ed286d89ac7', '寄韓團練', '寄韓團練', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["真宰動洪鑪，萬物皆消息。","唯有三珠樹，不用東風力。","君子天廟器，頭骨何巉崱。","海內久聞名，江西偶相識。","誰不有詩機，麟龍不解織。","誰不有心地，蘭茝不曾植。","多君二俱作，獨立千仞壁。","話道出先天，憑師動臻極。","青霄鴈行律，紅露荆花滴。","偶然成遠別，別後長相憶。","行至鄱陽郡，又見謝安石。","留我遇殘冬，身心苦恬寂。","江上春又至，引頸山空積。","何日再相逢，天香滿瑤席。"]', '["真宰动洪鑪，万物皆消息。","唯有三珠樹，不用东风力。","君子天廟器，头骨何巉崱。","海內久闻名，江西偶相識。","誰不有诗機，麟龙不解织。","誰不有心地，蘭茝不曾植。","多君二俱作，独立千仞壁。","話道出先天，憑師动臻極。","青霄鴈行律，紅露荆花滴。","偶然成远別，別後长相憶。","行至鄱陽郡，又见謝安石。","留我遇殘冬，身心苦恬寂。","江上春又至，引頸山空積。","何日再相逢，天香满瑤席。"]', '诗', 'shi', '', NULL, '寄韓團練 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad8119c-a952-494d-8d13-2bfadfa43c05', '春野作五首 一', '春野作五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["閑步淺青平綠，流水征車自逐。","誰家挾彈少年，擬打紅衣[啄]木。"]', '["闲步淺青平綠，流水征车自逐。","誰家挾彈少年，擬打紅衣[啄]木。"]', '诗', 'shi', '', NULL, '春野作五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d301c1b-a0f9-4ce9-a299-74fe08a31036', '春野作五首 二', '春野作五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山花雨打盡，滿地如爛錦。","遠尋鷓鴣雛，拾得一團蕈。"]', '["山花雨打尽，满地如爛錦。","远尋鷓鴣雛，拾得一團蕈。"]', '诗', 'shi', '', NULL, '春野作五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d591d4-9cbd-4424-bab5-3f75dd8a2965', '春野作五首 三', '春野作五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["大牛苦耕田，乳犢望似泣。","萬事皆天意，綠草頭蕺蕺。"]', '["大牛苦耕田，乳犢望似泣。","万事皆天意，綠草头蕺蕺。"]', '诗', 'shi', '', NULL, '春野作五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49963281-37ec-4930-b46d-2167f9799321', '春野作五首 四', '春野作五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["斜陽射破冢，髑髏半出地。","不知誰氏子，猶自作意氣。"]', '["斜陽射破冢，髑髏半出地。","不知誰氏子，猶自作意氣。"]', '诗', 'shi', '', NULL, '春野作五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d1d929-ec98-4841-8097-b47179050aa9', '春野作五首 五', '春野作五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["拋牛沙上鬬百草，鉏隴老人又太老。","薄煙漠漠覆桑棗，戴嵩醉後取次掃。"]', '["拋牛沙上鬬百草，鉏隴老人又太老。","薄煙漠漠覆桑棗，戴嵩醉後取次掃。"]', '诗', 'shi', '', NULL, '春野作五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea2805c-d7d1-4005-9f72-9fd3b606a410', '深山逢老僧二首 一', '深山逢老僧二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["衲衣線麄心似月，自把短鋤鋤榾柮。","青石溪邊踏葉行，數片雲隨兩眉雪。"]', '["衲衣線麄心似月，自把短鋤鋤榾柮。","青石溪邊踏葉行，數片云隨兩眉雪。"]', '诗', 'shi', '', NULL, '深山逢老僧二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76124fa1-0a96-470d-a832-8f0742278cd5', '深山逢老僧二首 二', '深山逢老僧二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山童貌頑名乞乞，放火燒畬采崖蜜。","擔頭何物帶山香，一籮白蕈一籮栗。"]', '["山童貌頑名乞乞，放火燒畬采崖蜜。","擔头何物带山香，一籮白蕈一籮栗。"]', '诗', 'shi', '', NULL, '深山逢老僧二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('565fe987-81c5-439e-98c5-5600c795adfa', '道情偈', '道情偈', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["草木亦有性，與我將不別。","我若似草木，成道無時節。","世人不會道，向道却嗔道。","傷嗟此輩人，寶山不得寶。"]', '["草木亦有性，與我將不別。","我若似草木，成道無时節。","世人不會道，向道却嗔道。","傷嗟此輩人，寶山不得寶。"]', '诗', 'shi', '', NULL, '道情偈 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1605dbfb-06a9-4fe7-9dcf-b8932826532c', '懷二三朝友', '懷二三朝友', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["傷心復傷心，流光似飛電。","有惠驪龍十斛珠，不如一見君子面。","愁人復愁人，滿眼皆埃塵。","有惠黃金一萬斤，不如一見於仁人。","我昔讀詩書，如今盡拋也。","只記得田叔孟溫舒，帝王滿口呼長者。"]', '["傷心复傷心，流光似飞電。","有惠驪龙十斛珠，不如一见君子面。","愁人复愁人，满眼皆埃塵。","有惠黄金一万斤，不如一见於仁人。","我昔读诗书，如今尽拋也。","只記得田叔孟溫舒，帝王满口呼长者。"]', '诗', 'shi', '', NULL, '懷二三朝友 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3dc4fbc-522c-4834-9cbd-ef747969f1e2', '偶作', '偶作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["君子稱一善，馨香遍九垓。","小人妬一善，處處生嫌猜。","口如暴死人，鐵尺抝不開。","稂莠蝕田髓，積陰成冬雷。","因知咋舌人，千古空悠哉。"]', '["君子稱一善，馨香遍九垓。","小人妬一善，处处生嫌猜。","口如暴死人，鐵尺抝不开。","稂莠蝕田髓，積陰成冬雷。","因知咋舌人，千古空悠哉。"]', '诗', 'shi', '', NULL, '偶作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2c787e-9399-499b-b5f8-c71be1879676', '義士行', '義士行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["先生先生不可遇，愛平不平眉斗豎。","黃昏雨雹空似黳，別我不知何處去。"]', '["先生先生不可遇，愛平不平眉斗豎。","黄昏雨雹空似黳，別我不知何处去。"]', '诗', 'shi', '', NULL, '義士行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cffd0769-b125-4945-896d-d4caf42ec0ed', '觀懷素草書歌', '观懷素草书歌', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["張顛顛後顛非顛，直至懷素之顛始是顛。","師不譚經不說禪，筋力唯於草書朽。","顛狂却恐是神仙，有神助兮人莫及。","鐵石畫兮墨須入，金尊竹葉數斗餘。","半斜半傾山衲濕，醉來把筆獰如虎。","粉壁素屏不問主，亂拏亂抹無規矩。","羅剎石上坐伍子胥，蒯通八字立對漢高祖。","勢崩騰兮不可止，天機暗轉鋒鋩裏。","閃電光邊霹靂飛，古栢身中𣵡龍死。","駭人心兮目眓{目臭}，頓人足兮神辟易。","乍如沙場大戰後，斷槍橛箭皆狼籍。","又似深山朽石上，古病松枝掛鐵錫。","月兔筆，天竈墨，斜鑿黃金側剉玉。","珊瑚枝長大束束，天馬驕獰不可勒。","東却西，南又北，倒又起，斷復續。","忽如鄂公喝住單雄信，秦王肩上𠞈著棗木槊。","懷素師，懷素師，若不是星辰降瑞，即必是河岳孕靈。","固宜須冷笑逸少，爭得不心醉伯英。","天台古杉一千尺，崖崩劁折何崢嶸。","或細微，仙衣半拆金線垂。","或妍媚，桃花半紅公子醉。","我恐山爲墨兮磨海水，天與筆兮書大地。","乃能畧展狂僧意，常恨與師不相識。","一見此書空歎息，伊昔張渭任華葉季良。","數子贈歌豈虛飾，所不足者渾未曾道著其神力。","石橋被燒燒，良玉土不蝕。","錐畫沙兮印印泥，世人世人爭得測。","知師雄名在世間，明月清風有何極。"]', '["張顛顛後顛非顛，直至懷素之顛始是顛。","師不譚經不说禪，筋力唯於草书朽。","顛狂却恐是神仙，有神助兮人莫及。","鐵石畫兮墨須入，金尊竹葉數斗餘。","半斜半傾山衲濕，醉来把笔獰如虎。","粉壁素屏不问主，亂拏亂抹無規矩。","羅剎石上坐伍子胥，蒯通八字立对漢高祖。","勢崩腾兮不可止，天機暗轉鋒鋩裏。","閃電光邊霹靂飞，古栢身中𣵡龙死。","駭人心兮目眓{目臭}，頓人足兮神辟易。","乍如沙場大戰後，斷槍橛箭皆狼籍。","又似深山朽石上，古病松枝掛鐵錫。","月兔笔，天竈墨，斜鑿黄金側剉玉。","珊瑚枝长大束束，天马驕獰不可勒。","东却西，南又北，倒又起，斷复續。","忽如鄂公喝住單雄信，秦王肩上𠞈著棗木槊。","懷素師，懷素師，若不是星辰降瑞，即必是河岳孕靈。","固宜須冷笑逸少，爭得不心醉伯英。","天台古杉一千尺，崖崩劁折何崢嶸。","或細微，仙衣半拆金線垂。","或妍媚，桃花半紅公子醉。","我恐山爲墨兮磨海水，天與笔兮书大地。","乃能畧展狂僧意，常恨與師不相識。","一见此书空歎息，伊昔張渭任华葉季良。","數子贈歌豈虛飾，所不足者渾未曾道著其神力。","石橋被燒燒，良玉土不蝕。","錐畫沙兮印印泥，世人世人爭得測。","知師雄名在世间，明月清风有何極。"]', '诗', 'shi', '', NULL, '觀懷素草書歌 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5689d532-07b4-467b-9725-ee2642c76144', '送盧舍人三首 一', '送盧舍人三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一曰：勸君不用登峴首山，讀羊祜碑。","男兒事業須自奇，此碑山頭如日月。","日日照人人不知，人不知，青山白雲徒爾爲。"]', '["一曰：勸君不用登峴首山，读羊祜碑。","男兒事業須自奇，此碑山头如日月。","日日照人人不知，人不知，青山白云徒爾爲。"]', '诗', 'shi', '', NULL, '送盧舍人三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19185848-0d6e-423a-9b40-54fb433442cb', '送盧舍人三首 二', '送盧舍人三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["二曰：勸君登商山，不用覓商山皓。","雲深雪深騾馬倒，我願終南太華變爲金。","吾后見之不爲寶，我願九州四海紙。","幅幅與君爲諫草，使躡卨踐夔。","逢軒見皞，日環五色。","是物得老，如此即商山皓。","商山皓，君不用討他，他必來相討。"]', '["二曰：勸君登商山，不用覓商山皓。","云深雪深騾马倒，我願終南太华变爲金。","吾后见之不爲寶，我願九州四海紙。","幅幅與君爲諫草，使躡卨踐夔。","逢軒见皞，日环五色。","是物得老，如此即商山皓。","商山皓，君不用討他，他必来相討。"]', '诗', 'shi', '', NULL, '送盧舍人三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc8539e-1fd5-414a-a3a7-f8cf2e10e1dc', '送盧舍人三首 三', '送盧舍人三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["三曰：君不見釋梵諸天壽億垓，天上人間去復來。","君又不見紫金爲輪一千幅，寶洲□四皆臣伏。","輪王釋梵作何因，祗是弘隆大乘福。","自古皇王與賢哲，頂敬心師刻金玉。","報通三世釋迦言，莫將梁武爲題目。","君不見近代韋裴蔣與蕭，文房書府師百僚。","代天理物映千古，布髮掩泥非一朝。","大哉釋梵輪王璞，已矣何人繼先覺。","行行珍重寄斯言，斯言不是尋常曲。"]', '["三曰：君不见釋梵諸天壽億垓，天上人间去复来。","君又不见紫金爲輪一千幅，寶洲□四皆臣伏。","輪王釋梵作何因，祗是弘隆大乘福。","自古皇王與賢哲，頂敬心師刻金玉。","報通三世釋迦言，莫將梁武爲題目。","君不见近代韋裴蔣與蕭，文房书府師百僚。","代天理物映千古，布髮掩泥非一朝。","大哉釋梵輪王璞，已矣何人繼先覺。","行行珍重寄斯言，斯言不是尋常曲。"]', '诗', 'shi', '', NULL, '送盧舍人三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5548982c-af27-4a74-988e-98d95c66758a', '宿深村', '宿深村', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["行行一宿深村裏，雞犬豐年鬧如市。","黃昏見客合家喜，月下取魚戽塘水。"]', '["行行一宿深村裏，雞犬豐年鬧如市。","黄昏见客合家喜，月下取鱼戽塘水。"]', '诗', 'shi', '', NULL, '宿深村 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cef18895-f2cc-4542-9b66-b51473e3d1f6', '黃鶯', '黄鶯', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一種爲春禽，花中開羽翼。","如何此鳥身，便是黃金色。","黃金色，若逢竹實終不食。"]', '["一種爲春禽，花中开羽翼。","如何此鸟身，便是黄金色。","黄金色，若逢竹實終不食。"]', '诗', 'shi', '', NULL, '黃鶯 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca56169-b0b3-4dd6-b8ef-9f013f4b193e', '送越將歸會稽', '送越將归會稽', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["面如玉盤身八尺，燕語清獰戰袍窄。","古嶽龍腥一匣霜，江上相逢雙眼碧。","冉冉春光方婉娩，黯然別我歸稽巘。","他年必帥邯鄲兒，與我殺輕班定遠。"]', '["面如玉盤身八尺，燕語清獰戰袍窄。","古嶽龙腥一匣霜，江上相逢雙眼碧。","冉冉春光方婉娩，黯然別我归稽巘。","他年必帥邯鄲兒，與我殺轻班定远。"]', '诗', 'shi', '', NULL, '送越將歸會稽 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c26b989-0b62-4d52-9f62-fc5c71eb945b', '別仙客', '別仙客', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["巨鼇頭縮翻仙翠，蟠桃爛落珊瑚地。","浪濺霓旌濕鵬翅，畧別千年太容易。"]', '["巨鼇头縮翻仙翠，蟠桃爛落珊瑚地。","浪濺霓旌濕鵬翅，畧別千年太容易。"]', '诗', 'shi', '', NULL, '別仙客 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b307d65-7a4f-41ad-9ba3-8c1edd4589c9', '寒江上望', '寒江上望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["荒岸燒未死，白雲癡不動。","極目無人行，浪打取魚籠。"]', '["荒岸燒未死，白云癡不动。","極目無人行，浪打取鱼籠。"]', '诗', 'shi', '', NULL, '寒江上望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0ab538-c4ad-42ba-8ed3-4c8a7ca1b96b', '讀唐史', '读唐史', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我愛李景伯，內宴執良規。","君臣道昭彰，天顏終熙怡。","大簸怕清風，糠粃繚亂飛。","洪鑪烹五金，黃金終自奇。","大哉爲忠臣，捨此何所之。"]', '["我愛李景伯，內宴執良規。","君臣道昭彰，天顏終熙怡。","大簸怕清风，糠粃繚亂飞。","洪鑪烹五金，黄金終自奇。","大哉爲忠臣，捨此何所之。"]', '诗', 'shi', '', NULL, '讀唐史 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('593ed65c-1082-495d-b677-a341751b2a35', '樵叟', '樵叟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["樵父貌飢帶塵土，自言一生苦寒苦。","擔頭擔箇赤瓷甖，斜陽獨立濛籠塢。"]', '["樵父貌飢带塵土，自言一生苦寒苦。","擔头擔箇赤瓷甖，斜陽独立濛籠塢。"]', '诗', 'shi', '', NULL, '樵叟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff25c2e2-054b-4968-a63f-f779da127d60', '春山行', '春山行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["重疊太古色，濛濛花雨時。","好峰行恐盡，流水語相隨。","黑壤生紅黍，黃猨領白兒。","因思石橋月，曾與故人期。"]', '["重叠太古色，濛濛花雨时。","好峰行恐尽，流水語相隨。","黑壤生紅黍，黄猨領白兒。","因思石橋月，曾與故人期。"]', '诗', 'shi', '', NULL, '春山行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68d30fd3-058d-4305-b4f6-e62bc97535b0', '送諫官南遷', '送諫官南遷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["危行危言者，從天落海涯。","如斯爲遠客，始是好男兒。","瘴雜交州雨，犀揩馬援碑。","不知千萬里，誰復識辛毗。"]', '["危行危言者，從天落海涯。","如斯爲远客，始是好男兒。","瘴杂交州雨，犀揩马援碑。","不知千万里，誰复識辛毗。"]', '诗', 'shi', '', NULL, '送諫官南遷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f578b08-7dd6-414e-bcc7-23acbed69df6', '懷香爐峰道人', '懷香爐峰道人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常思峰頂叟，石窟土爲牀。","日日先見日，煙霞多異香。","冥心同槁木，掃雪帶微陽。","終必相尋去，斯人不可忘。"]', '["常思峰頂叟，石窟土爲牀。","日日先见日，煙霞多異香。","冥心同槁木，掃雪带微陽。","終必相尋去，斯人不可忘。"]', '诗', 'shi', '', NULL, '懷香爐峰道人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9b6763-fff0-4951-bf14-acc5bdc07a43', '觀李翰林真二首 一', '观李翰林真二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["日角浮紫氣，凜然塵外清。","雖稱李太白，知是那星精。","御宴千鍾飲，蕃書一筆成。","宜哉杜工部，不錯道騎鯨。"]', '["日角浮紫氣，凜然塵外清。","雖稱李太白，知是那星精。","御宴千鍾饮，蕃书一笔成。","宜哉杜工部，不錯道騎鯨。"]', '诗', 'shi', '', NULL, '觀李翰林真二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42c920e-9a02-46aa-868c-65922521e2f8', '觀李翰林真二首 二', '观李翰林真二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["誰氏子丹青，毫端曲有靈。","屹如山忽墮，爽似酒初醒。","天馬難攏勒，仙房久閉扃。","若非如此輩，何以傲彤庭。"]', '["誰氏子丹青，毫端曲有靈。","屹如山忽墮，爽似酒初醒。","天马难攏勒，仙房久閉扃。","若非如此輩，何以傲彤庭。"]', '诗', 'shi', '', NULL, '觀李翰林真二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cde46e0-fe46-48f5-a25e-078b75bf1f3c', '晚泊湘江作', '晚泊湘江作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["煙浪瀁秋色，高吟似有鄰。","一輪湘渚月，萬古獨醒人。","岸濕穿花遠，風香禱廟頻。","祗應諛佞者，到此不傷神。"]', '["煙浪瀁秋色，高吟似有鄰。","一輪湘渚月，万古独醒人。","岸濕穿花远，风香禱廟頻。","祗應諛佞者，到此不傷神。"]', '诗', 'shi', '', NULL, '晚泊湘江作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec8c54b-2eda-48f6-b177-99b116d27b07', '淮上逢故人', '淮上逢故人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["故園離亂後，十載始逢君。","長恨南熏奏，尋常只自聞。","荒窗秋見岳，赤地夜生雲。","莫歎謀身晚，中興正用文。"]', '["故园離亂後，十載始逢君。","长恨南熏奏，尋常只自闻。","荒窗秋见岳，赤地夜生云。","莫歎謀身晚，中兴正用文。"]', '诗', 'shi', '', NULL, '淮上逢故人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('908f68ec-e7d3-4d08-9564-19f4b10d12ba', '讀杜工部集二首 一', '读杜工部集二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["造化拾無遺，唯應杜甫詩。","豈非玄域橐，奪得古人旗。","日月精華薄，山川氣概卑。","古今吟不盡，惆悵不同時。"]', '["造化拾無遺，唯應杜甫诗。","豈非玄域橐，奪得古人旗。","日月精华薄，山川氣概卑。","古今吟不尽，惆悵不同时。"]', '诗', 'shi', '', NULL, '讀杜工部集二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e7c374d-32dc-449d-9f57-ee519658a459', '讀杜工部集二首 二', '读杜工部集二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["甫也道亦喪，孤身出蜀城。","彩毫終不撅，白雲更能輕。","命薄相如命，名齊李白名。","不知耒陽令，何以葬先生。"]', '["甫也道亦喪，孤身出蜀城。","彩毫終不撅，白云更能轻。","命薄相如命，名齊李白名。","不知耒陽令，何以葬先生。"]', '诗', 'shi', '', NULL, '讀杜工部集二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d77052-7f2e-430e-9e2c-50a000250542', '題簡禪師院', '題簡禪師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["機忘室亦空，靜與沃洲同。","唯有半庭竹，能生竟日風。","思山海月上，出定印香終。","繼後傳衣者，還須立雪中。"]', '["機忘室亦空，静與沃洲同。","唯有半庭竹，能生竟日风。","思山海月上，出定印香終。","繼後傳衣者，還須立雪中。"]', '诗', 'shi', '', NULL, '題簡禪師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a40f2eb-0402-4c4a-aa1d-008f15f26862', '讀劉得仁賈島集二首 一', '读劉得仁賈島集二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["二公俱作者，其奈亦迂儒。","且有諸峰在，何將一第吁。","句還如菡萏，誰復贈襜褕。","想得重泉下，依前與衆殊。"]', '["二公俱作者，其奈亦迂儒。","且有諸峰在，何將一第吁。","句還如菡萏，誰复贈襜褕。","想得重泉下，依前與衆殊。"]', '诗', 'shi', '', NULL, '讀劉得仁賈島集二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('001a7fb3-c61b-42aa-82bc-28d470be9b08', '讀劉得仁賈島集二首 二', '读劉得仁賈島集二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["役思曾衝尹，多言阻國親。","桂枝何所直，陋巷不勝貧。","馬病唯湯雪，門荒劣有人。","伊余吟亦苦，爲爾一眉嚬。"]', '["役思曾衝尹，多言阻国親。","桂枝何所直，陋巷不勝貧。","马病唯湯雪，门荒劣有人。","伊余吟亦苦，爲爾一眉嚬。"]', '诗', 'shi', '', NULL, '讀劉得仁賈島集二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('175daf3f-fa38-4918-b8b0-59a838cc0d40', '天台老僧', '天台老僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["獨住無人處，松龕嶽色侵。","僧中九十臘，雲外一生心。","白髮垂不剃，青眸笑轉深。","猶能指孤月，爲我暫開襟。"]', '["独住無人处，松龕嶽色侵。","僧中九十臘，云外一生心。","白髮垂不剃，青眸笑轉深。","猶能指孤月，爲我暫开襟。"]', '诗', 'shi', '', NULL, '天台老僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c5a9be-4fc0-4953-9341-83e924d9b2b0', '經費隱君舊宅', '經費隐君旧宅', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["巉巖玉九株，秀濕掩蒼梧。","祥瑞久不出，羲軒消得無。","雨和高瀑濁，燒熁大櫧枯。","到此思歸去，迢迢隔五湖。"]', '["巉巖玉九株，秀濕掩蒼梧。","祥瑞久不出，羲軒消得無。","雨和高瀑濁，燒熁大櫧枯。","到此思归去，迢迢隔五湖。"]', '诗', 'shi', '', NULL, '經費隱君舊宅 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c7bf66-3a40-487d-82fe-9af8017e6562', '秋末懷舊山', '秋末懷旧山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昔住匡廬北，無人知姓名。","侵雲收穀粟，引蟻上柑橙。","寒雨雪兼落，枯林虎獨行。","誰能將白髮，共向此中生。"]', '["昔住匡廬北，無人知姓名。","侵云收穀粟，引蟻上柑橙。","寒雨雪兼落，枯林虎独行。","誰能將白髮，共向此中生。"]', '诗', 'shi', '', NULL, '秋末懷舊山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1610bf-679f-49e6-8ab3-2e926f45ccc3', '春過鄱陽湖', '春過鄱陽湖', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["百慮片帆下，風波極目看。","吳山兼鳥沒，楚色入衣寒。","過此愁人處，始知行路難。","夕陽沙島上，回首一長歎。"]', '["百慮片帆下，风波極目看。","吳山兼鸟沒，楚色入衣寒。","過此愁人处，始知行路难。","夕陽沙島上，回首一长歎。"]', '诗', 'shi', '', NULL, '春過鄱陽湖 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd191111-d21a-4629-b8ea-746b065847e0', '寄僧野和尚', '寄僧野和尚', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鳥外更誰親，諸峰即四鄰。","白頭寒枕石，青衲爛無塵。","橡栗堆行徑，猨猴遶定身。","儻然重結社，願作掃壇人。"]', '["鸟外更誰親，諸峰即四鄰。","白头寒枕石，青衲爛無塵。","橡栗堆行徑，猨猴遶定身。","儻然重結社，願作掃壇人。"]', '诗', 'shi', '', NULL, '寄僧野和尚 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22a59d9-515a-4678-8b84-b95f753ac599', '寄馮使君', '寄馮使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["端居碧雲暮，好鳥啼紅芳。","滿郭桃李熟，捲簾風雨香。","清吟繡段句，默念芙蓉章。","未得歸山去，頻升謝守堂。"]', '["端居碧云暮，好鸟啼紅芳。","满郭桃李熟，捲簾风雨香。","清吟繡段句，默念芙蓉章。","未得归山去，頻升謝守堂。"]', '诗', 'shi', '', NULL, '寄馮使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef62eaac-02c0-48eb-a6a1-23c45c4fe25e', '寄紫閣隱者', '寄紫閣隐者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["積翠藏一叟，常思未得遊。","不知在巖下，爲復在峰頭。","苔上枯藤笐，泉淋破石樓。","伊余更何事，不學此翁休。"]', '["積翠藏一叟，常思未得游。","不知在巖下，爲复在峰头。","苔上枯藤笐，泉淋破石楼。","伊余更何事，不学此翁休。"]', '诗', 'shi', '', NULL, '寄紫閣隱者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6210d5-bdbc-4b33-87c6-50e1f988a7e9', '寄天台道友', '寄天台道友', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["大是清虛地，高吟到日晡。","水聲金磬亂，雲片玉盤粗。","仙有遺蹤在，人還得意無。","石碑文不值，壁畫色多枯。","冷立千年鶴，閑燒六一爐。","松枝垂似物，山勢秀難圖。","紫府程非遠，清溪徑不迂。","馨香柏上露，皎潔水中珠。","賢聖無他術，圓融只在吾。","寄言桐柏子，珍重保之乎。"]', '["大是清虛地，高吟到日晡。","水声金磬亂，云片玉盤粗。","仙有遺蹤在，人還得意無。","石碑文不值，壁畫色多枯。","冷立千年鹤，闲燒六一爐。","松枝垂似物，山勢秀难圖。","紫府程非远，清溪徑不迂。","馨香柏上露，皎潔水中珠。","賢聖無他術，圓融只在吾。","寄言桐柏子，珍重保之乎。"]', '诗', 'shi', '', NULL, '寄天台道友 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12abc62-60d5-490c-b41f-3c3242f69fc7', '旅中懷孫路', '旅中懷孫路', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["暮塵微雨收，蟬急楚鄉秋。","一片月出海，幾家人上樓。","砌香殘果落，汀草宿煙浮。","唯有知音者，相思歌白頭。"]', '["暮塵微雨收，蟬急楚乡秋。","一片月出海，幾家人上楼。","砌香殘果落，汀草宿煙浮。","唯有知音者，相思歌白头。"]', '诗', 'shi', '', NULL, '旅中懷孫路 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c08cb2-34c6-4196-8302-fc80165bbecd', '貽世', '貽世', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["至理不誤物，悠悠自不明。","黃金燒欲盡，白髮火邊生。","苦惑神仙䜝，難收日月精。","捕風兼繫影，信矣不須爭。"]', '["至理不誤物，悠悠自不明。","黄金燒欲尽，白髮火邊生。","苦惑神仙䜝，难收日月精。","捕风兼繫影，信矣不須爭。"]', '诗', 'shi', '', NULL, '貽世 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58b4d694-56c7-4946-bdc5-4f27deb5b512', '覽李秀才卷', '覽李秀才卷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["香沐整山衣，開君一軸詩。","吟當秋景苦，味出雪林遲。","經濟幾人到，工夫兩鬢知。","因嗟和氏淚，不是等閑垂。"]', '["香沐整山衣，开君一軸诗。","吟當秋景苦，味出雪林遲。","經濟幾人到，工夫兩鬢知。","因嗟和氏泪，不是等闲垂。"]', '诗', 'shi', '', NULL, '覽李秀才卷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3305e7cf-60ac-4306-87a1-79c080ecb2c7', '懷方干張爲', '懷方干張爲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["冥搜入仙窟，半夜水堂前。","吾道祗如此，古人多亦然。","螢沈荒塢霧，月苦綠梧蟬。"]', '["冥搜入仙窟，半夜水堂前。","吾道祗如此，古人多亦然。","螢沈荒塢霧，月苦綠梧蟬。"]', '诗', 'shi', '', NULL, '懷方干張爲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091dfdbf-c8d1-4d28-9da0-f956f5583bbf', '四皓圖', '四皓圖', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["何人圖四皓，如語話嘮嘮。","雙鬢雪相似，是誰年最高。","溪苔連豹褥，仙酒汙雲袍。","想得忘秦日，伊余亦合逃。"]', '["何人圖四皓，如語話嘮嘮。","雙鬢雪相似，是誰年最高。","溪苔連豹褥，仙酒汙云袍。","想得忘秦日，伊余亦合逃。"]', '诗', 'shi', '', NULL, '四皓圖 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88626846-4a90-4f2e-8582-d2d17ed3eb29', '懷白閣道侶', '懷白閣道侶', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["寒思白閣層，石屋兩三僧。","斜雪掃不盡，飢猨喚得應。","香然一字火，磬過數潭冰。","終必相尋去，孤懷久不勝。"]', '["寒思白閣層，石屋兩三僧。","斜雪掃不尽，飢猨喚得應。","香然一字火，磬過數潭冰。","終必相尋去，孤懷久不勝。"]', '诗', 'shi', '', NULL, '懷白閣道侶 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a2c28d-7421-4ef3-8d56-9b22f6239263', '讀孟郊集', '读孟郊集', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["東野子何之，詩人始見詩。","清刳霜雪髓，吟動鬼神司。","舉世言多媚，無人師此師。","因知吾道後，冷淡亦如斯。"]', '["东野子何之，诗人始见诗。","清刳霜雪髓，吟动鬼神司。","舉世言多媚，無人師此師。","因知吾道後，冷淡亦如斯。"]', '诗', 'shi', '', NULL, '讀孟郊集 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b5f0e5c-4a1b-4356-92e8-f689f47d8701', '懷四明亮公', '懷四明亮公', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["孤峰含紫煙，師住此安禪。","不下便不下，如斯太可憐。","坐侵天井黑，吟久海霞蔫。","豈覺塵埃裏，干戈已十年。"]', '["孤峰含紫煙，師住此安禪。","不下便不下，如斯太可怜。","坐侵天井黑，吟久海霞蔫。","豈覺塵埃裏，干戈已十年。"]', '诗', 'shi', '', NULL, '懷四明亮公 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae002b8-9045-43d3-be91-69102ee2f677', '秋過錢塘江', '秋過錢塘江', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["巨浸東隅極，山吞大野平。","因知吳相恨，不盡海濤聲。","黑氣騰蛟窟，秋雲入戰城。","遊人千萬里，過此白髭生。"]', '["巨浸东隅極，山吞大野平。","因知吳相恨，不尽海濤声。","黑氣腾蛟窟，秋云入戰城。","游人千万里，過此白髭生。"]', '诗', 'shi', '', NULL, '秋過錢塘江 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4b7a50-1c95-49ae-8f30-c57dc39bda98', '上俞許二判官', '上俞許二判官', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["近拋蓑笠者，急善遇休明。","未省親宗伯，焉能識正聲。","病容經夏在，岳夢入秋幷。","無限林中意，今逢許郭傾。"]', '["近拋蓑笠者，急善遇休明。","未省親宗伯，焉能識正声。","病容經夏在，岳梦入秋幷。","無限林中意，今逢許郭傾。"]', '诗', 'shi', '', NULL, '上俞許二判官 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e79adefc-4434-4a9e-beae-1cced23d00d8', '懷劉得仁', '懷劉得仁', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["詩名動帝畿，身謝亦因詩。","白日只如哭，皇天得不知。","旅墳孤𨃤岳，羸僕泣如兒。","多少求名者，聞之淚盡垂。"]', '["诗名动帝畿，身謝亦因诗。","白日只如哭，皇天得不知。","旅墳孤𨃤岳，羸僕泣如兒。","多少求名者，闻之泪尽垂。"]', '诗', 'shi', '', NULL, '懷劉得仁 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb0565db-2757-412d-8dcd-10e47a27741e', '歸故林後寄二三知己', '归故林後寄二三知己', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昨別楚江邊，逡巡早數年。","詩雖清到後，人更瘦於前。","岸翠連喬嶽，汀沙入壞田。","何時重一見，談笑有茶煙。"]', '["昨別楚江邊，逡巡早數年。","诗雖清到後，人更瘦於前。","岸翠連喬嶽，汀沙入壞田。","何时重一见，談笑有茶煙。"]', '诗', 'shi', '', NULL, '歸故林後寄二三知己 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7359e37f-faf1-44d9-b7ea-a00dc0e465b6', '春寄西山陳陶', '春寄西山陳陶', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["搔首復搔首，孤懷草萋萋。","春光已滿目，君在西山西。","塹水成文去，庭柯擎翠低。","所思不可見，黃鳥花中啼。"]', '["搔首复搔首，孤懷草萋萋。","春光已满目，君在西山西。","塹水成文去，庭柯擎翠低。","所思不可见，黄鸟花中啼。"]', '诗', 'shi', '', NULL, '春寄西山陳陶 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d39c680-b9ea-4866-847b-c5ce3237929b', '秋末江行', '秋末江行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["四顧木落盡，扁舟增所思。","雲衝遠燒出，帆轉大荒遲。","天際霜雪作，水邊蒿艾衰。","斷猨不堪聽，一聽亦同悲。"]', '["四顧木落尽，扁舟增所思。","云衝远燒出，帆轉大荒遲。","天際霜雪作，水邊蒿艾衰。","斷猨不堪听，一听亦同悲。"]', '诗', 'shi', '', NULL, '秋末江行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8dc1637-e7f7-4982-9936-b45d4e44e459', '送人歸新羅', '送人归新羅', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昨夜西風起，送君歸故鄉。","積愁窮地角，見日上扶桑。","蜃氣生初霽，潮痕匝亂荒。","從茲頭各白，魂夢一相望。"]', '["昨夜西风起，送君归故乡。","積愁窮地角，见日上扶桑。","蜃氣生初霽，潮痕匝亂荒。","從茲头各白，魂梦一相望。"]', '诗', 'shi', '', NULL, '送人歸新羅 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c329a1-eceb-4993-a1d2-9d6497af346f', '思匡山賈匡', '思匡山賈匡', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山兄詩癖甚，寒夜更何爲。","覓句唯頑坐，嚴霜打不知。","石膏黏木屐，崖蜜落冰池。","近見禪僧說，生涯勝往時。"]', '["山兄诗癖甚，寒夜更何爲。","覓句唯頑坐，嚴霜打不知。","石膏黏木屐，崖蜜落冰池。","近见禪僧说，生涯勝往时。"]', '诗', 'shi', '', NULL, '思匡山賈匡 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8fbd555-2a68-478b-a457-25dbfd053e66', '偶作', '偶作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["十載獨扃扉，唯爲二雅詩。","道孤終不雜，頭白更何疑。","句冷杉松與，霜嚴鼓角知。","修心對閑鏡，明月印秋池。"]', '["十載独扃扉，唯爲二雅诗。","道孤終不杂，头白更何疑。","句冷杉松與，霜嚴鼓角知。","修心对闲镜，明月印秋池。"]', '诗', 'shi', '', NULL, '偶作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baf9995f-364c-4c99-b981-41838cf562c2', '贈方干', '贈方干', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["盛名與高隱，合近謝敷村。","弟子已得桂，先生猶灌園。","垂綸侵海介，拾句歷雲根。","白日昇天路，如君別有門。"]', '["盛名與高隐，合近謝敷村。","弟子已得桂，先生猶灌园。","垂綸侵海介，拾句歷云根。","白日昇天路，如君別有门。"]', '诗', 'shi', '', NULL, '贈方干 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70914bd-6189-41db-b71d-0150db9ea2f9', '漁父', '漁父', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一葉一竿竹，眉鬚雪欲零。","陸應無祖業，香必是伊腥。","兒亦名魚鷓，歌稱我洞庭。","回頭深自媿，舊業近滄溟。"]', '["一葉一竿竹，眉鬚雪欲零。","陸應無祖業，香必是伊腥。","兒亦名鱼鷓，歌稱我洞庭。","回头深自媿，旧業近滄溟。"]', '诗', 'shi', '', NULL, '漁父 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddf11e8-b166-40f0-acfb-73d4a2cb6e0e', '題友人山居', '題友人山居', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["卜居鄰塢寺，魂夢又相關。","鶴本如雲白，君初似我閑。","月明僧渡水，木落火連山。","從此天台約，來茲未得還。"]', '["卜居鄰塢寺，魂梦又相关。","鹤本如云白，君初似我闲。","月明僧渡水，木落火連山。","從此天台約，来茲未得還。"]', '诗', 'shi', '', NULL, '題友人山居 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958ba357-f213-43d2-b5c5-da1e222cfabc', '寄宋使君', '寄宋使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["寺倚烏龍腹，窗中見碧稜。","空廊人畫祖，古殿鶴窺燈。","風吼深松雪，爐寒一鼎冰。","唯應謝內史，知此道心澄。"]', '["寺倚烏龙腹，窗中见碧稜。","空廊人畫祖，古殿鹤窺灯。","风吼深松雪，爐寒一鼎冰。","唯應謝內史，知此道心澄。"]', '诗', 'shi', '', NULL, '寄宋使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae34a5d-57eb-4d41-a539-40831acfcbab', '懷武夷紅石子二首 一', '懷武夷紅石子二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常思紅石子，獨自住山椒。","窗外猩猩語，爐中奼奼嬌。","乳香諸洞滴，地秀衆峰朝。","曾見奇人說，煙霞恨太遙。"]', '["常思紅石子，独自住山椒。","窗外猩猩語，爐中奼奼嬌。","乳香諸洞滴，地秀衆峰朝。","曾见奇人说，煙霞恨太遙。"]', '诗', 'shi', '', NULL, '懷武夷紅石子二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec3b793-5144-4531-ad9d-3461bb10692e', '懷武夷紅石子二首 二', '懷武夷紅石子二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["弋者終何慕，高吟坐綠鼇。","燒侵薑芋窖，僧與水雲袍。","竹鞘畬刀缺，松枝獵箭勞。","何時一相見，清話擘蟠桃。"]', '["弋者終何慕，高吟坐綠鼇。","燒侵薑芋窖，僧與水云袍。","竹鞘畬刀缺，松枝獵箭勞。","何时一相见，清話擘蟠桃。"]', '诗', 'shi', '', NULL, '懷武夷紅石子二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('517cc330-aad1-4218-bf53-27cd8314a62f', '送人征蠻', '送人征蠻', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["七縱七擒處，君行事可攀。","亦知磨一劒，不獨定諸蠻。","樹盡低銅柱，潮常沸火山。","名須麟閣上，好去及瓜還。"]', '["七縱七擒处，君行事可攀。","亦知磨一劒，不独定諸蠻。","樹尽低銅柱，潮常沸火山。","名須麟閣上，好去及瓜還。"]', '诗', 'shi', '', NULL, '送人征蠻 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c957047-1970-4e2a-95ff-18018f2fa0b5', '懷周朴張爲', '懷周朴張爲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["二子無消息，多應各自耕。","巴江思杜甫，漳水憶劉楨。","白髮應全白，生涯作麽生。","寄書多不達，空念重行行。"]', '["二子無消息，多應各自耕。","巴江思杜甫，漳水憶劉楨。","白髮應全白，生涯作麽生。","寄书多不達，空念重行行。"]', '诗', 'shi', '', NULL, '懷周朴張爲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9330db84-8fa0-4a78-a829-68d40a824ad8', '寄令狐郎中', '寄令狐郎中', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雨打繁暑盡，放懷步微涼。","綠苔狂似人，入我白玉堂。","塹鳥眠堪畫，庭檉夜益香。","唯應蘂宮子，時到虎溪傍。"]', '["雨打繁暑尽，放懷步微涼。","綠苔狂似人，入我白玉堂。","塹鸟眠堪畫，庭檉夜益香。","唯應蘂宮子，时到虎溪傍。"]', '诗', 'shi', '', NULL, '寄令狐郎中 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c698a82-92fb-417f-bd4d-187d615b3fe5', '鄱陽道中作', '鄱陽道中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鄱陽古岸邊，無一樹無蟬。","路轉他山大，砧驅鄉思偏。","湖平帆盡落，天淡月初圓。","何事堯雲下，干戈滿許田。"]', '["鄱陽古岸邊，無一樹無蟬。","路轉他山大，砧驱乡思偏。","湖平帆尽落，天淡月初圓。","何事堯云下，干戈满許田。"]', '诗', 'shi', '', NULL, '鄱陽道中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d840a583-6308-4307-bf1e-b2d734f21d98', '歸故林別知己', '归故林別知己', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["別離無古今，柳色向人深。","萬里長江水，平生不印心。","遠書容北雁，贈別謝南金。","媿勉青雲志，余懷非陸沈。"]', '["別離無古今，柳色向人深。","万里长江水，平生不印心。","远书容北雁，贈別謝南金。","媿勉青云志，余懷非陸沈。"]', '诗', 'shi', '', NULL, '歸故林別知己 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff40d41a-7501-4e90-ac9e-62288b730b87', '送僧遊天台', '送僧游天台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["囊空心亦空，城郭去騰騰。","眼作麽是眼，僧誰識此僧。","歇隈紅樹久，笑看白雲崩。","已有天台約，深秋必共登。"]', '["囊空心亦空，城郭去腾腾。","眼作麽是眼，僧誰識此僧。","歇隈紅樹久，笑看白云崩。","已有天台約，深秋必共登。"]', '诗', 'shi', '', NULL, '送僧遊天台 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15efe7df-33f0-4fc5-8abb-fad09d91380b', '詠竹根珓子', '詠竹根珓子', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["出處慙林藪，才微幸一陽。","不緣懷片善，豈得近馨香。","節亦因人淨，聲從擲地彰。","但令筋力在，永願報時昌。"]', '["出处慙林藪，才微幸一陽。","不緣懷片善，豈得近馨香。","節亦因人淨，声從擲地彰。","但令筋力在，永願報时昌。"]', '诗', 'shi', '', NULL, '詠竹根珓子 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a3bfb22-eaa7-46af-80e4-15cecba0b18a', '硯瓦', '硯瓦', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["淺薄雖頑朴，其如近筆端。","低心蒙潤久，入匣更身安。","應念研磨苦，無爲瓦礫看。","儻然仁不棄，還可比琅玕。"]', '["淺薄雖頑朴，其如近笔端。","低心蒙潤久，入匣更身安。","應念研磨苦，無爲瓦礫看。","儻然仁不棄，還可比琅玕。"]', '诗', 'shi', '', NULL, '硯瓦 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc06baa-9966-4a88-9a9b-fa9ed08e5d4a', '水壺子', '水壺子', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["良匠曾陶瑩，多居筆硯中。","一從親几案，常恐近兒童。","卓立澄心久，提攜注意通。","不應嫌器小，還有濟人功。"]', '["良匠曾陶瑩，多居笔硯中。","一從親几案，常恐近兒童。","卓立澄心久，提携注意通。","不應嫌器小，還有濟人功。"]', '诗', 'shi', '', NULL, '水壺子 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d816f1a2-982e-4540-8998-6562fdffb025', '筆', '笔', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["莫訝書紳苦，功成在一毫。","自從蒙管錄，便覺用心勞。","手點時難棄，身閑架亦高。","何妨成五色，永願助風騷。"]', '["莫訝书紳苦，功成在一毫。","自從蒙管錄，便覺用心勞。","手点时难棄，身闲架亦高。","何妨成五色，永願助风騷。"]', '诗', 'shi', '', NULL, '筆 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca6ed24-6521-402f-849f-c4df46748ae8', '棊', '棊', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["棊信無聲樂，偏宜境寂寥。","著高圖暗合，勢王氣彌驕。","人事掀天盡，光陰動地銷。","因知韋氏論，不獨爲吳朝。"]', '["棊信無声乐，偏宜境寂寥。","著高圖暗合，勢王氣彌驕。","人事掀天尽，光陰动地銷。","因知韋氏論，不独爲吳朝。"]', '诗', 'shi', '', NULL, '棊 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c846acb-1c14-4cd8-9877-9126c8248e68', '夜對雪作寄友生', '夜对雪作寄友生', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["皓彩中宵合，開門失所蹤。","何年今夜意，共子在孤峰。","氣射燈花落，光侵壁罅濃。","唯君心似我，吟到五更鐘。"]', '["皓彩中宵合，开门失所蹤。","何年今夜意，共子在孤峰。","氣射灯花落，光侵壁罅濃。","唯君心似我，吟到五更鐘。"]', '诗', 'shi', '', NULL, '夜對雪作寄友生 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce2eeecf-98d5-4d01-81fb-89dce5b62d9f', '題惠琮律師院', '題惠琮律師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["苦節兼青目，公卿話有餘。","唯傳黃葉喻，還似白泉居。","猨撥孤雲破，鐘撞衆木疎。","社壇蹤跡在，重結復何如。"]', '["苦節兼青目，公卿話有餘。","唯傳黄葉喻，還似白泉居。","猨撥孤云破，鐘撞衆木疎。","社壇蹤跡在，重結复何如。"]', '诗', 'shi', '', NULL, '題惠琮律師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e61110c9-d584-4cea-ab75-1fcd50a9e4ac', '寄清泠山道人', '寄清泠山道人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶清泠子，深雲種早禾。","萬緣雖不涉，一句子如何。","蹤跡諸峰匝，衣裳老虱多。","江頭無事也，終必到煙蘿。"]', '["常憶清泠子，深云種早禾。","万緣雖不涉，一句子如何。","蹤跡諸峰匝，衣裳老虱多。","江头無事也，終必到煙蘿。"]', '诗', 'shi', '', NULL, '寄清泠山道人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e8a03c-15f1-4db6-9450-b762972df3be', '秋盡途中作', '秋尽途中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["行行芳草歇，潭島葉紛紛。","山色路無盡，砧聲客強聞。","殘陽曜極野，黑水浸空墳。","那得無鄉思，前程入楚雲。"]', '["行行芳草歇，潭島葉紛紛。","山色路無尽，砧声客強闻。","殘陽曜極野，黑水浸空墳。","那得無乡思，前程入楚云。"]', '诗', 'shi', '', NULL, '秋盡途中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f86497-8343-4196-8337-f352aad57684', '秋居寄王相公三首 一', '秋居寄王相公三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["禪林蟬□落，地燥可生苔。","好句慵收拾，清風作麽來。","餅唯餐喜悅，社已得宗雷。","還似山中日，柴門更不開。"]', '["禪林蟬□落，地燥可生苔。","好句慵收拾，清风作麽来。","餅唯餐喜悅，社已得宗雷。","還似山中日，柴门更不开。"]', '诗', 'shi', '', NULL, '秋居寄王相公三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26eb858c-23f4-4b8d-bdee-217eff1c5acd', '秋居寄王相公三首 二', '秋居寄王相公三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["松聲高似瀑，藥熟色如花。","誰道全無病，時猶不在家。","山童舂菽粉，園叟送銀瓜。","誰訪孫弘閣，談玄到日斜。"]', '["松声高似瀑，藥熟色如花。","誰道全無病，时猶不在家。","山童舂菽粉，园叟送銀瓜。","誰訪孫弘閣，談玄到日斜。"]', '诗', 'shi', '', NULL, '秋居寄王相公三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2771e0fb-a3b4-413a-9c16-7621c1b67867', '秋居寄王相公三首 三', '秋居寄王相公三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["氣與非常合，常人爭得知。","直須窮到底，始是出家兒。","閣雀銜紅粟，鄰僧背古碑。","祗應王與謝，時有沃州期。"]', '["氣與非常合，常人爭得知。","直須窮到底，始是出家兒。","閣雀銜紅粟，鄰僧背古碑。","祗應王與謝，时有沃州期。"]', '诗', 'shi', '', NULL, '秋居寄王相公三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5caae55-5b5d-48e2-8818-10fc9d18ac72', '讀玄宗幸蜀記', '读玄宗幸蜀記', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["宋璟姚崇死，中庸遂變移。","如何遊萬里，祗爲一胡兒。","泣溻乾坤色，飄零日月旗。","火從龍闕起，淚向馬嵬垂。","始憶張丞相，全師郭子儀。","百官皆剽劫，九廟盡崩隳。","塵撲銀輪暗，雷奔棧閣危。","倖臣方賜死，野老不勝悲。","及霤飄淪日，行宮寂寞時。","人心雖未厭，天意亦難知。","聖兩歸丹禁，承乾動四夷。","因知納諫諍，始是太平基。"]', '["宋璟姚崇死，中庸遂变移。","如何游万里，祗爲一胡兒。","泣溻乾坤色，飄零日月旗。","火從龙闕起，泪向马嵬垂。","始憶張丞相，全師郭子儀。","百官皆剽劫，九廟尽崩隳。","塵撲銀輪暗，雷奔棧閣危。","倖臣方賜死，野老不勝悲。","及霤飄淪日，行宮寂寞时。","人心雖未厭，天意亦难知。","聖兩归丹禁，承乾动四夷。","因知納諫諍，始是太平基。"]', '诗', 'shi', '', NULL, '讀玄宗幸蜀記 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5a10b9-a93d-4525-aa75-2d13eb823d14', '聞徵四處士', '闻徵四处士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一詔羣公起，移山四海聞。","因知丈夫事，須佐聖明君。","白酒全傾甕，蒲輪半載雲。","從茲居諫署，筆硯幾人焚。"]', '["一詔羣公起，移山四海闻。","因知丈夫事，須佐聖明君。","白酒全傾甕，蒲輪半載云。","從茲居諫署，笔硯幾人焚。"]', '诗', 'shi', '', NULL, '聞徵四處士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01077e4-9b2f-4ff5-8ec2-b2beb06c1959', '送友人下第遊邊', '送友人下第游邊', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["失意窮邊去，孤城值晚春。","黑山霞不赤，白日鬼隨人。","角咽胡風緊，沙昏磧月新。","明時至公在，迴首莫因循。"]', '["失意窮邊去，孤城值晚春。","黑山霞不赤，白日鬼隨人。","角咽胡风緊，沙昏磧月新。","明时至公在，迴首莫因循。"]', '诗', 'shi', '', NULL, '送友人下第遊邊 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ca6a371-c799-4418-b228-bbf007af7117', '寄匡山紀公', '寄匡山紀公', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["錦繡谷中人，相思入夢頻。","寄言無別事，琢句似終身。","書卷須求旨，鬚根易得銀。","斯言如不惑，千里亦相親。"]', '["錦繡谷中人，相思入梦頻。","寄言無別事，琢句似終身。","书卷須求旨，鬚根易得銀。","斯言如不惑，千里亦相親。"]', '诗', 'shi', '', NULL, '寄匡山紀公 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('379416d5-eb98-44ef-8fd7-41eb405b5952', '聞無相道人順世五首 一', '闻無相道人順世五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一事不經營，孤峰長老情。","惟餐橡子餅，愛說道君兄。","池藕香貍掘，山神白日行。"]', '["一事不經營，孤峰长老情。","惟餐橡子餅，愛说道君兄。","池藕香貍掘，山神白日行。"]', '诗', 'shi', '', NULL, '聞無相道人順世五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e54795-d406-4b1c-b77a-45de6ba025aa', '聞無相道人順世五首 二', '闻無相道人順世五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["自昔尋師日，顛峰絕頂頭。","雖聞不相似，特地使人愁。","庭樹雪摧殘，上有白獮猴。","大哉法中龍，去去不可留。"]', '["自昔尋師日，顛峰絕頂头。","雖闻不相似，特地使人愁。","庭樹雪摧殘，上有白獮猴。","大哉法中龙，去去不可留。"]', '诗', 'shi', '', NULL, '聞無相道人順世五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db52ba9d-b7c0-4a0a-9b69-4d55c3d4f2f5', '聞無相道人順世五首 三', '闻無相道人順世五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常思將道者，高論地爐傍。","迂談無世味，夜深山木僵。","下山遭離亂，多病惟深藏。","一別三十年，煙水空茫茫。"]', '["常思將道者，高論地爐傍。","迂談無世味，夜深山木僵。","下山遭離亂，多病惟深藏。","一別三十年，煙水空茫茫。"]', '诗', 'shi', '', NULL, '聞無相道人順世五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eafffc19-3d74-4a0d-9d90-22fa3b4143dc', '聞無相道人順世五首 四', '闻無相道人順世五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["石霜既順世，吾師亦不住。","杉桂有猩猩，糠粃無句句。","土肥多孟蕨，道老如孾孺。","莫比優曇花，斯人更難遇。"]', '["石霜既順世，吾師亦不住。","杉桂有猩猩，糠粃無句句。","土肥多孟蕨，道老如孾孺。","莫比優曇花，斯人更难遇。"]', '诗', 'shi', '', NULL, '聞無相道人順世五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c5bb93-e6f6-4caf-8bfd-2d45a818d7ee', '聞無相道人順世五首 五', '闻無相道人順世五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["百千萬億偈，共他勿交涉。","所以那老人，密傳與迦葉。","吾師得此法，不論劫不劫。","去矣不可留，無踪若爲躡。"]', '["百千万億偈，共他勿交涉。","所以那老人，密傳與迦葉。","吾師得此法，不論劫不劫。","去矣不可留，無踪若爲躡。"]', '诗', 'shi', '', NULL, '聞無相道人順世五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee8df6b-525b-408e-bbdb-b5381367ed1f', '苦熱', '苦熱', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["松桂枝不動，陽烏飛半天。","稻麻須結實，沙石欲生煙。","毒氣仍干扇，高枝不立蟬。","舊山多積雪，歸去是何年。"]', '["松桂枝不动，陽烏飞半天。","稻麻須結實，沙石欲生煙。","毒氣仍干扇，高枝不立蟬。","旧山多積雪，归去是何年。"]', '诗', 'shi', '', NULL, '苦熱 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cbe381a-7b22-4e7e-ab21-99565ee597c5', '鄂渚贈祥公', '鄂渚贈祥公', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["寂寥堆積者，自爲是高僧。","客遠何人識，吟多冷病增。","松煙青透壁，雪氣細吹燈。","猶賴師於我，依依非面朋。"]', '["寂寥堆積者，自爲是高僧。","客远何人識，吟多冷病增。","松煙青透壁，雪氣細吹灯。","猶賴師於我，依依非面朋。"]', '诗', 'shi', '', NULL, '鄂渚贈祥公 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e8030c-3a82-4507-9813-a5f235e7362b', '懷武昌棲一二首 一', '懷武昌棲一二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶能吟一，房連古帝墟。","無端多忤物，唯我獨知渠。","病愈囊空後，神清木落初。","祗因烽火起，書札自茲疎。"]', '["常憶能吟一，房連古帝墟。","無端多忤物，唯我独知渠。","病愈囊空後，神清木落初。","祗因烽火起，书札自茲疎。"]', '诗', 'shi', '', NULL, '懷武昌棲一二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f217011-f281-4957-9db6-797bbe42f2fb', '懷武昌棲一二首 二', '懷武昌棲一二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清風江上月，霜灑月中砧。","得句先呈佛，無人知此心。","寂寥從鬼出，蒼翠到門深。","惟有雙峰寺，時時獨去尋。"]', '["清风江上月，霜灑月中砧。","得句先呈佛，無人知此心。","寂寥從鬼出，蒼翠到门深。","惟有雙峰寺，时时独去尋。"]', '诗', 'shi', '', NULL, '懷武昌棲一二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c940534-e56b-470c-8637-7b727a602811', '寒食郊外', '寒食郊外', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["寒食將吾族，相隨過石溪。","塚花沾酒落，林鳥學人啼。","白水穿蕪疾，新霞出霧低。","不堪迴首望，家在赤松西。"]', '["寒食將吾族，相隨過石溪。","塚花沾酒落，林鸟学人啼。","白水穿蕪疾，新霞出霧低。","不堪迴首望，家在赤松西。"]', '诗', 'shi', '', NULL, '寒食郊外 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f8ead1-ed1c-4bd2-8c7c-c433b5f10e7b', '送道士歸天台', '送道士归天台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["道高留不住，道去更何云。","舉世皆趨世，如君始愛君。","徑侵銀地滑，瀑到石城聞。","它日如相憶，金桃一爲分。"]', '["道高留不住，道去更何云。","舉世皆趨世，如君始愛君。","徑侵銀地滑，瀑到石城闻。","它日如相憶，金桃一爲分。"]', '诗', 'shi', '', NULL, '送道士歸天台 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('044d89e7-3b5a-40e1-8ae8-e6273de393ac', '經孟浩然鹿門舊居二首 一', '經孟浩然鹿门旧居二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["孟子終焉處，遊人得得過。","⿰木養深黃狖小，地煗白雲多。","孔聖嗟大謬，玄宗爭奈何。","空餘峴山色，千古共嵯峨。"]', '["孟子終焉处，游人得得過。","⿰木養深黄狖小，地煗白云多。","孔聖嗟大謬，玄宗爭奈何。","空餘峴山色，千古共嵯峨。"]', '诗', 'shi', '', NULL, '經孟浩然鹿門舊居二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeda7c05-18ee-447c-a4b4-361dcec8f0e8', '經孟浩然鹿門舊居二首 二', '經孟浩然鹿门旧居二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["花落谷鶯啼，精靈安在哉。","青山不可問，永日獨裴回。","塚穴應藏虎，荒碑祗見苔。","伊余亦惆悵，昨日郢城迴。"]', '["花落谷鶯啼，精靈安在哉。","青山不可问，永日独裴回。","塚穴應藏虎，荒碑祗见苔。","伊余亦惆悵，昨日郢城迴。"]', '诗', 'shi', '', NULL, '經孟浩然鹿門舊居二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81de46df-7a5c-4e45-b174-e7f026d1f11d', '春送禪師歸閩中', '春送禪師归閩中', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["春色滿三湘，送師還故鄉。","穿霞逢黑鴧，乞食得紅薑。","大化宗門闢，孤禪海樹涼。","儻爲新句偈，寄我亦何妨。"]', '["春色满三湘，送師還故乡。","穿霞逢黑鴧，乞食得紅薑。","大化宗门闢，孤禪海樹涼。","儻爲新句偈，寄我亦何妨。"]', '诗', 'shi', '', NULL, '春送禪師歸閩中 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb03845a-507c-4a85-b25a-2cd7b2103ed2', '途中逢周朴', '途中逢周朴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["東西南北路，相遇共興哀。","世濁無知己，子從何處來？","菊衰芳草在，程遠宿煙開。","儻遇中興主，還應不用媒。"]', '["东西南北路，相遇共兴哀。","世濁無知己，子從何处来？","菊衰芳草在，程远宿煙开。","儻遇中兴主，還應不用媒。"]', '诗', 'shi', '', NULL, '途中逢周朴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c7275b-6c9d-44bc-80ca-84404009cb92', '避寇山中作', '避寇山中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山翠碧嵯峨，攀牽去者多。","淺深俱得地，好惡未知他。","有草皆爲戶，無人不荷戈。","相逢空悵望，更有好時麽。"]', '["山翠碧嵯峨，攀牽去者多。","淺深俱得地，好惡未知他。","有草皆爲戶，無人不荷戈。","相逢空悵望，更有好时麽。"]', '诗', 'shi', '', NULL, '避寇山中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a252eb-e1c0-4cff-b958-872607a390ae', '避寇上唐臺山', '避寇上唐台山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蒼黃緣鳥道，峰脋見樓臺。","檉桂香皆滴，煙霞濕不開。","僧高眉半白，山老石多摧。","莫問塵中事，如今正可哀。"]', '["蒼黄緣鸟道，峰脋见楼台。","檉桂香皆滴，煙霞濕不开。","僧高眉半白，山老石多摧。","莫问塵中事，如今正可哀。"]', '诗', 'shi', '', NULL, '避寇上唐臺山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ec4742-6ae4-4c1b-ab2e-b3c0cb65bc23', '題嶧桐律師院', '題嶧桐律師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["律中麟角者，高[淡]出塵埃。","芳草不曾觸，幾生如此來。","壑風吹磬斷，杉露滴花開。","如結林中社，伊余亦願陪。"]', '["律中麟角者，高[淡]出塵埃。","芳草不曾觸，幾生如此来。","壑风吹磬斷，杉露滴花开。","如結林中社，伊余亦願陪。"]', '诗', 'shi', '', NULL, '題嶧桐律師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff84338-4c67-4d21-a9ca-21fd8a7ce7ad', '上馮使君渡水僧障子', '上馮使君渡水僧障子', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["跣足拄巴藤，潺湲渡幾曾。","盡權無著印，不是登閑僧。","熊耳應初到，牛頭始去登。","畫來偏覺好，將寄柳吳興。"]', '["跣足拄巴藤，潺湲渡幾曾。","尽權無著印，不是登闲僧。","熊耳應初到，牛头始去登。","畫来偏覺好，將寄柳吳兴。"]', '诗', 'shi', '', NULL, '上馮使君渡水僧障子 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f797c58f-66fc-4824-b457-fd739470ce47', '秋夜翫月懷玉霄道士', '秋夜翫月懷玉霄道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["光異磨礱出，輪非雕斵成。","今宵剛道別，舉世勿人爭。","征婦砧添怨，詩人哭到明。","惟宜華頂叟，笙磬有餘聲。"]', '["光異磨礱出，輪非雕斵成。","今宵剛道別，舉世勿人爭。","征婦砧添怨，诗人哭到明。","惟宜华頂叟，笙磬有餘声。"]', '诗', 'shi', '', NULL, '秋夜翫月懷玉霄道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d76477f-567b-4b3a-8429-eb2fb623096e', '上杭州令狐使君', '上杭州令狐使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["顏冉德無鄰，分憂浙水濱。","愛山成大癖，求瘼似諸身。","視事奸回盡，登樓海岳春。","野人如有幸，應得見陶鈞。"]', '["顏冉德無鄰，分憂浙水濱。","愛山成大癖，求瘼似諸身。","視事奸回尽，登楼海岳春。","野人如有幸，應得见陶鈞。"]', '诗', 'shi', '', NULL, '上杭州令狐使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80109dd8-2d23-4f26-9f9c-af2f8ab30c97', '懷諸葛珏二首 一', '懷諸葛珏二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["諸葛子作者，詩曾我細看。","出山因覓孟，踏雪去尋韓。","謬獨哭不錯，常流飲實難。","知音知便了，歸去舊江干。"]', '["諸葛子作者，诗曾我細看。","出山因覓孟，踏雪去尋韓。","謬独哭不錯，常流饮實难。","知音知便了，归去旧江干。"]', '诗', 'shi', '', NULL, '懷諸葛珏二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffbb2dc3-d796-4db0-b4ca-86c979155601', '懷諸葛珏二首 二', '懷諸葛珏二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["羸馬與羸童，微吟冒北風。","店孤僧共歇，日落思無窮。","囊草無非刺，魏人那識公。","鶯花五陵道，去去與誰同。"]', '["羸马與羸童，微吟冒北风。","店孤僧共歇，日落思無窮。","囊草無非刺，魏人那識公。","鶯花五陵道，去去與誰同。"]', '诗', 'shi', '', NULL, '懷諸葛珏二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0fab6ba-0410-41b9-b4df-e90573bc87d1', '懷錢唐羅隱章魯封', '懷錢唐羅隐章魯封', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["二子依公子，雞鳴狗盜徒。","青雲十上苦，白髮一莖無。","風澀潮聲惡，天寒角韻孤。","別離千萬里，何以慰榮枯。"]', '["二子依公子，雞鳴狗盜徒。","青云十上苦，白髮一莖無。","风澀潮声惡，天寒角韻孤。","別離千万里，何以慰榮枯。"]', '诗', 'shi', '', NULL, '懷錢唐羅隱章魯封 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb0d317-82e2-454a-8fb7-5596f03c26fd', '送沈侍郎', '送沈侍郎', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["從知無遠近，木落去閩城。","地入無諸俗，冠峨甲乙精。","山多高興亂，江直好風生。","儉府清無事，唯應薦禰衡。"]', '["從知無远近，木落去閩城。","地入無諸俗，冠峨甲乙精。","山多高兴亂，江直好风生。","儉府清無事，唯應薦禰衡。"]', '诗', 'shi', '', NULL, '送沈侍郎 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd803d7e-c11b-455d-8586-97dd3fd5482a', '題宿禪師院', '題宿禪師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["身閑心亦然，如此已多年。","語淡不著物，茶香別有泉。","古衣和蘚衲，新偈幾人傳。","時說秋歸夢，孤峰在海邊。"]', '["身闲心亦然，如此已多年。","語淡不著物，茶香別有泉。","古衣和蘚衲，新偈幾人傳。","时说秋归梦，孤峰在海邊。"]', '诗', 'shi', '', NULL, '題宿禪師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc62ffe-a9da-467e-ab7f-74427ac8722f', '秋晚泊石頭驛有寄', '秋晚泊石头驛有寄', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蕭索漳江北，何人慰寂寥。","北風人獨立，南國信空遙。","燒塢新雲白，漁家衆木凋。","所思不可見，行雁在青霄。"]', '["蕭索漳江北，何人慰寂寥。","北风人独立，南国信空遙。","燒塢新云白，漁家衆木凋。","所思不可见，行雁在青霄。"]', '诗', 'shi', '', NULL, '秋晚泊石頭驛有寄 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1b470e-721b-44fa-a2a4-96d9be93a197', '別盧使君', '別盧使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["杜宇聲聲急，行行楚水濆。","道無裨政化，行處傲孤雲。","幸到膺門下，頻蒙俸粟分。","詩雖曾引玉，棊數中埋軍。","山好還尋去，恩深豈易云。","扇風千里泰，車雨九重聞。","晴霧和花氣，危檣鼓浪文。","終期陶鑄日，再見信陵君。"]', '["杜宇声声急，行行楚水濆。","道無裨政化，行处傲孤云。","幸到膺门下，頻蒙俸粟分。","诗雖曾引玉，棊數中埋軍。","山好還尋去，恩深豈易云。","扇风千里泰，车雨九重闻。","晴霧和花氣，危檣鼓浪文。","終期陶鑄日，再见信陵君。"]', '诗', 'shi', '', NULL, '別盧使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72345f4c-bb4b-44cc-8070-0bbe44c532b6', '秋夜吟', '秋夜吟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["如愚復愛詩，木落即眠遲。","思苦香消盡，更深筆尚隨。","飢童舂赤黍，繁露灑烏椑。","看却龍鍾也，歸山是底時。"]', '["如愚复愛诗，木落即眠遲。","思苦香消尽，更深笔尚隨。","飢童舂赤黍，繁露灑烏椑。","看却龙鍾也，归山是底时。"]', '诗', 'shi', '', NULL, '秋夜吟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4eb7117-8f24-4e2c-8c14-65738c975e89', '桐江閑居作十二首 一', '桐江闲居作十二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["木落雨翛翛，桐江古岸頭。","擬歸仙掌去，剛被謝公留。","猛燒侵茶塢，殘霞照角樓。","坐來還有意，流水面前流。"]', '["木落雨翛翛，桐江古岸头。","擬归仙掌去，剛被謝公留。","猛燒侵茶塢，殘霞照角楼。","坐来還有意，流水面前流。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc5d2a24-d230-4080-a9a7-8aa419da187a', '桐江閑居作十二首 二', '桐江闲居作十二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["香剎通真觀，樓臺倚郡城。","陰森古樹氣，粗淡老僧情。","壁畫連山潤，仙鐘扣月清。","何須結西社，大道本無生。"]', '["香剎通真观，楼台倚郡城。","陰森古樹氣，粗淡老僧情。","壁畫連山潤，仙鐘扣月清。","何須結西社，大道本無生。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a9a528-7aff-4962-8999-9d393ab433c0', '桐江閑居作十二首 三', '桐江闲居作十二首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["靜室焚檀印，深爐燒鐵瓶。","茶和阿魏煖，火種柏根馨。","數隻飛來鶴，成堆讀了經。","何妨似支遁，騎馬入青冥。"]', '["静室焚檀印，深爐燒鐵瓶。","茶和阿魏煖，火種柏根馨。","數隻飞来鹤，成堆读了經。","何妨似支遁，騎马入青冥。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ba63db-8003-44f6-8e52-3e422349a2b5', '桐江閑居作十二首 四', '桐江闲居作十二首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不問賡桑子，唯師妙吉祥。","等閑眠片石，不覺到斜陽。","獨自收櫧葉，教童探柏瓤。","王孫莫指笑，淡泊味還長。"]', '["不问賡桑子，唯師妙吉祥。","等闲眠片石，不覺到斜陽。","独自收櫧葉，教童探柏瓤。","王孫莫指笑，淡泊味還长。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2175d830-a5b5-4cf3-9256-861c224b55f7', '桐江閑居作十二首 五', '桐江闲居作十二首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["詩琢冰成句，多將大道論。","人誰知此意，日日祗關門。","乳鼠穿荒壁，溪龜上淨盆。","因知無事貴，言外更無言。"]', '["诗琢冰成句，多將大道論。","人誰知此意，日日祗关门。","乳鼠穿荒壁，溪龟上淨盆。","因知無事貴，言外更無言。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95e0da2-9bf1-40d4-8259-8aff74f66bed', '桐江閑居作十二首 六', '桐江闲居作十二首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["紅黍飯溪苔，清吟茗數杯。","祗應唯道在，無意俟時來。","樹疊藏仙洞，山蒸足爆雷。","從他嫌復笑，門更不曾開。"]', '["紅黍飯溪苔，清吟茗數杯。","祗應唯道在，無意俟时来。","樹叠藏仙洞，山蒸足爆雷。","從他嫌复笑，门更不曾开。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43491681-26bd-4df7-8847-eb0114f33d87', '桐江閑居作十二首 七', '桐江闲居作十二首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蟬急野蕭蕭，山中信屢招。","樹香烹菌朮，詩□□瓊瑤。","諸境教人認，荒榛引燒燒。","吾皇禮金骨，誰□美南朝。"]', '["蟬急野蕭蕭，山中信屢招。","樹香烹菌朮，诗□□瓊瑤。","諸境教人認，荒榛引燒燒。","吾皇禮金骨，誰□美南朝。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dffe621-5c62-4f4f-a3d0-24db011ab579', '桐江閑居作十二首 八', '桐江闲居作十二首 八', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["露滴滴蘅茅，秋成爽氣交。","霜椑如蜜裹，□□似鹽苞。","浮蘚侵蛩穴，微陽落鶴巢。","還如山裏日，門更絕人敲。"]', '["露滴滴蘅茅，秋成爽氣交。","霜椑如蜜裹，□□似鹽苞。","浮蘚侵蛩穴，微陽落鹤巢。","還如山裏日，门更絕人敲。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 八 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('859b171b-533d-4d04-8d1a-fd03b06d915b', '桐江閑居作十二首 九', '桐江闲居作十二首 九', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["壍鳥毛衣別，頻來似愛吟。","蕭條秋病後，斑駁綠苔深。","珠翠籠金像，風泉灑玉琴。","孰知吾所適，終不是心心。"]', '["壍鸟毛衣別，頻来似愛吟。","蕭條秋病後，斑駁綠苔深。","珠翠籠金像，风泉灑玉琴。","孰知吾所適，終不是心心。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 九 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da2eb8d9-4699-4a1d-b2fa-6aabe1a15c18', '桐江閑居作十二首 十', '桐江闲居作十二首 十', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["芙蓉峰裏居，關閉復何如。","白玃兼花鹿，多年不見渠。","紅泉香滴瀝，丹桂冷扶疎。","唯有西溪叟，時時到弊廬。"]', '["芙蓉峰裏居，关閉复何如。","白玃兼花鹿，多年不见渠。","紅泉香滴瀝，丹桂冷扶疎。","唯有西溪叟，时时到弊廬。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 十 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c2b1379-b10f-401e-b172-8081c5044a01', '桐江閑居作十二首 十一', '桐江闲居作十二首 十一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["憶在山中日，爲僧鬢欲衰。","一燈常到曉，十載不離師。","水汲冰溪滑，鐘撞雪閣危。","從來多自省，不學擬何爲。"]', '["憶在山中日，爲僧鬢欲衰。","一灯常到晓，十載不離師。","水汲冰溪滑，鐘撞雪閣危。","從来多自省，不学擬何爲。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 十一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf25b759-79db-45d1-9b69-610f5d730ff4', '桐江閑居作十二首 十二', '桐江闲居作十二首 十二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["囊非撲滿器，門更絕人過。","土井連岡冷，風簾迸葉多。","村童頑似鐵，山菜硬如莎。","唯有前山色，窗中無奈何。"]', '["囊非撲满器，门更絕人過。","土井連岡冷，风簾迸葉多。","村童頑似鐵，山菜硬如莎。","唯有前山色，窗中無奈何。"]', '诗', 'shi', '', NULL, '桐江閑居作十二首 十二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('510ab4a1-3617-4cc0-a1f5-0e7e561f5448', '寄馮使君', '寄馮使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山風與霜氣，浩浩滿松枝。","永日燒杉子，無人共此時。","爲文攀諷諫，得道在毫釐。","唯有桐江守，常憐志不卑。"]', '["山风與霜氣，浩浩满松枝。","永日燒杉子，無人共此时。","爲文攀諷諫，得道在毫釐。","唯有桐江守，常怜志不卑。"]', '诗', 'shi', '', NULL, '寄馮使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98da9e6a-be05-4f84-b49c-41ea3b29ba17', '經棲白舊院二首 一', '經棲白旧院二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["竺卿何處去，觸目盡淒涼。","不見中秋月，空餘一炷香。","殘花飄暮雨，枯葉蓋啼螿。","誰禮新墳塔，蕭條渭水傍。"]', '["竺卿何处去，觸目尽淒涼。","不见中秋月，空餘一炷香。","殘花飄暮雨，枯葉蓋啼螿。","誰禮新墳塔，蕭條渭水傍。"]', '诗', 'shi', '', NULL, '經棲白舊院二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae51901-884c-41b3-afab-24d227da488d', '經棲白舊院二首 二', '經棲白旧院二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["國寶還亡一，時多李德林。","故人卿相泣，承製渥恩深。","舊藳誰收得，空堂影似吟。","裴回不能去，寒日下西岑。"]', '["国寶還亡一，时多李德林。","故人卿相泣，承製渥恩深。","旧藳誰收得，空堂影似吟。","裴回不能去，寒日下西岑。"]', '诗', 'shi', '', NULL, '經棲白舊院二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ea552e-e6e3-4c4a-9643-46313a813fb2', '贈李祐道人', '贈李祐道人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["闒茸復埃塵，難親復易親。","皆疑有仙術，問著却愁人。","祗是耽浮蟻，曾云見泣麟。","相逢先合手，渾似有前因。"]', '["闒茸复埃塵，难親复易親。","皆疑有仙術，问著却愁人。","祗是耽浮蟻，曾云见泣麟。","相逢先合手，渾似有前因。"]', '诗', 'shi', '', NULL, '贈李祐道人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbe3e704-4cb1-42ce-8f08-1517e62a0a49', '贈景和尚院', '贈景和尚院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["藏經看幾徧，眉有數條霜。","萬境心都泯，深冬日亦長。","窗虛花木氣，衲挂水雲鄉。","時說秋歸夢，峰頭雪滿牀。"]', '["藏經看幾徧，眉有數條霜。","万境心都泯，深冬日亦长。","窗虛花木氣，衲挂水云乡。","时说秋归梦，峰头雪满牀。"]', '诗', 'shi', '', NULL, '贈景和尚院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb2a2fd-38b6-4c07-a1df-63ab004ec2ce', '上宋使君', '上宋使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["折桂文如錦，分憂力若春。","位高空倚命，詩妙古無人。","有感禾爭熟，無私吏盡貧。","野人如有幸，應得見陶鈞。"]', '["折桂文如錦，分憂力若春。","位高空倚命，诗妙古無人。","有感禾爭熟，無私吏尽貧。","野人如有幸，應得见陶鈞。"]', '诗', 'shi', '', NULL, '上宋使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd335a8-d8f6-41ab-bf90-eb0c68a3c72d', '離亂後寄九峰和尚二首 一', '離亂後寄九峰和尚二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["亂後知深隱，菴應近石樓。","異香因雪歇，仙果落池浮。","詩老全拋格，心空未到頭。","還應嫌笑我，世路獨悠悠。"]', '["亂後知深隐，菴應近石楼。","異香因雪歇，仙果落池浮。","诗老全拋格，心空未到头。","還應嫌笑我，世路独悠悠。"]', '诗', 'shi', '', NULL, '離亂後寄九峰和尚二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b935ca1c-a8d6-4181-bd4f-669a145fdf5d', '離亂後寄九峰和尚二首 二', '離亂後寄九峰和尚二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蕭灑復蕭灑，松根獨據梧。","瀑冰吟次折，遠燒坐來無。","老𤣎寒披衲，孤雲靜入廚。","不知知我否，已到不區區。"]', '["蕭灑复蕭灑，松根独據梧。","瀑冰吟次折，远燒坐来無。","老𤣎寒披衲，孤云静入廚。","不知知我否，已到不區區。"]', '诗', 'shi', '', NULL, '離亂後寄九峰和尚二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b198b1b-9ab1-44bb-9328-5f14fe6c4ea6', '送黃賓于赴舉', '送黄賓于赴舉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["冬暮雨菲菲，行人喜可稀。","二階□夜雪，亞聖在春闈。","馬疾頑童遠，山荒凍葉飛。","□師無一事，應見麗龜歸。"]', '["冬暮雨菲菲，行人喜可稀。","二階□夜雪，亞聖在春闈。","马疾頑童远，山荒凍葉飞。","□師無一事，應见丽龟归。"]', '诗', 'shi', '', NULL, '送黃賓于赴舉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee56384d-1331-4440-9bbc-06b173d75d9a', '題靈溪暢公墅', '題靈溪暢公墅', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["境清僧格冷，新斬古林開。","舊隱還如此，令人來又來。","嵐飛黏似霧，茶好碧於苔。","但使心清淨，從渠歲月催。"]', '["境清僧格冷，新斬古林开。","旧隐還如此，令人来又来。","嵐飞黏似霧，茶好碧於苔。","但使心清淨，從渠歲月催。"]', '诗', 'shi', '', NULL, '題靈溪暢公墅 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04ffd72a-f1b3-4649-ad10-1515e6a583a0', '送高九經赴舉', '送高九經赴舉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["回也曾言志，明君則事之。","中興今若此，須去更何疑。","志列秋霜好，忠言劇諫奇。","陸機遊洛日，文舉薦衡時。","虎跡商山雪，雲痕岳廟碑。","夫君將潦倒，一說向深知。"]', '["回也曾言志，明君則事之。","中兴今若此，須去更何疑。","志列秋霜好，忠言劇諫奇。","陸機游洛日，文舉薦衡时。","虎跡商山雪，云痕岳廟碑。","夫君將潦倒，一说向深知。"]', '诗', 'shi', '', NULL, '送高九經赴舉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d984c45-4fc0-4a41-b4cf-89b60352f152', '東西二林寺流水', '东西二林寺流水', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["水爾何如此，區區矻矻流。","牆牆邊瀝瀝，砌砌下啾啾。","味不卑於乳，聲常占得秋。","崩騰成大瀑，落托出深溝。","遠歷神仙窟，高淋竹樹頭。","數家舂碓磑，幾處浴猿猴。","共月穿峰罅，喧僧睡石樓。","派通天宇闊，霤入楚江浮。","爲潤知何極，無邊始自由。","好歸江海裏，長負濟川舟。"]', '["水爾何如此，區區矻矻流。","牆牆邊瀝瀝，砌砌下啾啾。","味不卑於乳，声常占得秋。","崩腾成大瀑，落托出深溝。","远歷神仙窟，高淋竹樹头。","數家舂碓磑，幾处浴猿猴。","共月穿峰罅，喧僧睡石楼。","派通天宇闊，霤入楚江浮。","爲潤知何極，無邊始自由。","好归江海裏，长負濟川舟。"]', '诗', 'shi', '', NULL, '東西二林寺流水 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ecbd4c-aa8d-42a8-ab02-e79733151163', '送王貞白重試東歸', '送王貞白重試东归', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["心苦酬心了，東歸謝所知。","可鄰重試者，如折兩三枝。","雨毒逢花少，山多愛馬遲。","此行三可羨，正值倒戈時。"]', '["心苦酬心了，东归謝所知。","可鄰重試者，如折兩三枝。","雨毒逢花少，山多愛马遲。","此行三可羨，正值倒戈时。"]', '诗', 'shi', '', NULL, '送王貞白重試東歸 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fafd02d-6d57-4fa9-88db-067a89caa8ba', '早秋即事寄馮使君', '早秋即事寄馮使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["金脈火初微，開門竹杖隨。","此身全是病，今日更嗔誰。","落葉崢嶸處，諸峰爽拔時。","唯思棠樹下，高論入圓伊。"]', '["金脈火初微，开门竹杖隨。","此身全是病，今日更嗔誰。","落葉崢嶸处，諸峰爽拔时。","唯思棠樹下，高論入圓伊。"]', '诗', 'shi', '', NULL, '早秋即事寄馮使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550739a8-64b7-4a4f-b24f-132835de272e', '贈景和尚院', '贈景和尚院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["貌古眉如雪，看經二十霜。","尋常對詩客，祗勸療心瘡。","炭火邕湖瀅，山晴紫竹涼。","怡然無一事，流水自湯湯。"]', '["貌古眉如雪，看經二十霜。","尋常对诗客，祗勸療心瘡。","炭火邕湖瀅，山晴紫竹涼。","怡然無一事，流水自湯湯。"]', '诗', 'shi', '', NULL, '贈景和尚院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b009a1a1-c9fa-444d-bb75-1df42230400c', '寄西山胡汾', '寄西山胡汾', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["待價欲要君，山前獨灌園。","雖然不識面，要且已消魂。","鹿睡紅霞影，泉淋白石門。","伊余心更苦，何日共深論。"]', '["待價欲要君，山前独灌园。","雖然不識面，要且已消魂。","鹿睡紅霞影，泉淋白石门。","伊余心更苦，何日共深論。"]', '诗', 'shi', '', NULL, '寄西山胡汾 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f3ee07-8164-48ef-b151-a89213c368f8', '題師頴和尚院', '題師頴和尚院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["師院清無敵，師心智不知。","臘高清眼細，閑甚白雲卑。","煮茗然楓枿，泥牆札祖碑。","愛師終不及，謾住許多時。"]', '["師院清無敵，師心智不知。","臘高清眼細，闲甚白云卑。","煮茗然楓枿，泥牆札祖碑。","愛師終不及，謾住許多时。"]', '诗', 'shi', '', NULL, '題師頴和尚院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b955db8-1d3d-4dc7-bb07-c05213bfb067', '遊雲頂山晚望', '游云頂山晚望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雲頂聊一望，山靈草木奇。","黔南在何處，堪笑復堪悲。","菊歇香未歇，露繁蟬不飢。","明朝又西去，錦水與峨眉。"]', '["云頂聊一望，山靈草木奇。","黔南在何处，堪笑复堪悲。","菊歇香未歇，露繁蟬不飢。","明朝又西去，錦水與峨眉。"]', '诗', 'shi', '', NULL, '遊雲頂山晚望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54eba643-8818-4d0e-b957-8f245334d9da', '劉相公見訪', '劉相公见訪', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["千騎擁朱輪，香塵豈是塵。","如何補衮服，來看衲衣人。","莊叟因先覺，空王有宿因。","對花無俗態，愛竹見天真。","欹枕松窗迥，題牆道意新。","戒師慙匪什，都講更勝詢。","桃熟多紅璺，茶香有碧筋。","高宗多不寐，終是夢中人。"]', '["千騎擁朱輪，香塵豈是塵。","如何補衮服，来看衲衣人。","莊叟因先覺，空王有宿因。","对花無俗態，愛竹见天真。","欹枕松窗迥，題牆道意新。","戒師慙匪什，都講更勝詢。","桃熟多紅璺，茶香有碧筋。","高宗多不寐，終是梦中人。"]', '诗', 'shi', '', NULL, '劉相公見訪 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aebf17e6-ad83-4325-84a7-68e85ed85208', '寄赤松舒道士二首 一', '寄赤松舒道士二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不見高人久，空令鄙恡多。","遙思青嶂下，無那白雲何。","子愛寒山子，歌惟樂道歌。","會應陪太守，一日到煙蘿。"]', '["不见高人久，空令鄙恡多。","遙思青嶂下，無那白云何。","子愛寒山子，歌惟乐道歌。","會應陪太守，一日到煙蘿。"]', '诗', 'shi', '', NULL, '寄赤松舒道士二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def6beb6-726d-417c-a6d9-2ed535e096f4', '寄赤松舒道士二首 二', '寄赤松舒道士二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["余亦如君也，詩魔不敢魔。","一餐兼午睡，萬事不如他。","雨陣衝溪月，蛛絲罥砌莎。","近知山果熟，還擬寄來麽。"]', '["余亦如君也，诗魔不敢魔。","一餐兼午睡，万事不如他。","雨陣衝溪月，蛛絲罥砌莎。","近知山果熟，還擬寄来麽。"]', '诗', 'shi', '', NULL, '寄赤松舒道士二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3c873c-6348-4d31-b01b-9595fd065cfd', '鄂渚逢楊贊禹', '鄂渚逢楊贊禹', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["流浪兵荒苦，相思歲月闌。","理惟通至道，人或謂無端。","燒猛湖煙赤，窗空雪月寒。","知音不可見，始爲一吟看。"]', '["流浪兵荒苦，相思歲月闌。","理惟通至道，人或謂無端。","燒猛湖煙赤，窗空雪月寒。","知音不可见，始爲一吟看。"]', '诗', 'shi', '', NULL, '鄂渚逢楊贊禹 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700ca29d-82f7-4c3a-8a66-0ff0c4a163a4', '別性空禪師', '別性空禪師', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["積翠迸一瀑，紅霞碧霧開。","方尋此境去，莫問幾時迴。","盪槳入檐石，思詩聞早雷。","唯師心似我，欲近不然灰。"]', '["積翠迸一瀑，紅霞碧霧开。","方尋此境去，莫问幾时迴。","盪槳入檐石，思诗闻早雷。","唯師心似我，欲近不然灰。"]', '诗', 'shi', '', NULL, '別性空禪師 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c58e3397-685a-4acd-8409-1c7d675c6014', '送胡處士', '送胡处士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不名兼不利，相遇海西濆。","白字未干髮，清時錯愛雲。","頭巾多酒氣，竹杖有苔文。","久積希顏意，林中又送君。"]', '["不名兼不利，相遇海西濆。","白字未干髮，清时錯愛云。","头巾多酒氣，竹杖有苔文。","久積希顏意，林中又送君。"]', '诗', 'shi', '', NULL, '送胡處士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d9609b-53d8-4eef-986a-64c6f645b180', '寄瀾公二首 一', '寄瀾公二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["小一頭應白，孤高住歙城。","不知安樂否，何以近無生。","燒逼鴻行側，風乾雪朕清。","途中逢此信，珍重未精誠。"]', '["小一头應白，孤高住歙城。","不知安乐否，何以近無生。","燒逼鴻行側，风乾雪朕清。","途中逢此信，珍重未精誠。"]', '诗', 'shi', '', NULL, '寄瀾公二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f60045a-4d04-430c-ae97-69454af2a690', '寄瀾公二首 二', '寄瀾公二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["荒亂拋深隱，飄零遠寓居。","片雲無定所，得力是逢渠。","瀑灂羣公社，江崩古帝墟。","終期再相見，招手復何如。"]', '["荒亂拋深隐，飄零远寓居。","片云無定所，得力是逢渠。","瀑灂羣公社，江崩古帝墟。","終期再相见，招手复何如。"]', '诗', 'shi', '', NULL, '寄瀾公二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0339c075-3dce-4d7d-8854-c9de165977ca', '寄棲一上人', '寄棲一上人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["花塹接滄洲，陰雲閑楚丘。","雨聲雖到夜，吟味不如秋。","古屋藏花鴿，荒園聚亂流。","無機心便是，何用話歸休。"]', '["花塹接滄洲，陰云闲楚丘。","雨声雖到夜，吟味不如秋。","古屋藏花鴿，荒园聚亂流。","無機心便是，何用話归休。"]', '诗', 'shi', '', NULL, '寄棲一上人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ada22b-c8fd-4f32-9766-b51d896d7de3', '送僧之湖南', '送僧之湖南', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["湘水萬餘里，師遊芳草生。","登山乞食後，無伴入雲行。","宿雨和花落，春牛擁霧耕。"]', '["湘水万餘里，師游芳草生。","登山乞食後，無伴入云行。","宿雨和花落，春牛擁霧耕。"]', '诗', 'shi', '', NULL, '送僧之湖南 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc3720c-f1fc-4a11-8cc6-097cfe626633', '秋末寄張侍郎', '秋末寄張侍郎', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["靜坐黔城北，離仁半歲彊。","霧中紅黍熟，燒後白雲香。","多病如何好，無心去始長。","寂寥還得句，溪上寄三張。"]', '["静坐黔城北，離仁半歲彊。","霧中紅黍熟，燒後白云香。","多病如何好，無心去始长。","寂寥還得句，溪上寄三張。"]', '诗', 'shi', '', NULL, '秋末寄張侍郎 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f49601d-f757-4cd2-b8f0-4b8d6f05bb9d', '古塞曲三首 一', '古塞曲三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["單于烽火動，都護去天涯。","別賜黃金甲，親臨白玉除。","塞垣須靜謐，師旅審安危。","定遠條支寵，如今勝古時。"]', '["單于烽火动，都護去天涯。","別賜黄金甲，親臨白玉除。","塞垣須静謐，師旅審安危。","定远條支寵，如今勝古时。"]', '诗', 'shi', '', NULL, '古塞曲三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516fbe77-eee2-4a8c-a982-6d0548f33e0f', '古塞曲三首 二', '古塞曲三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["方見將軍貴，分明[對]冕旒。","聖恩如遠被，狂虜不難收。","臣節唯期死，功勳敢望侯。","終辭脩里第，從此出皇州。"]', '["方见將軍貴，分明[对]冕旒。","聖恩如远被，狂虜不难收。","臣節唯期死，功勳敢望侯。","終辞脩里第，從此出皇州。"]', '诗', 'shi', '', NULL, '古塞曲三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d71efae1-1556-4efc-83e4-500de066aa44', '古塞曲三首 三', '古塞曲三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["百萬精兵動，參差便渡遼。","如何好白日，亦照此天驕。","遠樹深疑賊，驚蓬迥似鵰。","凱歌何日唱，磧路共天遙。"]', '["百万精兵动，參差便渡遼。","如何好白日，亦照此天驕。","远樹深疑賊，驚蓬迥似鵰。","凱歌何日唱，磧路共天遙。"]', '诗', 'shi', '', NULL, '古塞曲三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e385d41-7a71-4829-905d-bd7f1e806c99', '古塞下曲七首 一', '古塞下曲七首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["下營依遁甲，分帥把河隍。","地使人心惡，風吹旗燄荒。","搜山得探卒，放火獵黃羊。","唯有南飛雁，聲聲斷客腸。"]', '["下營依遁甲，分帥把河隍。","地使人心惡，风吹旗燄荒。","搜山得探卒，放火獵黄羊。","唯有南飞雁，声声斷客腸。"]', '诗', 'shi', '', NULL, '古塞下曲七首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12b7929-807e-4c85-bf63-961b810df9c3', '古塞下曲七首 二', '古塞下曲七首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["歸去是何年，山連邏逤川。","蒼黃曾戰地，空闊養鵰天。","旗插蒸沙堡，槍擔卓槊泉。","蕭條寒日落，號令徹窮邊。"]', '["归去是何年，山連邏逤川。","蒼黄曾戰地，空闊養鵰天。","旗插蒸沙堡，槍擔卓槊泉。","蕭條寒日落，號令徹窮邊。"]', '诗', 'shi', '', NULL, '古塞下曲七首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6917c039-5787-4737-afbe-960f9d8123ce', '古塞下曲七首 三', '古塞下曲七首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["虜寇日相持，如龍馬不肥。","突圍金甲破，趂賊鐵槍飛。","漢月堂堂上，胡雲慘慘微。","黃河冰已合，猶未送征衣。"]', '["虜寇日相持，如龙马不肥。","突圍金甲破，趂賊鐵槍飞。","漢月堂堂上，胡云慘慘微。","黄河冰已合，猶未送征衣。"]', '诗', 'shi', '', NULL, '古塞下曲七首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b785cad-7bd9-4a1e-86bd-5118ea86eeea', '古塞下曲七首 四', '古塞下曲七首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["南北惟堪恨，東西實可嗟。","常飛侵夏雪，何處有人家？","風刮陰山薄，河推大岸斜。","祗應寒夜夢，時見故園花。"]', '["南北惟堪恨，东西實可嗟。","常飞侵夏雪，何处有人家？","风刮陰山薄，河推大岸斜。","祗應寒夜梦，时见故园花。"]', '诗', 'shi', '', NULL, '古塞下曲七首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1ee72d0-3426-41ff-9681-25376a1dce20', '古塞下曲七首 五', '古塞下曲七首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不是將軍勇，胡兵豈易當。","雨曾淋火陣，箭又中金瘡。","鐵嶺全無土，豺羣亦有狼。","因思無戰日，天子是陶唐。"]', '["不是將軍勇，胡兵豈易當。","雨曾淋火陣，箭又中金瘡。","鐵嶺全無土，豺羣亦有狼。","因思無戰日，天子是陶唐。"]', '诗', 'shi', '', NULL, '古塞下曲七首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1bd78c1-45dd-4000-a6a0-f5fd0f95fffd', '古塞下曲七首 六', '古塞下曲七首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["榆葉飄蕭盡，關防烽寨重。","寒來知馬疾，戰後覺人兇。","燒逐飛蓬死，沙生毒霧濃。","誰能奏明主，功業已堪封。"]', '["榆葉飄蕭尽，关防烽寨重。","寒来知马疾，戰後覺人兇。","燒逐飞蓬死，沙生毒霧濃。","誰能奏明主，功業已堪封。"]', '诗', 'shi', '', NULL, '古塞下曲七首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601d8e9a-142c-4dfa-a390-8f422ac68e79', '古塞下曲七首 七', '古塞下曲七首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬戰千征地，蒼茫古塞門。","陰兵爲客祟，惡酒發刀痕。","風落崑崙石，河崩苜蓿根。","將軍更移帳，日日近西蕃。"]', '["万戰千征地，蒼茫古塞门。","陰兵爲客祟，惡酒發刀痕。","风落崑崙石，河崩苜蓿根。","將軍更移帳，日日近西蕃。"]', '诗', 'shi', '', NULL, '古塞下曲七首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2e6b95-1383-4d00-8fa6-ff3ac7779bf7', '古塞上曲七首 一', '古塞上曲七首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["幽幷兒百萬，百戰未曾輸。","蕃界已深入，將軍仍遠圖。","月明風拔帳，磧暗鬼騎狐。","但有東歸日，甘從筋力枯。"]', '["幽幷兒百万，百戰未曾輸。","蕃界已深入，將軍仍远圖。","月明风拔帳，磧暗鬼騎狐。","但有东归日，甘從筋力枯。"]', '诗', 'shi', '', NULL, '古塞上曲七首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d253d8-25c2-474e-b0c8-dc2bf199bef9', '古塞上曲七首 二', '古塞上曲七首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["中軍殺白馬，白日祭蒼蒼。","號變旗幡亂，鼙乾草木黃。","朔雲含凍雨，枯骨放妖光。","故國今何處，參差近鬼方。"]', '["中軍殺白马，白日祭蒼蒼。","號变旗幡亂，鼙乾草木黄。","朔云含凍雨，枯骨放妖光。","故国今何处，參差近鬼方。"]', '诗', 'shi', '', NULL, '古塞上曲七首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e6902f-8152-4c25-84e3-b6dc1965eb78', '古塞上曲七首 三', '古塞上曲七首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["白雁兼羌笛，幾年垂淚聽。","陰風吹殺氣，永日在青冥。","遠戍秋添將，邊烽夜雜星。","嫖姚頭半白，猶自看兵經。"]', '["白雁兼羌笛，幾年垂泪听。","陰风吹殺氣，永日在青冥。","远戍秋添將，邊烽夜杂星。","嫖姚头半白，猶自看兵經。"]', '诗', 'shi', '', NULL, '古塞上曲七首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81687455-4367-4bec-9567-2b973766009e', '古塞上曲七首 四', '古塞上曲七首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["久雨始無塵，邊聲四散聞。","浸河荒寨柱，吹角白頭軍。","戰馬齕𦎬草，烏鳶識陣雲。","征人心力盡，枯骨更遭焚。"]', '["久雨始無塵，邊声四散闻。","浸河荒寨柱，吹角白头軍。","戰马齕𦎬草，烏鳶識陣云。","征人心力尽，枯骨更遭焚。"]', '诗', 'shi', '', NULL, '古塞上曲七首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('061e8cbe-c05c-48b2-ab99-786946dc247d', '古塞上曲七首 五', '古塞上曲七首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["帳幕侵奚界，憑陵未可涯。","擒生行別路，尋箭向平沙。","赤落蒲桃葉，香微甘草花。","不堪登隴望，白日又西斜。"]', '["帳幕侵奚界，憑陵未可涯。","擒生行別路，尋箭向平沙。","赤落蒲桃葉，香微甘草花。","不堪登隴望，白日又西斜。"]', '诗', 'shi', '', NULL, '古塞上曲七首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f42235ee-d4d1-4139-a8fc-599f139dd27d', '古塞上曲七首 六', '古塞上曲七首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["地角天涯外，人號鬼哭邊。","大河流敗卒，寒日下蒼煙。","殺氣諸蕃動，軍書一箭傳。","將軍莫惆悵，高處是燕然。"]', '["地角天涯外，人號鬼哭邊。","大河流敗卒，寒日下蒼煙。","殺氣諸蕃动，軍书一箭傳。","將軍莫惆悵，高处是燕然。"]', '诗', 'shi', '', NULL, '古塞上曲七首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a412022b-2965-4ddb-bb76-ea59af9e74db', '古塞上曲七首 七', '古塞上曲七首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山接胡奴水，河連勃勃城。","數州今已伏，此命豈堪輕。","磧吼旄頭落，風乾刁斗清。","因嗟李陵苦，祗得沒蕃名。"]', '["山接胡奴水，河連勃勃城。","數州今已伏，此命豈堪轻。","磧吼旄头落，风乾刁斗清。","因嗟李陵苦，祗得沒蕃名。"]', '诗', 'shi', '', NULL, '古塞上曲七首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53b39de2-aa4e-420a-b55d-d4b3c6a423e7', '古出塞曲三首 一', '古出塞曲三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["掃盡狂胡迹，迴頭望故關。","相逢惟死鬬，豈易得生還。","縱宴參胡樂，收兵過雪山。","不封十萬戶，此事亦應閑。"]', '["掃尽狂胡迹，迴头望故关。","相逢惟死鬬，豈易得生還。","縱宴參胡乐，收兵過雪山。","不封十万戶，此事亦應闲。"]', '诗', 'shi', '', NULL, '古出塞曲三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7614674-e17b-427d-a0c5-9e26147f16d2', '古出塞曲三首 二', '古出塞曲三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["玉帳將軍意，殷勤把酒論。","功高寧在我，陣沒與招魂。","塞色干戈束，軍容喜氣屯。","男兒今始是，譀出玉關門。"]', '["玉帳將軍意，殷勤把酒論。","功高寧在我，陣沒與招魂。","塞色干戈束，軍容喜氣屯。","男兒今始是，譀出玉关门。"]', '诗', 'shi', '', NULL, '古出塞曲三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('866e6de8-31cf-4772-8078-50e5c00f708a', '古出塞曲三首 三', '古出塞曲三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["回首隴山頭，連天草木秋。","聖君應入夢，半路遣封侯。","水不擔陰雪，柴令倒戍樓。","歸來麟閣上，春色滿皇州。"]', '["回首隴山头，連天草木秋。","聖君應入梦，半路遣封侯。","水不擔陰雪，柴令倒戍楼。","归来麟閣上，春色满皇州。"]', '诗', 'shi', '', NULL, '古出塞曲三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df764d09-6970-4b94-ab8d-1bf5cc159c79', '聞赤松舒道士下世', '闻赤松舒道士下世', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["地變賢人喪，瘡痍不可觀。","一聞消息苦，千種破除難。","陰騭那虛擲，深山近始安。","玄關評兔角，玉器琢雞冠。","傲野高難狎，融怡美不殫。","冀迎新渥澤，遽逐逝波瀾。","蛻殼埋金隧，飛精駕錦鸞。","傾摧千仞壁，枯歇一株蘭。","仙廟詩雖繼，苔牆篆必鞔。","煙霞成片黯，松桂著行乾。","影拄溪流咽，堂扃隟月寒。","寂寥遺藥犬，縹緲想瓊竿。","伊昔相尋遠，留連幾盡歡。","論詩花作席，炙菌葉爲盤。","彭伉心相似，承禎趣一般。","琴彈溪月側，棊次砌雲殘。","儵忽成千古，飄零見百端。","荆囊春浩浩，吳越浪漫漫。","已矣紅霞子，空留白石壇。","無弦亦須絕，回首一長歎。"]', '["地变賢人喪，瘡痍不可观。","一闻消息苦，千種破除难。","陰騭那虛擲，深山近始安。","玄关評兔角，玉器琢雞冠。","傲野高难狎，融怡美不殫。","冀迎新渥澤，遽逐逝波瀾。","蛻殼埋金隧，飞精駕錦鸾。","傾摧千仞壁，枯歇一株蘭。","仙廟诗雖繼，苔牆篆必鞔。","煙霞成片黯，松桂著行乾。","影拄溪流咽，堂扃隟月寒。","寂寥遺藥犬，縹緲想瓊竿。","伊昔相尋远，留連幾尽歡。","論诗花作席，炙菌葉爲盤。","彭伉心相似，承禎趣一般。","琴彈溪月側，棊次砌云殘。","儵忽成千古，飄零见百端。","荆囊春浩浩，吳越浪漫漫。","已矣紅霞子，空留白石壇。","無弦亦須絕，回首一长歎。"]', '诗', 'shi', '', NULL, '聞赤松舒道士下世 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd6df86-e9e8-4c18-8117-3b7ea20163d2', '贈抱麻劉舍人', '贈抱麻劉舍人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["郡政今良吏，門風古縉紳。","萬年唐社稷，一箇哭麻人。","憤烈身先死，敷敭氣益貞。","天乎資大寶，泰矣見忠臣。","得罪鍾多故，投荒豈是迍。","玉寒方重澀，松古更青皴。","鵬𪄚寧唯白，龍多豈止荀。","道孤梳有雪，恩重淚盈巾。","喻蜀須憑草，成周必仗仁。","三峰宵旰切，萬里渥恩新。","賦鵩言無累，依劉德有鄰。","風期仁祖帽，鼠訝史雲塵。","禪叟知何幸，玄談有宿因。","雙溪逢陸海，荆渚遇平津。","落日愁聞笛，何人爲吐茵。","生徒希匠化，寰海仰經綸。","疾愈蟬聲老，年豐雨滴頻。","劉虬師弟子，時喜一相親。"]', '["郡政今良吏，门风古縉紳。","万年唐社稷，一箇哭麻人。","憤烈身先死，敷敭氣益貞。","天乎資大寶，泰矣见忠臣。","得罪鍾多故，投荒豈是迍。","玉寒方重澀，松古更青皴。","鵬𪄚寧唯白，龙多豈止荀。","道孤梳有雪，恩重泪盈巾。","喻蜀須憑草，成周必仗仁。","三峰宵旰切，万里渥恩新。","賦鵩言無累，依劉德有鄰。","风期仁祖帽，鼠訝史云塵。","禪叟知何幸，玄談有宿因。","雙溪逢陸海，荆渚遇平津。","落日愁闻笛，何人爲吐茵。","生徒希匠化，寰海仰經綸。","疾愈蟬声老，年豐雨滴頻。","劉虬師弟子，时喜一相親。"]', '诗', 'shi', '', NULL, '贈抱麻劉舍人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3d56f2-c049-40d4-8349-c4c108be013f', '夜寒寄盧給事二首 一', '夜寒寄盧給事二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["刻羽流商否，霜風動地吹。","邇來唯自惜，知合是誰知。","塹雪消難盡，鄰僧睡太奇。","知音不可得，始爲一吟之。"]', '["刻羽流商否，霜风动地吹。","邇来唯自惜，知合是誰知。","塹雪消难尽，鄰僧睡太奇。","知音不可得，始爲一吟之。"]', '诗', 'shi', '', NULL, '夜寒寄盧給事二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1bd2ac-136b-4a81-bef8-b8b6e7c3029e', '夜寒寄盧給事二首 二', '夜寒寄盧給事二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["心苦味不苦，世衰吾道微。","清如吞雪雹，誰把比珠璣。","作者相收拾，常人任是非。","舊居滄海上，歸去即應歸。"]', '["心苦味不苦，世衰吾道微。","清如吞雪雹，誰把比珠璣。","作者相收拾，常人任是非。","旧居滄海上，归去即應归。"]', '诗', 'shi', '', NULL, '夜寒寄盧給事二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad3a5bb-70bb-4bc2-8911-b2a6992baa33', '送葉蒙赴舉', '送葉蒙赴舉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["年年屈復屈，惆悵曲江湄。","自古身榮者，多非年少時。","空囊投刺遠，大雪入關遲。","來歲還公道，平人不用疑。"]', '["年年屈复屈，惆悵曲江湄。","自古身榮者，多非年少时。","空囊投刺远，大雪入关遲。","来歲還公道，平人不用疑。"]', '诗', 'shi', '', NULL, '送葉蒙赴舉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0416605-ce3a-4e92-80db-2bd29c632882', '聞王慥常侍卒三首 一', '闻王慥常侍卒三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["世亂君巡狩，清賢又告亡。","星辰皆有角，日月略無光。","金柱連天折，瑤階被賊荒。","令人轉惆悵，無路問蒼蒼。"]', '["世亂君巡狩，清賢又告亡。","星辰皆有角，日月略無光。","金柱連天折，瑤階被賊荒。","令人轉惆悵，無路问蒼蒼。"]', '诗', 'shi', '', NULL, '聞王慥常侍卒三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbe45d0-4760-4422-87b2-96df7becce86', '聞王慥常侍卒三首 二', '闻王慥常侍卒三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["宗社運微衰，山摧甘井枯。","不知千載後，更有此人無。","政入龔黃甲，詩輕沈宋徒。","受恩酬未得，不覺祗長吁。"]', '["宗社運微衰，山摧甘井枯。","不知千載後，更有此人無。","政入龔黄甲，诗轻沈宋徒。","受恩酬未得，不覺祗长吁。"]', '诗', 'shi', '', NULL, '聞王慥常侍卒三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab574363-6946-4118-af09-3671cf4fca1f', '聞王慥常侍卒三首 三', '闻王慥常侍卒三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["儻在扶天步，重興古國風。","還如齊晏子，再見狄梁公。","棠樹梅溪北，佳城舜廟東。","誰修循吏傳，對此莫悤悤。"]', '["儻在扶天步，重兴古国风。","還如齊晏子，再见狄梁公。","棠樹梅溪北，佳城舜廟东。","誰修循吏傳，对此莫悤悤。"]', '诗', 'shi', '', NULL, '聞王慥常侍卒三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e320ab-c0d5-41a3-a836-ead8b94564f3', '秋晚野步', '秋晚野步', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["藤屨兼閩竹，吟行一水傍。","樹涼蟬不少，溪斷路多荒。","燒岳陰風起，田家濁酒香。","登高吟更苦，微月出蒼茫。"]', '["藤屨兼閩竹，吟行一水傍。","樹涼蟬不少，溪斷路多荒。","燒岳陰风起，田家濁酒香。","登高吟更苦，微月出蒼茫。"]', '诗', 'shi', '', NULL, '秋晚野步 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f25f808d-b3dc-46a3-94f1-27d63e18543a', '聞大願和尚順世三首 一', '闻大願和尚順世三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["王室今如燬，仍聞喪我師。","古容圖得否，內院去無疑。","岳鬼月中哭，松龕雪次隳。","直須文五色，始可立高碑。"]', '["王室今如燬，仍闻喪我師。","古容圖得否，內院去無疑。","岳鬼月中哭，松龕雪次隳。","直須文五色，始可立高碑。"]', '诗', 'shi', '', NULL, '聞大願和尚順世三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b672cb2d-0d41-4ee4-8a20-f78d899df704', '聞大願和尚順世三首 二', '闻大願和尚順世三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鄴衛松杉外，芝蘭季孟間。","盡希重詔出，祗待六龍還。","不疾成千古，令焚動四山。","感恩終有淚，遙寄水潺潺。"]', '["鄴衛松杉外，芝蘭季孟间。","尽希重詔出，祗待六龙還。","不疾成千古，令焚动四山。","感恩終有泪，遙寄水潺潺。"]', '诗', 'shi', '', NULL, '聞大願和尚順世三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e07d818-f8e9-4ecd-ad9a-9e96b6ff1301', '聞大願和尚順世三首 三', '闻大願和尚順世三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["師稟盡名卿，孤峰老稱情。","若遊三點外，爭把七賢平。","苦霧埋空室，啼猨有咽聲。","今朝益惆悵，曾沐下牀迎。"]', '["師稟尽名卿，孤峰老稱情。","若游三点外，爭把七賢平。","苦霧埋空室，啼猨有咽声。","今朝益惆悵，曾沐下牀迎。"]', '诗', 'shi', '', NULL, '聞大願和尚順世三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5400d94-a37f-4b08-9198-37ba84d6bb2c', '聞葉蒙及第', '闻葉蒙及第', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["憶昨送君詩，平人不用疑。","吾徒若不得，天道即應私。","塵土茫茫曉，麟龍草草騎。","相思不可見，又是落花時。"]', '["憶昨送君诗，平人不用疑。","吾徒若不得，天道即應私。","塵土茫茫晓，麟龙草草騎。","相思不可见，又是落花时。"]', '诗', 'shi', '', NULL, '聞葉蒙及第 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f6aaf57-b3d9-4c03-a172-c1b300641f67', '送僧之靈夏', '送僧之靈夏', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["舊識爲邊帥，師遊勝事兼。","連天唯白草，野餅有紅鹽。","蕃近風多{孛支}，河渾磧半淹。","因知心似月，處處有人瞻。"]', '["旧識爲邊帥，師游勝事兼。","連天唯白草，野餅有紅鹽。","蕃近风多{孛支}，河渾磧半淹。","因知心似月，处处有人瞻。"]', '诗', 'shi', '', NULL, '送僧之靈夏 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab6673b-d3b3-498d-be60-a1adfd4858f4', '書無相道人菴', '书無相道人菴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["造化太茫茫，端居紫石房。","心遺無句句，頂處有霜霜。","白鹿眠枯葉，清泉灑毳囊。","寄言疑未決，須道雪溪旁。"]', '["造化太茫茫，端居紫石房。","心遺無句句，頂处有霜霜。","白鹿眠枯葉，清泉灑毳囊。","寄言疑未決，須道雪溪旁。"]', '诗', 'shi', '', NULL, '書無相道人菴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d511214-d634-4647-a5f8-822a6080a045', '明進士北齋避暑', '明進士北斋避暑', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["相訪多衝雨，由來德有鄰。","卷簾繁暑退，濕樹一蟬新。","道在誰爲主，吾衰自有因。","祗應江海上，還作狎鷗人。"]', '["相訪多衝雨，由来德有鄰。","卷簾繁暑退，濕樹一蟬新。","道在誰爲主，吾衰自有因。","祗應江海上，還作狎鷗人。"]', '诗', 'shi', '', NULL, '明進士北齋避暑 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba3d33d-418b-40da-87ff-6836c230ac78', '晚春寄吳融于競二侍郎', '晚春寄吳融于競二侍郎', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["白頭爲遠客，常憶白雲間。","祗覺老轉老，不知閑是閑。","花含宜細雨，室冷是深山。","唯有霜臺客，依依是往還。"]', '["白头爲远客，常憶白云间。","祗覺老轉老，不知闲是闲。","花含宜細雨，室冷是深山。","唯有霜台客，依依是往還。"]', '诗', 'shi', '', NULL, '晚春寄吳融于競二侍郎 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15231ea-e011-4af2-a471-d93536cf93ce', '喜不思上人來', '喜不思上人来', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["沃州那不住，一別許多時。","幾度懷君夜，相逢出夢遲。","瓶擔千丈瀑，偈是七言詩。","若向羅浮去，伊余亦願隨。"]', '["沃州那不住，一別許多时。","幾度懷君夜，相逢出梦遲。","瓶擔千丈瀑，偈是七言诗。","若向羅浮去，伊余亦願隨。"]', '诗', 'shi', '', NULL, '喜不思上人來 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4e8c4e-9f12-407c-8ad7-055d61527087', '秋懷赤松道士', '秋懷赤松道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["仙觀在雲端，相思星斗寒。","常憐呼鶴易，却恨見君難。","石罅青虵濕，風榸白菌乾。","終期花月下，壇上聽君彈。"]', '["仙观在云端，相思星斗寒。","常怜呼鹤易，却恨见君难。","石罅青虵濕，风榸白菌乾。","終期花月下，壇上听君彈。"]', '诗', 'shi', '', NULL, '秋懷赤松道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('316bb760-a73a-4ae5-a498-a604d2526270', '送劉逖赴閩辟', '送劉逖赴閩辟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["離亂生涯盡，依劉是見機。","從來吟太苦，不得力還稀。","路入閩山熟，江浮瘴雨肥。","何須折楊柳，相送已依依。"]', '["離亂生涯尽，依劉是见機。","從来吟太苦，不得力還稀。","路入閩山熟，江浮瘴雨肥。","何須折楊柳，相送已依依。"]', '诗', 'shi', '', NULL, '送劉逖赴閩辟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16e05dff-217a-4b95-b122-042cc9fd1250', '苦雨中作', '苦雨中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["通宵復連夕，其狀祗如傾。","却遣思山者，忽然嫌水聲。","好花飄草盡，古壁欲雲生。","不奈天難問，迢迢遠客情。"]', '["通宵复連夕，其狀祗如傾。","却遣思山者，忽然嫌水声。","好花飄草尽，古壁欲云生。","不奈天难问，迢迢远客情。"]', '诗', 'shi', '', NULL, '苦雨中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409fb19a-ee56-4158-88a1-d52bd7f9710f', '送僧歸日本', '送僧归日本', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["焚香祝海靈，開眼夢中行。","得達即便是，無生可作輕。","流黃山火著，碇石索雷鳴。","想到夷王禮，還爲上寺迎。"]', '["焚香祝海靈，开眼梦中行。","得達即便是，無生可作轻。","流黄山火著，碇石索雷鳴。","想到夷王禮，還爲上寺迎。"]', '诗', 'shi', '', NULL, '送僧歸日本 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d4be1a-303f-426e-918a-c1208bb1066b', '贈信安鄭道人', '贈信安鄭道人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["貌古似蒼鶴，心清如鼎湖。","仍聞得新義，便欲註陰符。","點化金常有，閑行影漸無。","杳兮中便是，應不食菖蒲。"]', '["貌古似蒼鹤，心清如鼎湖。","仍闻得新義，便欲註陰符。","点化金常有，闲行影漸無。","杳兮中便是，應不食菖蒲。"]', '诗', 'shi', '', NULL, '贈信安鄭道人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292b47cc-a1bc-4c6a-aab1-bf808b3b459d', '送吏部劉相公除東川', '送吏部劉相公除东川', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["帝念梓州民，年年戰仗頻。","山川無草木，烽火沒煙塵。","政亂皆因亂，安人必藉仁。","皇天開白日，殷鼎輟誠臣。","一日離君側，千官送渭濱。","酒傾紅琥珀，馬控白騏驎。","渥澤番番降，壺漿處處陳。","旌幢山色濕，邛僰鳥啼新。","帟幕還名儉，良醫始姓秦。","軍雄城似岳，地變物含春。","白必侵雙鬢，清應誡四鄰。","吾皇重命相，更合是何人。"]', '["帝念梓州民，年年戰仗頻。","山川無草木，烽火沒煙塵。","政亂皆因亂，安人必藉仁。","皇天开白日，殷鼎輟誠臣。","一日離君側，千官送渭濱。","酒傾紅琥珀，马控白騏驎。","渥澤番番降，壺漿处处陳。","旌幢山色濕，邛僰鸟啼新。","帟幕還名儉，良醫始姓秦。","軍雄城似岳，地变物含春。","白必侵雙鬢，清應誡四鄰。","吾皇重命相，更合是何人。"]', '诗', 'shi', '', NULL, '送吏部劉相公除東川 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db4b8ed-970a-46c8-8236-aa920d6c5cc4', '送智光禪伯', '送智光禪伯', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬事歸一衲，曹溪初去尋。","從來相狎輩，盡不是知音。","乞食林花落，穿雲翠巘深。","終希重一見，示我祖師心。"]', '["万事归一衲，曹溪初去尋。","從来相狎輩，尽不是知音。","乞食林花落，穿云翠巘深。","終希重一见，示我祖師心。"]', '诗', 'shi', '', NULL, '送智光禪伯 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c4f55cf-9f7a-4779-9d4d-04909ce6bd0b', '夜對雪寄杜使君', '夜对雪寄杜使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["片片含天意，紛紛勢莫拘。","灑於諸瑞後，憂恐一冬無。","鶴凚聲偏密，風焦片益粗。","冷牽人夢轉，清逼瘴根徂。","掃徑僧傾笠，爲詩士棄爐。","橋高銀螮蝀，峰峻玉浮圖。","盈尺何須問，豐年已可□。","遙思郢中曲，句句出冰壺。"]', '["片片含天意，紛紛勢莫拘。","灑於諸瑞後，憂恐一冬無。","鹤凚声偏密，风焦片益粗。","冷牽人梦轉，清逼瘴根徂。","掃徑僧傾笠，爲诗士棄爐。","橋高銀螮蝀，峰峻玉浮圖。","盈尺何須问，豐年已可□。","遙思郢中曲，句句出冰壺。"]', '诗', 'shi', '', NULL, '夜對雪寄杜使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39815561-8fff-46bd-8a48-adaa57c7e7ef', '送王轂及第後歸江西', '送王轂及第後归江西', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["太宗羅俊彥，桂玉比光輝。","難得終須得，言歸始是歸。","風帆天際吼，金鶚月中飛。","五府如交辟，魚書莫便稀。"]', '["太宗羅俊彥，桂玉比光輝。","难得終須得，言归始是归。","风帆天際吼，金鶚月中飞。","五府如交辟，鱼书莫便稀。"]', '诗', 'shi', '', NULL, '送王轂及第後歸江西 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb6681d-abba-4cbd-9e5d-cd9307c60621', '送盧瞻罷廬陵幕歸閿鄉', '送盧瞻罷廬陵幕归閿乡', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["文行成身事，從知貴得仁。","歸來還寂寞，何以慰交親。","芳草色似動，胡桃花又新。","昌朝有知己，好作諫垣臣。"]', '["文行成身事，從知貴得仁。","归来還寂寞，何以慰交親。","芳草色似动，胡桃花又新。","昌朝有知己，好作諫垣臣。"]', '诗', 'shi', '', NULL, '送盧瞻罷廬陵幕歸閿鄉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89dbb1ab-0373-435a-862c-366a73b016f4', '避寇白沙驛作', '避寇白沙驛作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["避亂無深淺，蒼黃古驛東。","草枯牛尚齕，霞濕燒微紅。","□□時時□，人愁處處同。","猶逢好時否，孤坐雪濛濛。"]', '["避亂無深淺，蒼黄古驛东。","草枯牛尚齕，霞濕燒微紅。","□□时时□，人愁处处同。","猶逢好时否，孤坐雪濛濛。"]', '诗', 'shi', '', NULL, '避寇白沙驛作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ddb6ca-d910-4a35-8f78-f7206e28b12d', '聞李頻員外卒', '闻李頻員外卒', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蒼蒼難可問，問荅亦難聞。","落葉平津岸，愁人李使君。","文章應力竭，茅土始天分。","又逐東風去，迢迢隔嶺雲。"]', '["蒼蒼难可问，问荅亦难闻。","落葉平津岸，愁人李使君。","文章應力竭，茅土始天分。","又逐东风去，迢迢隔嶺云。"]', '诗', 'shi', '', NULL, '聞李頻員外卒 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de94bff-c805-4a0b-8756-c7aa6ac9e8df', '江陵寄翰林韓偓學士', '江陵寄翰林韓偓学士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["久住荆溪北，禪關挂綠蘿。","風清閑客去，睡美落花多。","萬事皆妨道，孤峰謾憶他。","新詩舊知己，始爲味如何。"]', '["久住荆溪北，禪关挂綠蘿。","风清闲客去，睡美落花多。","万事皆妨道，孤峰謾憶他。","新诗旧知己，始爲味如何。"]', '诗', 'shi', '', NULL, '江陵寄翰林韓偓學士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bbc7fb7-5814-4ba0-932a-b9f8b7a50d7c', '閑居作', '闲居作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["閑門微雪下，慵惰計全成。","默作便終日，孤峰祗此清。","身心閑少夢，杉竹冷多聲。","唯有西峰叟，相逢眼最明。"]', '["闲门微雪下，慵惰計全成。","默作便終日，孤峰祗此清。","身心闲少梦，杉竹冷多声。","唯有西峰叟，相逢眼最明。"]', '诗', 'shi', '', NULL, '閑居作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d82ab1-d18d-496b-b0f7-7931ce75bf6f', '和韋相公見示閑臥', '和韋相公见示闲臥', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["刻形求得相，事事未嘗眠。","霖雨方爲雨，非煙豈是煙。","童收庭樹果，風曳案頭牋。","仲虺專爲誥，何充雅愛禪。","靜嫌山色遠，病是酒杯偏。","蜩響初穿壁，蘭芽半出甎。","堂懸金粟像，門枕御溝泉。","旦沐雖頻握，融帷孰敢褰。","德高羣彥表，善植幾生前。","脩補烏皮几，深藏子敬氈。","扶持千載聖，瀟灑一聲蟬。","棊陣連殘月，僧交似大顛。","常知生似幻，維重直如弦。","餅憶蓴羹美，茶思岳瀑煎。","祗聞溫樹譽，堪鄙竹林賢。","脫穎三千士，馨香四十年。","寬平開義路，淡泞潤清田。","哲后知如子，空王夙有緣。","對歸香滿袖，吟次月當川。","休說慙如揵，堯天即梵天。"]', '["刻形求得相，事事未嘗眠。","霖雨方爲雨，非煙豈是煙。","童收庭樹果，风曳案头牋。","仲虺專爲誥，何充雅愛禪。","静嫌山色远，病是酒杯偏。","蜩响初穿壁，蘭芽半出甎。","堂懸金粟像，门枕御溝泉。","旦沐雖頻握，融帷孰敢褰。","德高羣彥表，善植幾生前。","脩補烏皮几，深藏子敬氈。","扶持千載聖，瀟灑一声蟬。","棊陣連殘月，僧交似大顛。","常知生似幻，維重直如弦。","餅憶蓴羹美，茶思岳瀑煎。","祗闻溫樹譽，堪鄙竹林賢。","脫穎三千士，馨香四十年。","寬平开義路，淡泞潤清田。","哲后知如子，空王夙有緣。","对归香满袖，吟次月當川。","休说慙如揵，堯天即梵天。"]', '诗', 'shi', '', NULL, '和韋相公見示閑臥 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b15546-2895-456b-81eb-459360c705f8', '寄山中伉禪師', '寄山中伉禪師', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["舉世遭心使，吾師獨使心。","萬緣冥目盡，一句不言深。","野火燒禪石，殘霞照栗林。","秋風溪上路，終願一相尋。"]', '["舉世遭心使，吾師独使心。","万緣冥目尽，一句不言深。","野火燒禪石，殘霞照栗林。","秋风溪上路，終願一相尋。"]', '诗', 'shi', '', NULL, '寄山中伉禪師 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b70b6e-b2ee-4df6-b76c-dc99a5043c06', '秋寄栖一', '秋寄栖一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一別一公後，相思時一吁。","眼中瘡校未，般若偈持無。","卷句冰團大，爐煙櫪橛粗。","勸君君記取，不用更他圖。"]', '["一別一公後，相思时一吁。","眼中瘡校未，般若偈持無。","卷句冰團大，爐煙櫪橛粗。","勸君君記取，不用更他圖。"]', '诗', 'shi', '', NULL, '秋寄栖一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b350d17b-8e23-4042-bf63-9f5900f59be1', '懷匡山山長二首 一', '懷匡山山长二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["白石峰之半，先生好在麽。","捲簾當大瀑，常恨不如他。","杉罅龍涎溢，潭㘭石髮多。","吾皇搜草澤，爭奈謝安何。"]', '["白石峰之半，先生好在麽。","捲簾當大瀑，常恨不如他。","杉罅龙涎溢，潭㘭石髮多。","吾皇搜草澤，爭奈謝安何。"]', '诗', 'shi', '', NULL, '懷匡山山長二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baae70d6-9e7c-4062-aec3-1f8731f72c6d', '懷匡山山長二首 二', '懷匡山山长二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說面前峰，尋常醉亦登。","雨餘多菌出，燒甚古崖崩。","覓句曾衝虎，耕田半爲僧。","聞名多歲也，常恨不飛騰。"]', '["见说面前峰，尋常醉亦登。","雨餘多菌出，燒甚古崖崩。","覓句曾衝虎，耕田半爲僧。","闻名多歲也，常恨不飞腾。"]', '诗', 'shi', '', NULL, '懷匡山山長二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519ac77d-8fe5-4c79-ac5c-091cf9b44d65', '懷高真動二首 一', '懷高真动二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["知爾今何處，孤高獨不羣。","論詩唯許我，窮易到無文。","貰酒兒穿雪，尋僧月照雲。","何時再相見，兵寇尚紛紛。"]', '["知爾今何处，孤高独不羣。","論诗唯許我，窮易到無文。","貰酒兒穿雪，尋僧月照云。","何时再相见，兵寇尚紛紛。"]', '诗', 'shi', '', NULL, '懷高真動二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aaa3ebd-bc84-4314-93b4-58bbe8e1d6c8', '懷高真動二首 二', '懷高真动二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["久別無消息，今秋忽得書。","諸孤婚嫁苦，求己世情疎。","亂甚無喬木，溪多不釣魚。","祗應金岳色，如爾復如余。"]', '["久別無消息，今秋忽得书。","諸孤婚嫁苦，求己世情疎。","亂甚無喬木，溪多不釣鱼。","祗應金岳色，如爾复如余。"]', '诗', 'shi', '', NULL, '懷高真動二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98010ad5-bc2c-472a-851b-98f809fc9fcc', '秋末入匡山船行八首 一', '秋末入匡山船行八首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["楚國茱萸月，吳吟梨栗船。","遠遊無定所，高臥是何年。","浪卷紛紛葉，檣衝澹澹煙。","去心還自喜，廬岳倚青天。"]', '["楚国茱萸月，吳吟梨栗船。","远游無定所，高臥是何年。","浪卷紛紛葉，檣衝澹澹煙。","去心還自喜，廬岳倚青天。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23391358-ea11-49ab-abf8-a0a209374a39', '秋末入匡山船行八首 二', '秋末入匡山船行八首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蘆葦深花裏，漁歌一曲長。","人心雖憶越，帆態似浮湘。","石獺銜魚白，汀茅浸浪黃。","等閑千萬里，道在亦無妨。"]', '["蘆葦深花裏，漁歌一曲长。","人心雖憶越，帆態似浮湘。","石獺銜鱼白，汀茅浸浪黄。","等闲千万里，道在亦無妨。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9806351-cd2a-48e7-a159-16e7b7913be8', '秋末入匡山船行八首 三', '秋末入匡山船行八首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["島上離家化，茅茨竹戶開。","黃桑雙鵲喜，白日有誰來。","擔浪澆秋芋，緣灘取淨苔。","回頭深自媿，舊業本蒿萊。"]', '["島上離家化，茅茨竹戶开。","黄桑雙鵲喜，白日有誰来。","擔浪澆秋芋，緣灘取淨苔。","回头深自媿，旧業本蒿萊。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3552e2ed-e071-4302-b7e7-8386a6b19ef5', '秋末入匡山船行八首 四', '秋末入匡山船行八首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["匡阜層層翠，修江疊疊波。","從來未曾到，此去復如何。","水廟寒鴉集，沙村夕照多。","誰如垂釣者，孤作鬢皤皤。"]', '["匡阜層層翠，修江叠叠波。","從来未曾到，此去复如何。","水廟寒鴉集，沙村夕照多。","誰如垂釣者，孤作鬢皤皤。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac838a0f-0402-4cb5-ba7a-d6b0fd752771', '秋末入匡山船行八首 五', '秋末入匡山船行八首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["晚泊蒼茫浦，風微浪亦粗。","估喧如亥合，檣密似林枯。","地峻湖無□，潮寒蚌有珠。","東西無定所，何用問前途。"]', '["晚泊蒼茫浦，风微浪亦粗。","估喧如亥合，檣密似林枯。","地峻湖無□，潮寒蚌有珠。","东西無定所，何用问前途。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db49702e-d89b-414b-b414-f354afee3fc2', '秋末入匡山船行八首 六', '秋末入匡山船行八首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["島香思賈島，江碧憶清江。","囊橐誰相似，饞慵世少雙。","鼉驚入窟月，燒到繫船樁。","謾有歸鄉夢，前頭是楚邦。"]', '["島香思賈島，江碧憶清江。","囊橐誰相似，饞慵世少雙。","鼉驚入窟月，燒到繫船樁。","謾有归乡梦，前头是楚邦。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7bce7a2-640c-4e38-b17c-45b4319ff6e3', '秋末入匡山船行八首 七', '秋末入匡山船行八首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["南北雖無適，東西亦似萍。","霞根生石片，象跡壞沙汀。","莽莽蒹葭赤，微微蜃蛤腥。","因思范蠡輩，未免亦飄零。"]', '["南北雖無適，东西亦似萍。","霞根生石片，象跡壞沙汀。","莽莽蒹葭赤，微微蜃蛤腥。","因思范蠡輩，未免亦飄零。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a79701-1203-4814-8657-c7aa5a0c55b6', '秋末入匡山船行八首 八', '秋末入匡山船行八首 八', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["曉色千檣去，長江八月時。","雨淙山骨出，橰擉岸形卑。","野水畬田黑，荒汀獨鳥癡。","如今是清世，誰道出山遲。"]', '["晓色千檣去，长江八月时。","雨淙山骨出，橰擉岸形卑。","野水畬田黑，荒汀独鸟癡。","如今是清世，誰道出山遲。"]', '诗', 'shi', '', NULL, '秋末入匡山船行八首 八 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed50c044-aa14-4cee-a88e-de5772498fd1', '送僧歸華山', '送僧归华山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["心枯衲亦枯，歸岳揭空盂。","七貴留不住，孤雲出更孤。","燒灰猶湯足，雪片似黏鬚。","他日如相覓，還應道到吳。"]', '["心枯衲亦枯，归岳揭空盂。","七貴留不住，孤云出更孤。","燒灰猶湯足，雪片似黏鬚。","他日如相覓，還應道到吳。"]', '诗', 'shi', '', NULL, '送僧歸華山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0b0e46-8b1f-4557-b7bd-1ce97285f332', '送友人之嶺外', '送友人之嶺外', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["五嶺難爲客，君遊早晚回。","一囊秋課苦，萬里瘴雲開。","金柱根應動，風雷舶欲來。","明時好□進，莫滯長卿才。"]', '["五嶺难爲客，君游早晚回。","一囊秋課苦，万里瘴云开。","金柱根應动，风雷舶欲来。","明时好□進，莫滯长卿才。"]', '诗', 'shi', '', NULL, '送友人之嶺外 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a39823b3-e3f9-4bde-8e3b-ff85d3203d98', '送盧舍人朝覲', '送盧舍人朝覲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["羶行無爲日，垂衣帝道亨。","聖真千載聖，明必萬年明。","重德須朝覲，流年不可輕。","洪才傳出世，清甲得高名。","罕玉藏無映，嵇松畫不成。","起銜軒后勅，醉別亞夫營。","燒闊荆州熟，霞新峴首晴。","重重堯雨露，去去漢公卿。","白髮應從白，清貧但更清。","夢緣丹陛險，春傍綵衣生。","既握鍾繇筆，須調傅說羹。","倘因星使出，一望問支鏗。"]', '["羶行無爲日，垂衣帝道亨。","聖真千載聖，明必万年明。","重德須朝覲，流年不可轻。","洪才傳出世，清甲得高名。","罕玉藏無映，嵇松畫不成。","起銜軒后勅，醉別亞夫營。","燒闊荆州熟，霞新峴首晴。","重重堯雨露，去去漢公卿。","白髮應從白，清貧但更清。","梦緣丹陛險，春傍綵衣生。","既握鍾繇笔，須調傅说羹。","倘因星使出，一望问支鏗。"]', '诗', 'shi', '', NULL, '送盧舍人朝覲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc61a33f-cf3a-4ad6-9d4f-8f5bb083cf6d', '上馮使君山水障子', '上馮使君山水障子', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["憶山歸未得，畫出亦堪憐。","崩岸全隳路，荒村半有煙。","筆句岡勢轉，墨搶燒痕顛。","遠浦深通海，孤峰冷倚天。","柴棚坐逸士，露茗煮紅泉。","繡與蓮峰競，威如劒閣牽。","石門關麈鹿，氣候有神仙。","茅屋書窗小，苔堦滴瀑圓。","松根擊石朽，桂葉蝕霜鮮。","畫出欺王墨，擎將獻惠連。","新詩寧妄說，舊隱實如然。","願似窗中列，時聞大雅篇。"]', '["憶山归未得，畫出亦堪怜。","崩岸全隳路，荒村半有煙。","笔句岡勢轉，墨搶燒痕顛。","远浦深通海，孤峰冷倚天。","柴棚坐逸士，露茗煮紅泉。","繡與蓮峰競，威如劒閣牽。","石门关麈鹿，氣候有神仙。","茅屋书窗小，苔堦滴瀑圓。","松根擊石朽，桂葉蝕霜鲜。","畫出欺王墨，擎將獻惠連。","新诗寧妄说，旧隐實如然。","願似窗中列，时闻大雅篇。"]', '诗', 'shi', '', NULL, '上馮使君山水障子 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a74210-3717-4c21-9671-5e2184e494c6', '送令狐煥赴闕', '送令狐煥赴闕', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["渚宮遙落日，相送碧江湄。","陟也須爲相，天乎更贊誰。","風高檣力出，霞熱鳥行遲。","此去多來客，無忘慰所思。"]', '["渚宮遙落日，相送碧江湄。","陟也須爲相，天乎更贊誰。","风高檣力出，霞熱鸟行遲。","此去多来客，無忘慰所思。"]', '诗', 'shi', '', NULL, '送令狐煥赴闕 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a637488-2e87-493c-a1e4-ddd736108bd1', '送吳融員外赴闕', '送吳融員外赴闕', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["漢文思賈傅，賈傅遂生還。","今日又如此，送君非等閑。","雲寒猶惜雪，燒猛似烹山。","應笑無機者，騰騰天地間。"]', '["漢文思賈傅，賈傅遂生還。","今日又如此，送君非等闲。","云寒猶惜雪，燒猛似烹山。","應笑無機者，腾腾天地间。"]', '诗', 'shi', '', NULL, '送吳融員外赴闕 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76674fe-695e-4691-8155-2c5712e5405b', '送姚洎拾遺自江陵幕赴京', '送姚洎拾遺自江陵幕赴京', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["捧詔動征輪，分飛楚水濱。","由來真廟器，多作伏蒲人。","捨魯知非願，朝天不話貧。","沙頭千騎送，島上一蟬新。","莫使身侵貴，無矜貴逼身。","玉階凝正色，蘭苑漲芳塵。","鑾輅方離華，車書漸似秦。","流年飄儵忽，書札莫因循。","涼雨鳴紅葉，非煙閉紫宸。","憑將西社意，一說向荀陳。"]', '["捧詔动征輪，分飞楚水濱。","由来真廟器，多作伏蒲人。","捨魯知非願，朝天不話貧。","沙头千騎送，島上一蟬新。","莫使身侵貴，無矜貴逼身。","玉階凝正色，蘭苑漲芳塵。","鑾輅方離华，车书漸似秦。","流年飄儵忽，书札莫因循。","涼雨鳴紅葉，非煙閉紫宸。","憑將西社意，一说向荀陳。"]', '诗', 'shi', '', NULL, '送姚洎拾遺自江陵幕赴京 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19061181-fe35-49d8-b79b-c76b545d4936', '送僧人入石霜', '送僧人入石霜', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["舉世祗堪吁，空知與道俱。","論心齊至聖，對鏡破凡夫。","業王如雲合，頭低似箭驅。","三清徒妄想，千載亦須臾。","唯我流陽叟，深雲領毳徒。","盡騎香白象，皆握月明珠。","寂寞排松榻，斕斑半雪鬚。","苔侵長者論，嵐蝕祖師圖。","翠巘金鐘曉，香林寶月孤。","兟兟齊白趾，赫赫共洪爐。","山色鋤難盡，松根踏欲無。","難評傳的的，須到不區區。","撩舍新羅瘦，爐煙榾柮粗。","燒畬平虎窟，分瀑入香廚。","師去情何切，人間事莫拘。","穿林宿古冢，踏葉揭空盂。","無事終無事，令枯便合枯他年相覓在，亦不是生蘇。"]', '["舉世祗堪吁，空知與道俱。","論心齊至聖，对镜破凡夫。","業王如云合，头低似箭驱。","三清徒妄想，千載亦須臾。","唯我流陽叟，深云領毳徒。","尽騎香白象，皆握月明珠。","寂寞排松榻，斕斑半雪鬚。","苔侵长者論，嵐蝕祖師圖。","翠巘金鐘晓，香林寶月孤。","兟兟齊白趾，赫赫共洪爐。","山色鋤难尽，松根踏欲無。","难評傳的的，須到不區區。","撩舍新羅瘦，爐煙榾柮粗。","燒畬平虎窟，分瀑入香廚。","師去情何切，人间事莫拘。","穿林宿古冢，踏葉揭空盂。","無事終無事，令枯便合枯他年相覓在，亦不是生蘇。"]', '诗', 'shi', '', NULL, '送僧人入石霜 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52cc3857-5a5a-48f6-ae74-643bcdf26fe1', '送僧歸南康', '送僧归南康', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["殼殼學得律，還鄉見苦情。","遠思芳草盛，不入楚山行。","帆入汀煙健，經吟戍月清。","到鄉同學輩，應到贛江迎。"]', '["殼殼学得律，還乡见苦情。","远思芳草盛，不入楚山行。","帆入汀煙健，經吟戍月清。","到乡同学輩，應到贛江迎。"]', '诗', 'shi', '', NULL, '送僧歸南康 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('549bc28c-406c-4398-a205-e2b12036405b', '送陳秀才赴舉兼寄韓舍人', '送陳秀才赴舉兼寄韓舍人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["主聖臣賢日，求名莫等閑。","直須詩似玉，不用力如山。","草白兵初息，年豐駕已還。","憑將安養意，一說向曾顏。"]', '["主聖臣賢日，求名莫等闲。","直須诗似玉，不用力如山。","草白兵初息，年豐駕已還。","憑將安養意，一说向曾顏。"]', '诗', 'shi', '', NULL, '送陳秀才赴舉兼寄韓舍人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6472c949-4888-4320-9fb5-958fc3d5d01b', '送友人及第後歸台州', '送友人及第後归台州', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["得桂爲邊辟，翩翩頗合宜。","嫖姚留不住，晝錦已歸遲。","島側花藏虎，湖心浪撼棊。","終期華頂下，共禮淥身師。"]', '["得桂爲邊辟，翩翩頗合宜。","嫖姚留不住，晝錦已归遲。","島側花藏虎，湖心浪撼棊。","終期华頂下，共禮淥身師。"]', '诗', 'shi', '', NULL, '送友人及第後歸台州 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('014cd916-3921-4e8c-b8dc-2f4e6cb6079c', '晚春寄張侍郎', '晚春寄張侍郎', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["遐想涪陵岸，山花半已殘。","人心何以遣，天步正艱難。","鳥聽黃袍小，城臨白帝寒。","應知窗下夢，日日到江干。"]', '["遐想涪陵岸，山花半已殘。","人心何以遣，天步正艱难。","鸟听黄袍小，城臨白帝寒。","應知窗下梦，日日到江干。"]', '诗', 'shi', '', NULL, '晚春寄張侍郎 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2fe4c1-3983-49b0-845f-55daed7373e1', '寄景判官兼思州葉使君', '寄景判官兼思州葉使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["獨住西峰半，尋常欲下難。","石多桐屐齾，香甚藥花乾。","荏苒新鶯老，窮通亦自寬。","髯參與短簿，始爲一吟看。"]', '["独住西峰半，尋常欲下难。","石多桐屐齾，香甚藥花乾。","荏苒新鶯老，窮通亦自寬。","髯參與短簿，始爲一吟看。"]', '诗', 'shi', '', NULL, '寄景判官兼思州葉使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2101a4d-5354-48a5-8ac8-9af19521caff', '送盧秀才應舉', '送盧秀才應舉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["幾載阻兵荒，一名終不忘。","還衝猛風雪，如畫冷朝陽。","句好慵將出，囊空却不忙。","明年公道日，去去必穿楊。"]', '["幾載阻兵荒，一名終不忘。","還衝猛风雪，如畫冷朝陽。","句好慵將出，囊空却不忙。","明年公道日，去去必穿楊。"]', '诗', 'shi', '', NULL, '送盧秀才應舉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebe9157b-aa85-4210-b319-51c686e3c00f', '聞新蟬寄桂雍', '闻新蟬寄桂雍', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["新蟬終夜呌，嘒嘒隔溪濆。","杜宇仍相雜，故人聞不聞。","捲簾花動月，冥目砌生雲。","終共謝時去，西山鸞鶴羣。"]', '["新蟬終夜呌，嘒嘒隔溪濆。","杜宇仍相杂，故人闻不闻。","捲簾花动月，冥目砌生云。","終共謝时去，西山鸾鹤羣。"]', '诗', 'shi', '', NULL, '聞新蟬寄桂雍 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb9130e8-b244-43a3-9033-39b7a9b55ad6', '寄懷楚和尚二首 一', '寄懷楚和尚二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["吾師師子兒，而復貌瓌奇。","何得文明代，不爲王者師。","鐵盂湯雪早，石炭煮茶遲。","謾有參尋意，因循到亂時。"]', '["吾師師子兒，而复貌瓌奇。","何得文明代，不爲王者師。","鐵盂湯雪早，石炭煮茶遲。","謾有參尋意，因循到亂时。"]', '诗', 'shi', '', NULL, '寄懷楚和尚二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0c9d29-c64d-4afe-938d-3f0140e7c606', '寄懷楚和尚二首 二', '寄懷楚和尚二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["跳躑諸峰險，回翔萬里空。","爭將金鎖鎖，那把玉籠籠。","印缺香崩火，窗疎蝎喫風。","永懷今已矣，吟坐雪濛濛。"]', '["跳躑諸峰險，回翔万里空。","爭將金鎖鎖，那把玉籠籠。","印缺香崩火，窗疎蝎喫风。","永懷今已矣，吟坐雪濛濛。"]', '诗', 'shi', '', NULL, '寄懷楚和尚二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42388f80-e8cb-49c8-a042-7e60afbf8fe3', '和韋相公話婺州陳事', '和韋相公話婺州陳事', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昔事堪惆悵，談玄愛白牛。","千場花下醉，一片夢中遊。","耕避初平石，燒殘沈約樓。","無因更重到，且副濟川舟。"]', '["昔事堪惆悵，談玄愛白牛。","千場花下醉，一片梦中游。","耕避初平石，燒殘沈約楼。","無因更重到，且副濟川舟。"]', '诗', 'shi', '', NULL, '和韋相公話婺州陳事 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a56c12-67ee-469c-89bb-1dfdbddaec70', '遇五天僧入五臺五首 一', '遇五天僧入五台五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["十萬里到此，辛勤詎可論。","唯云吾上祖，見買給孤園。","一月行沙磧，三更到鐵門。","白頭鄉思在，迴首一銷魂。"]', '["十万里到此，辛勤詎可論。","唯云吾上祖，见買給孤园。","一月行沙磧，三更到鐵门。","白头乡思在，迴首一銷魂。"]', '诗', 'shi', '', NULL, '遇五天僧入五臺五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f008b2-1cd4-464b-ae9a-9e2ea4c67c32', '遇五天僧入五臺五首 二', '遇五天僧入五台五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雪嶺頂危坐，乾坤四顧低。","河橫于闐北，日落月支西。","水石香多白，猨猱老不啼。","空餘忍辱草，相對色萋萋。"]', '["雪嶺頂危坐，乾坤四顧低。","河橫于闐北，日落月支西。","水石香多白，猨猱老不啼。","空餘忍辱草，相对色萋萋。"]', '诗', 'shi', '', NULL, '遇五天僧入五臺五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9105eaa-3461-4932-9137-c3f66fdd5d54', '遇五天僧入五臺五首 三', '遇五天僧入五台五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["遠禮清涼寺，尋真似善才。","身心無所得，日月不將來。","白疊還圖象，滄溟亦汎杯。","唐人亦何幸，處處覺花開。"]', '["远禮清涼寺，尋真似善才。","身心無所得，日月不將来。","白叠還圖象，滄溟亦汎杯。","唐人亦何幸，处处覺花开。"]', '诗', 'shi', '', NULL, '遇五天僧入五臺五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0808fe0f-f916-434e-9374-12d7e32e73ac', '遇五天僧入五臺五首 四', '遇五天僧入五台五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["塗足油應盡，乾陀帔半隳。","辟支迦狀貌，剎利帝家兒。","結印魔應哭，遊心聖不知。","深嗟頭已白，不得遠相隨。"]', '["塗足油應尽，乾陀帔半隳。","辟支迦狀貌，剎利帝家兒。","結印魔應哭，游心聖不知。","深嗟头已白，不得远相隨。"]', '诗', 'shi', '', NULL, '遇五天僧入五臺五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c989e9a7-0805-417c-96af-c548044a37fe', '遇五天僧入五臺五首 五', '遇五天僧入五台五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["送迎經幾國，多化帝王心。","電激青蓮目，環垂紫磨金。","眉根霜入細，梵夾蠹難侵。","必似陀波利，他年不可尋。"]', '["送迎經幾国，多化帝王心。","電激青蓮目，环垂紫磨金。","眉根霜入細，梵夾蠹难侵。","必似陀波利，他年不可尋。"]', '诗', 'shi', '', NULL, '遇五天僧入五臺五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b68d61-57ca-4beb-894d-f66a8c00e276', '經普化禪師影院', '經普化禪師影院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["大一今何處，登堂似昔時。","曾蒙金印印，得異野干兒。","影束龍神在，門荒桐竹衰。","誰云續僧史，別位著吾師。"]', '["大一今何处，登堂似昔时。","曾蒙金印印，得異野干兒。","影束龙神在，门荒桐竹衰。","誰云續僧史，別位著吾師。"]', '诗', 'shi', '', NULL, '經普化禪師影院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b52e4a-b40b-46db-914f-75d6d757ceb5', '秋寄李頻使君二首 一', '秋寄李頻使君二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["爲郎須塞詔，當路亦驅驅。","貴不因人得，清還似句無。","燒煙連野白，山藥拶階枯。","想得徵黃詔，如今已在途。"]', '["爲郎須塞詔，當路亦驱驱。","貴不因人得，清還似句無。","燒煙連野白，山藥拶階枯。","想得徵黄詔，如今已在途。"]', '诗', 'shi', '', NULL, '秋寄李頻使君二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385e6970-ac1e-4aac-89a9-3d31c49b981a', '秋寄李頻使君二首 二', '秋寄李頻使君二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["務簡趣難陪，清吟共綠苔。","葉和秋蟻落，僧帶野香來。","留客朝嘗酒，憂民夜畫灰。","終期冒風雪，江上見宗雷。"]', '["務簡趣难陪，清吟共綠苔。","葉和秋蟻落，僧带野香来。","留客朝嘗酒，憂民夜畫灰。","終期冒风雪，江上见宗雷。"]', '诗', 'shi', '', NULL, '秋寄李頻使君二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6791481-45a7-4c10-a119-22c2963708f1', '上東林和尚', '上东林和尚', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["讓紫歸青壁，高名四海聞。","雖然無一事，得不是要君。","道祗傳伊字，詩多笑碧雲。","應憐門下客，餘力亦爲文。"]', '["讓紫归青壁，高名四海闻。","雖然無一事，得不是要君。","道祗傳伊字，诗多笑碧云。","應怜门下客，餘力亦爲文。"]', '诗', 'shi', '', NULL, '上東林和尚 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60762fd-8b7e-41fb-922c-c1e2bc5e70f9', '江邊道士', '江邊道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["獨住大江濱，不知何代人。","藥罏生紫氣，肌肉似紅銀。","酒釅竹屋[爛]，符收山鬼仁。","何妨將我去，一看武陵春。"]', '["独住大江濱，不知何代人。","藥罏生紫氣，肌肉似紅銀。","酒釅竹屋[爛]，符收山鬼仁。","何妨將我去，一看武陵春。"]', '诗', 'shi', '', NULL, '江邊道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e484cc34-6bcd-463b-ae30-f8415b448932', '送僧之湖外', '送僧之湖外', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["去旨趣非常，春風爾莫狂。","惟擎一鐵鉢，舊亦講金剛。","午飯孤煙裏，宵禪大石旁。","羨師終不及，湘浪淥茫茫。"]', '["去旨趣非常，春风爾莫狂。","惟擎一鐵鉢，旧亦講金剛。","午飯孤煙裏，宵禪大石旁。","羨師終不及，湘浪淥茫茫。"]', '诗', 'shi', '', NULL, '送僧之湖外 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2003d1a4-829a-4952-904d-72b1ed0d7e58', '懷謬獨一', '懷謬独一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶蘭陵子，瓌奇皴渴才。","思還如我苦，時不爲伊來。","岳霞猱擲雪，湖月浪翻杯。","未聞霑寸祿，此事亦堪哀。"]', '["常憶蘭陵子，瓌奇皴渴才。","思還如我苦，时不爲伊来。","岳霞猱擲雪，湖月浪翻杯。","未闻霑寸祿，此事亦堪哀。"]', '诗', 'shi', '', NULL, '懷謬獨一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba94546-a2d9-425d-b4a5-6468bb951fe5', '送廬山衲僧', '送廬山衲僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["飛錫下崆㟅，清高世少雙。","凍天方篩雪，別我去何邦。","燒繞赤烏亥，雲漫白蚌江。","路人爭得識，空仰鬢眉[龐]。"]', '["飞錫下崆㟅，清高世少雙。","凍天方篩雪，別我去何邦。","燒繞赤烏亥，云漫白蚌江。","路人爭得識，空仰鬢眉[龐]。"]', '诗', 'shi', '', NULL, '送廬山衲僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d6e480-90d2-4c24-a800-0192028a812e', '寄西山胡汾吳樵', '寄西山胡汾吳樵', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["帶經鋤隴者，何止手胼胝。","覓句句句好，慙予筋力衰。","雲塠臨案冷，鹿隊過門遲。","相憶空回首，江頭日暮時。"]', '["带經鋤隴者，何止手胼胝。","覓句句句好，慙予筋力衰。","云塠臨案冷，鹿隊過门遲。","相憶空回首，江头日暮时。"]', '诗', 'shi', '', NULL, '寄西山胡汾吳樵 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f90985a-7b30-4196-85a7-d3da41c8d351', '休糧僧', '休糧僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不食更何憂，自由中自由。","身輕嫌衲重，天旱爲民愁。","應器誰將去，生臺蟻不遊。","會須傳此術，相共老山丘。"]', '["不食更何憂，自由中自由。","身轻嫌衲重，天旱爲民愁。","應器誰將去，生台蟻不游。","會須傳此術，相共老山丘。"]', '诗', 'shi', '', NULL, '休糧僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08aa7e3f-58d0-45a0-9002-eb138c62d0c5', '送杜使君朝覲', '送杜使君朝覲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["借寇借不得，清聲徹帝聰。","坐來千里泰，歸去一囊空。","遺愛封疆熟，扳轅草木同。","路遙山不少，江靜思無窮。","花舸衝煙濕，朱衣照浪紅。","援毫兩岸曉，欹枕滿旗風。","道罕將人合，心難與聖通。","從茲林下客，應□代天功。"]', '["借寇借不得，清声徹帝聰。","坐来千里泰，归去一囊空。","遺愛封疆熟，扳轅草木同。","路遙山不少，江静思無窮。","花舸衝煙濕，朱衣照浪紅。","援毫兩岸晓，欹枕满旗风。","道罕將人合，心难與聖通。","從茲林下客，應□代天功。"]', '诗', 'shi', '', NULL, '送杜使君朝覲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c9b064-44ca-457e-b31d-3ab1197a5354', '送人之嶺外', '送人之嶺外', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說還南去，迢迢有侶無。","時危須早轉，親老莫他圖。","小店虵羹黑，空山象糞枯。","三閭遺廟在，爲我一鳴呼。"]', '["见说還南去，迢迢有侶無。","时危須早轉，親老莫他圖。","小店虵羹黑，空山象糞枯。","三閭遺廟在，爲我一鳴呼。"]', '诗', 'shi', '', NULL, '送人之嶺外 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c23b5ff-e9d9-4a9a-9b3e-f0da181099da', '題弘式和尚院兼呈杜使君', '題弘式和尚院兼呈杜使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["二雅兼二密，愔愔祗自怡。","臘高雲屐朽，貌古畫師疑。","壍蟻緣金錫，罏煙惹雪眉。","仍聞有新作，祗是寄相思。"]', '["二雅兼二密，愔愔祗自怡。","臘高云屐朽，貌古畫師疑。","壍蟻緣金錫，罏煙惹雪眉。","仍闻有新作，祗是寄相思。"]', '诗', 'shi', '', NULL, '題弘式和尚院兼呈杜使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fadf4f2d-bd6b-430a-8b9b-1640ef60fa26', '湖頭別墅三首 一', '湖头別墅三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["梨栗鳥啾啾，高歌若自由。","人誰知此意，舊業在湖頭。","飢鼠掀菱殻，新蟬避栗皺。","不知江海上，戈甲幾時休。"]', '["梨栗鸟啾啾，高歌若自由。","人誰知此意，旧業在湖头。","飢鼠掀菱殻，新蟬避栗皺。","不知江海上，戈甲幾时休。"]', '诗', 'shi', '', NULL, '湖頭別墅三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501c51d6-24d7-40dc-a8a7-ab633840e336', '湖頭別墅三首 二', '湖头別墅三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["桑柘參桐竹，陰陰一徑苔。","更無他事出，祗有衲僧來。","壍蟻爭生食，窗經卷燒灰。","可憐門外路，日日起塵埃。"]', '["桑柘參桐竹，陰陰一徑苔。","更無他事出，祗有衲僧来。","壍蟻爭生食，窗經卷燒灰。","可怜门外路，日日起塵埃。"]', '诗', 'shi', '', NULL, '湖頭別墅三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e2d254-3069-4354-a543-e5b00f8ca82b', '湖頭別墅三首 三', '湖头別墅三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["南北如仙境，東西似畫圖。","園飛青啄木，簷挂白蜘蛛。","鄰叟教修廢，牛童與納租。","寄言來往客，不用問榮枯。"]', '["南北如仙境，东西似畫圖。","园飞青啄木，簷挂白蜘蛛。","鄰叟教修廢，牛童與納租。","寄言来往客，不用问榮枯。"]', '诗', 'shi', '', NULL, '湖頭別墅三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c88819f-1fce-4552-837d-8cdb25f47c80', '三峽聞猨', '三峽闻猨', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["歷歷數聲猨，寥寥渡白煙。","應栖多月樹，況是下霜天。","萬里客危坐，千山境悄然。","更深仍不住，使我欲移船。"]', '["歷歷數声猨，寥寥渡白煙。","應栖多月樹，況是下霜天。","万里客危坐，千山境悄然。","更深仍不住，使我欲移船。"]', '诗', 'shi', '', NULL, '三峽聞猨 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f96160-fe72-45d8-89a6-4a5cb058eb86', '聞知聞赴成都辟請', '闻知闻赴成都辟請', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["文翁還化蜀，帟幕列鵷鸞。","飲水臨人易，燒山覓士難。","錦機花正合，椶蕈火初乾。","知己相思否，如何借羽翰。"]', '["文翁還化蜀，帟幕列鵷鸾。","饮水臨人易，燒山覓士难。","錦機花正合，椶蕈火初乾。","知己相思否，如何借羽翰。"]', '诗', 'shi', '', NULL, '聞知聞赴成都辟請 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1bdf665-ca76-48fc-a04c-39b87dcba3c1', '題淮南惠照寺律師院', '題淮南惠照寺律師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["儀冠凝寒玉，端居似沃州。","學徒梧有鳳，律藏目無牛。","茗滑香黏齒，鐘清雪滴樓。","還須結西社，來往悉諸侯。"]', '["儀冠凝寒玉，端居似沃州。","学徒梧有鳳，律藏目無牛。","茗滑香黏齒，鐘清雪滴楼。","還須結西社，来往悉諸侯。"]', '诗', 'shi', '', NULL, '題淮南惠照寺律師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ab7baf-95ea-4e7f-8058-f66e84bcef28', '秋末長興寺作', '秋末长兴寺作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["荒寺古江濱，莓苔地絕塵。","長廊飛亂葉，寒雨更無人。","栗不和皺落，僧多到骨貧。","行行行未得，孤坐更誰親。"]', '["荒寺古江濱，莓苔地絕塵。","长廊飞亂葉，寒雨更無人。","栗不和皺落，僧多到骨貧。","行行行未得，孤坐更誰親。"]', '诗', 'shi', '', NULL, '秋末長興寺作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1a116f-fae6-4ba5-83ed-19b06b28e4c2', '寄杭州靈隱寺宋震使君', '寄杭州靈隐寺宋震使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["罷郡歸侵夏，仍聞靈隱居。","僧房謝朓語，寺額葛洪書。","月樹獮猴睡，山池菡萏疎。","吾皇愛清靜，莫便結吾廬。"]', '["罷郡归侵夏，仍闻靈隐居。","僧房謝朓語，寺額葛洪书。","月樹獮猴睡，山池菡萏疎。","吾皇愛清静，莫便結吾廬。"]', '诗', 'shi', '', NULL, '寄杭州靈隱寺宋震使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b92e14-b8e7-450c-b2ad-6dc1eb640c6e', '送人歸夏口', '送人归夏口', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鴈鴈葉紛紛，行人豈易聞。","千山與萬水，何處更逢君？","貌不長如玉，人生祗似雲。","倘經三祖寺，一爲禮龕墳。"]', '["鴈鴈葉紛紛，行人豈易闻。","千山與万水，何处更逢君？","貌不长如玉，人生祗似云。","倘經三祖寺，一爲禮龕墳。"]', '诗', 'shi', '', NULL, '送人歸夏口 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb81fe79-0e09-4ff1-863e-f7a3fa6ee49c', '送新羅僧歸本國', '送新羅僧归本国', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["忘身求至教，求得却東歸。","離岸乘空去，終年無所依。","月衝陰火出，帆拶大鵬飛。","想得還鄉後，多應著紫衣。"]', '["忘身求至教，求得却东归。","離岸乘空去，終年無所依。","月衝陰火出，帆拶大鵬飞。","想得還乡後，多應著紫衣。"]', '诗', 'shi', '', NULL, '送新羅僧歸本國 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ba76ba7-23d1-4762-a9f7-2050c3a228da', '避寇入銀山', '避寇入銀山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["草草穿銀峽，崎嶇路未諳。","傍山爲店戍，永日繞溪潭。","燒地生芚蕨，人家煮僞蠶。","翻如歸舊隱，步步入煙嵐。"]', '["草草穿銀峽，崎嶇路未諳。","傍山爲店戍，永日繞溪潭。","燒地生芚蕨，人家煮僞蠶。","翻如归旧隐，步步入煙嵐。"]', '诗', 'shi', '', NULL, '避寇入銀山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37bc4a26-3b08-424c-9267-a4615ff8ef97', '聞友人駕前及第', '闻友人駕前及第', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見心知命好，一別隔煙波。","世亂無全士，君方掇大科。","早隨鑾輅轉，莫戀蜀山多。","必貢安時策，忠言奈爾何。"]', '["见心知命好，一別隔煙波。","世亂無全士，君方掇大科。","早隨鑾輅轉，莫戀蜀山多。","必貢安时策，忠言奈爾何。"]', '诗', 'shi', '', NULL, '聞友人駕前及第 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480e4f20-0fd6-4a06-97bf-2b5d4bd7b2f3', '避地毘陵上王慥使君', '避地毘陵上王慥使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["至理至昭昭，心通即不遙。","聖威無遠近，吾道太孤標。","辛苦蘇氓俗，端貞荅盛朝。","氣高吞海岳，貧甚似漁樵。","庾亮風流澹，劉寬政事超。","清須遭貴遇，隱已被誰招。","栗塢修禪寺，仙香寄石橋。","風雷巡稼穡，魚鳥合歌謠。","視事私終殺，憂民態亦彫。","道高無不及，恩甚固難消。","大寇山難隔，孤城數合燒。","烽煙終日起，湯沐用心燋。","勇義排千陣，誅鋤擬一朝。","誓盟違日月，旌斾過寒潮。","古驛江雲入，荒宮海雨飄。","仙松添瘦碧，天驥減豐臕。","似在陳兼衛，終爲宋與姚。","已觀雲似鹿，即報首皆梟。","盡願迴清鏡，重希在此條。","應憐千萬戶，禱祝向唐堯。"]', '["至理至昭昭，心通即不遙。","聖威無远近，吾道太孤標。","辛苦蘇氓俗，端貞荅盛朝。","氣高吞海岳，貧甚似漁樵。","庾亮风流澹，劉寬政事超。","清須遭貴遇，隐已被誰招。","栗塢修禪寺，仙香寄石橋。","风雷巡稼穡，鱼鸟合歌謠。","視事私終殺，憂民態亦彫。","道高無不及，恩甚固难消。","大寇山难隔，孤城數合燒。","烽煙終日起，湯沐用心燋。","勇義排千陣，誅鋤擬一朝。","誓盟違日月，旌斾過寒潮。","古驛江云入，荒宮海雨飄。","仙松添瘦碧，天驥減豐臕。","似在陳兼衛，終爲宋與姚。","已观云似鹿，即報首皆梟。","尽願迴清镜，重希在此條。","應怜千万戶，禱祝向唐堯。"]', '诗', 'shi', '', NULL, '避地毘陵上王慥使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f3543a-d635-47bd-b91b-692e092c5b64', '送崔尚書朝覲', '送崔尚书朝覲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["至理契穹旻，方生甫與申。","一麾歌政正，三相賀仁人。","叵似盧懷慎，全如邵信臣。","澄渟消宿蠹，煦愛劇陽春。","對客煙花拆，焚香渥澤新。","徵黃還有自，挽鄧住無因。","峽水全輸潔，巫娥却訝神。","宋均顏未老，劉寵骨應貧。","大醉辭王翦，含香望紫宸。","三峰初有雪，萬里正無塵。","伊昔林中社，多招席上珍。","終期仙掌下，香火一相親。"]', '["至理契穹旻，方生甫與申。","一麾歌政正，三相賀仁人。","叵似盧懷慎，全如邵信臣。","澄渟消宿蠹，煦愛劇陽春。","对客煙花拆，焚香渥澤新。","徵黄還有自，挽鄧住無因。","峽水全輸潔，巫娥却訝神。","宋均顏未老，劉寵骨應貧。","大醉辞王翦，含香望紫宸。","三峰初有雪，万里正無塵。","伊昔林中社，多招席上珍。","終期仙掌下，香火一相親。"]', '诗', 'shi', '', NULL, '送崔尚書朝覲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8602c2-0ace-4c49-a762-6de52f3353a0', '寒夜有懷同志', '寒夜有懷同志', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["永夜殊不寐，懷君正寂寥。","疎鐘寒徧郭，微雪靜鳴條。","南省鴈孤下，西林鶴屢招。","終當謝時去，與子住山椒。"]', '["永夜殊不寐，懷君正寂寥。","疎鐘寒徧郭，微雪静鳴條。","南省鴈孤下，西林鹤屢招。","終當謝时去，與子住山椒。"]', '诗', 'shi', '', NULL, '寒夜有懷同志 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac5f2fa-46a7-4b33-bd8b-13100b40e885', '寄新定桂雍', '寄新定桂雍', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["獨自住烏龍，應憐是衲僧。","句須人未道，君此事偏能。","塢濕雲埋觀，溪寒月照罾。","相思不可見，江上立騰騰。"]', '["独自住烏龙，應怜是衲僧。","句須人未道，君此事偏能。","塢濕云埋观，溪寒月照罾。","相思不可见，江上立腾腾。"]', '诗', 'shi', '', NULL, '寄新定桂雍 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad0983d-f474-4449-b5f0-e461259a328c', '贈靈鷲山道潤禪師院', '贈靈鷲山道潤禪師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常恨煙波隔，聞名二十年。","結爲清氣引，來到法堂前。","薪拾紛紛葉，茶烹滴滴泉。","莫嫌來又去，天道本泠然。"]', '["常恨煙波隔，闻名二十年。","結爲清氣引，来到法堂前。","薪拾紛紛葉，茶烹滴滴泉。","莫嫌来又去，天道本泠然。"]', '诗', 'shi', '', NULL, '贈靈鷲山道潤禪師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c33be971-5cf6-4bed-bf73-7901c46f32fb', '干霄亭晚望懷王棨侍郎', '干霄亭晚望懷王棨侍郎', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["霜打汀島赤，孤煙生池塘。","清吟倚大樹，瑤草何馨香。","久別青雲士，常思白石房。","誰能共歸去，流水似鳴璫。"]', '["霜打汀島赤，孤煙生池塘。","清吟倚大樹，瑤草何馨香。","久別青云士，常思白石房。","誰能共归去，流水似鳴璫。"]', '诗', 'shi', '', NULL, '干霄亭晚望懷王棨侍郎 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25318673-4aef-42c4-89d9-7aed97ab6781', '海邊見羅鄴', '海邊见羅鄴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清世詩聲出，誰人得似君。","命通須有日，天未喪斯文。","楚木寒連寺，修江碧入雲。","相思喜相見，庭葉正紛紛。"]', '["清世诗声出，誰人得似君。","命通須有日，天未喪斯文。","楚木寒連寺，修江碧入云。","相思喜相见，庭葉正紛紛。"]', '诗', 'shi', '', NULL, '海邊見羅鄴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ddf9ef4-0fcd-47b0-87ae-045488e02c88', '送僧之東都', '送僧之东都', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["之子之東洛，囊中有偈新。","紅塵誰不入，獨鶴自難親。","定鼎門連岳，黃河凍過春。","憑師將遠意，說似社中人。"]', '["之子之东洛，囊中有偈新。","紅塵誰不入，独鹤自难親。","定鼎门連岳，黄河凍過春。","憑師將远意，说似社中人。"]', '诗', 'shi', '', NULL, '送僧之東都 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a02462-e7d8-40d1-a13a-b1c674e72353', '送于兢補闕赴京', '送于兢補闕赴京', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["亂離吾道在，不覺到清時。","得句下雪岳，送君登玉墀。","冷驚蟬韻斷，涼觸火雲隳。","倘遇南來使，無忘問所之。"]', '["亂離吾道在，不覺到清时。","得句下雪岳，送君登玉墀。","冷驚蟬韻斷，涼觸火云隳。","倘遇南来使，無忘问所之。"]', '诗', 'shi', '', NULL, '送于兢補闕赴京 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6649508-3b80-4317-8d12-524ab291beab', '送鄭準赴舉', '送鄭準赴舉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["兩河兵火後，西笑見吾曹。","海靜三山出，天空一鶚高。","賃居槐拶屋，行卷雪埋袍。","他日如相覓，栽桃近海濤。"]', '["兩河兵火後，西笑见吾曹。","海静三山出，天空一鶚高。","賃居槐拶屋，行卷雪埋袍。","他日如相覓，栽桃近海濤。"]', '诗', 'shi', '', NULL, '送鄭準赴舉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b1c5b3-00a4-4bde-81ab-0c181431baff', '寄拄杖上王使君', '寄拄杖上王使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["拄杖鄰僧與，殊常不可名。","一條黳玉重，百兩紫金輕。","有乳盤春力，無心合道情。","惟宜高處著，將寄謝宣城。"]', '["拄杖鄰僧與，殊常不可名。","一條黳玉重，百兩紫金轻。","有乳盤春力，無心合道情。","惟宜高处著，將寄謝宣城。"]', '诗', 'shi', '', NULL, '寄拄杖上王使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aee28e7-c254-4226-a065-259f79739f55', '秋望寄王使君', '秋望寄王使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["靜躡紅蘭徑，憑高曠望時。","無端求句苦，永日壑風吹。","大月生峰角，殘霞在樹枝。","祗應劉越石，清嘯正相宜。"]', '["静躡紅蘭徑，憑高曠望时。","無端求句苦，永日壑风吹。","大月生峰角，殘霞在樹枝。","祗應劉越石，清嘯正相宜。"]', '诗', 'shi', '', NULL, '秋望寄王使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3acec7e-0989-4819-b308-5b2b950e0720', '送緣有禪師與雷處士入武夷山', '送緣有禪師與雷处士入武夷山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["師與雷居士，尋山道入閩。","應將熊耳印，別授武夷君。","崖𥕕仙棺出，江垠毒草分。","他年相覓在，莫苦入深雲。"]', '["師與雷居士，尋山道入閩。","應將熊耳印，別授武夷君。","崖𥕕仙棺出，江垠毒草分。","他年相覓在，莫苦入深云。"]', '诗', 'shi', '', NULL, '送緣有禪師與雷處士入武夷山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8af7dd-5c98-4550-a85f-fe712c9fe2b6', '送友生入越投知己', '送友生入越投知己', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["才大終難住，東浮景漸暄。","知將刖足恨，去擊李膺門。","宿霧開花塢，春潮入苧村。","預思秋薦後，一鶚出乾坤。"]', '["才大終难住，东浮景漸暄。","知將刖足恨，去擊李膺门。","宿霧开花塢，春潮入苧村。","預思秋薦後，一鶚出乾坤。"]', '诗', 'shi', '', NULL, '送友生入越投知己 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086f8ae0-fcf0-4896-a691-940c0ed9af92', '寄烏龍山賈泰處士', '寄烏龙山賈泰处士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["庭果色如丹，相思夕照殘。","雲邊踏燒去，月下把書看。","澗水仙居共，窗風漆樹寒。","吾君方側席，未可便懷安。"]', '["庭果色如丹，相思夕照殘。","云邊踏燒去，月下把书看。","澗水仙居共，窗风漆樹寒。","吾君方側席，未可便懷安。"]', '诗', 'shi', '', NULL, '寄烏龍山賈泰處士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e903cd38-5bef-4aaa-a44a-3d15f5112e1f', '題大安寺通禪師院', '題大安寺通禪師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["應行諸岳徧，象屣半無綱。","一法尋常說，此機仍未忘。","窗閑藤影老，衲厚瀑痕荒。","寄語迷津者，來茲問不妨。"]', '["應行諸岳徧，象屣半無綱。","一法尋常说，此機仍未忘。","窗闲藤影老，衲厚瀑痕荒。","寄語迷津者，来茲问不妨。"]', '诗', 'shi', '', NULL, '題大安寺通禪師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51c9044-4a5c-4e8c-b14e-0824e8659302', '春晚寄盧使君', '春晚寄盧使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["滿郭春如畫，空堂心自澄。","禪拋金鼎藥，詩和玉壺冰。","白雨飄花盡，晴霞向閣凝。","寂寥還得句，因寄柳吳興。"]', '["满郭春如畫，空堂心自澄。","禪拋金鼎藥，诗和玉壺冰。","白雨飄花尽，晴霞向閣凝。","寂寥還得句，因寄柳吳兴。"]', '诗', 'shi', '', NULL, '春晚寄盧使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3017902-5140-4f2b-b704-c536a55f22ee', '武昌縣與晝公兼寄邑宰', '武昌縣與晝公兼寄邑宰', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["小一何人識，騰騰天地間。","尋常如一鶴，亦不愛青山。","鐵鉢年多赤，麻衣帶毳斑。","祗聞尋五柳，時到月中還。"]', '["小一何人識，腾腾天地间。","尋常如一鹤，亦不愛青山。","鐵鉢年多赤，麻衣带毳斑。","祗闻尋五柳，时到月中還。"]', '诗', 'shi', '', NULL, '武昌縣與晝公兼寄邑宰 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b913a3-fb24-4395-a44c-a9795fd9d811', '別東林僧', '別东林僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["大士宅裏宿，芙蓉龕畔遊。","自憐□□在，子莫苦相留。","燥葉飄山席，孤雲傍茗甌。","裴回不能去，房在好峰頭。"]', '["大士宅裏宿，芙蓉龕畔游。","自怜□□在，子莫苦相留。","燥葉飄山席，孤云傍茗甌。","裴回不能去，房在好峰头。"]', '诗', 'shi', '', NULL, '別東林僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df5f97c-9dee-4e73-bcb2-956c8c82c23c', '避地寄高蟾', '避地寄高蟾', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["荒寺雨微微，空堂獨掩扉。","高吟多忤俗，此貌若爲飢。","旅夢遭鴻喚，家山被賊圍。","空餘老萊子，相見獨依依。"]', '["荒寺雨微微，空堂独掩扉。","高吟多忤俗，此貌若爲飢。","旅梦遭鴻喚，家山被賊圍。","空餘老萊子，相见独依依。"]', '诗', 'shi', '', NULL, '避地寄高蟾 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a934608-a290-4a63-bb24-9ff3cbab2041', '懷武夷山禪師', '懷武夷山禪師', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬疊仙山裏，無緣見有緣。","紅心蕉繞屋，白額虎同禪。","古木苔封菌，深崖乳雜泉。","終期還此去，世事祗如然。"]', '["万叠仙山裏，無緣见有緣。","紅心蕉繞屋，白額虎同禪。","古木苔封菌，深崖乳杂泉。","終期還此去，世事祗如然。"]', '诗', 'shi', '', NULL, '懷武夷山禪師 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d04414d4-52fb-4fec-8656-2f23daa1ccd4', '秋末閑居作', '秋末闲居作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["幽居山不別，落葉與階平。","盡日吟詩坐，無端箇病成。","徑苔因旱赤，池水入冬清。","惟有東峰叟，相尋月下行。"]', '["幽居山不別，落葉與階平。","尽日吟诗坐，無端箇病成。","徑苔因旱赤，池水入冬清。","惟有东峰叟，相尋月下行。"]', '诗', 'shi', '', NULL, '秋末閑居作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ac2cfe-b74c-4df3-ad73-ca86567911d3', '贈許徵君', '贈許徵君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["晝公友秦奚，來往踏溪雲。","如今又到我，還愛許徵君。","落花鳥銜來，永日香氤氳。","終期將爾曹，歸去麋鹿羣。"]', '["晝公友秦奚，来往踏溪云。","如今又到我，還愛許徵君。","落花鸟銜来，永日香氤氳。","終期將爾曹，归去麋鹿羣。"]', '诗', 'shi', '', NULL, '贈許徵君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8612de4-9a77-40dc-ac0c-59078aa156fb', '秋夜作因懷天台道者', '秋夜作因懷天台道者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬事何須問，良時即此時。","高秋半夜雨，落葉滿前池。","靜怕龍神識，貧從草木欺。","平生無限事，祗有道人知。"]', '["万事何須问，良时即此时。","高秋半夜雨，落葉满前池。","静怕龙神識，貧從草木欺。","平生無限事，祗有道人知。"]', '诗', 'shi', '', NULL, '秋夜作因懷天台道者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27ab0cb-2e3e-4f65-aef8-7f8d226b5492', '偶作因懷大同道友', '偶作因懷大同道友', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蠻木葉不落，微吟漳水濱。","二毛空有雪，萬事不如人。","壍水平芳草，山花落淨巾。","天童好真伴，何日更相親。"]', '["蠻木葉不落，微吟漳水濱。","二毛空有雪，万事不如人。","壍水平芳草，山花落淨巾。","天童好真伴，何日更相親。"]', '诗', 'shi', '', NULL, '偶作因懷大同道友 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('525e545e-5080-4ec2-8ea9-123c757d3df7', '邊上行', '邊上行', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["黑松林外路，風角遠嗈嗈。","朔氣生荒堡，秋塵滿病容。","豺掊沙底骨，人上月邊烽。","休作西行計，西行地漸兇。"]', '["黑松林外路，风角远嗈嗈。","朔氣生荒堡，秋塵满病容。","豺掊沙底骨，人上月邊烽。","休作西行計，西行地漸兇。"]', '诗', 'shi', '', NULL, '邊上行 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b836181-12f9-4517-9bc5-fd3ec578ed69', '江西再逢周璉', '江西再逢周璉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["六七年不見，相逢鬢已蒼。","交情終淡薄，詩語更清狂。","未得丹霄便，依前四壁荒。","但令吾道在，晚達亦何妨。"]', '["六七年不见，相逢鬢已蒼。","交情終淡薄，诗語更清狂。","未得丹霄便，依前四壁荒。","但令吾道在，晚達亦何妨。"]', '诗', 'shi', '', NULL, '江西再逢周璉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95e49cd-8338-42a1-ac92-e89688fe4b3a', '登鄱陽寺閣', '登鄱陽寺閣', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["寺樓閑縱望，不覺到斜暉。","故國在何處，多年未得歸。","寒江平楚外，細雨一鴻飛。","終斅於陵子，吳山有綠薇。"]', '["寺楼闲縱望，不覺到斜暉。","故国在何处，多年未得归。","寒江平楚外，細雨一鴻飞。","終斅於陵子，吳山有綠薇。"]', '诗', 'shi', '', NULL, '登鄱陽寺閣 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30aec185-4eff-4542-a328-d3702dcf8e54', '秋晚野居', '秋晚野居', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["僻居人不到，吾道本來孤。","山色園中有，詩魔象外無。","霜禾連島赤，煙草倚橋枯。","何必求深隱，門前似畫圖。"]', '["僻居人不到，吾道本来孤。","山色园中有，诗魔象外無。","霜禾連島赤，煙草倚橋枯。","何必求深隐，门前似畫圖。"]', '诗', 'shi', '', NULL, '秋晚野居 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13a138cd-8e8c-4334-9cc8-03c4149e2ad8', '酬杜使君見寄', '酬杜使君见寄', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["軋軋復軋軋，更深門未關。","心疼無所得，詩債若爲還。","露灑一鶴睡，鐘餘萬象閑。","慙將此時意，明日寄東山。"]', '["軋軋复軋軋，更深门未关。","心疼無所得，诗債若爲還。","露灑一鹤睡，鐘餘万象闲。","慙將此时意，明日寄东山。"]', '诗', 'shi', '', NULL, '酬杜使君見寄 貫休 shi');
